INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bRETK9Ylt63', 4, '{"title":"第400104038条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>38、咽喉燥痛，属水涸火炎，肺热之极。此证法所难治。忌、宜俱同咳嗽。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '38、咽喉燥痛，属水涸火炎，肺热之极。此证法所难治。忌、宜俱同咳嗽。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zKHU9Pz21Up', 4, '{"title":"第400104037条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>37、声哑，属肺热甚。忌、宜俱同咳嗽。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '37、声哑，属肺热甚。忌、宜俱同咳嗽。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HFazYv2vjcy', 4, '{"title":"第400104036条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>36、咳嗽吐血痰，属肺热甚。</p>\n<p>【忌】升、破气，复忌补气、破血、辛燥、温热、收涩。诸药俱见前。</p>\n<p>【宜】降气清热、润肺生津液、凉血益血、甘寒、甘平、咸寒、佐以苦寒。郁金、生地黄、蒲黄、侧柏叶、茅根、剪草、白及、阿胶、童便、知母。馀药肺虚条内参用。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '36、咳嗽吐血痰，属肺热甚。 【忌】升、破气，复忌补气、破血、辛燥、温热、收涩。诸药俱见前。 【宜】降气清热、润肺生津液、凉血益血、甘寒、甘平、咸寒、佐以苦寒。郁金、生地黄、蒲黄、侧柏叶、茅根、剪草、白及、阿胶、童便、知母。馀药肺虚条内参用。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IrfeEGsOPyR', 4, '{"title":"第400104035条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>35、齁喘，属肺虚有热，因而痰壅。</p>\n<p>【忌】破气、升、发散、收涩。诃子、亚芙蓉、粟壳（已上收涩）。馀忌药俱见前。</p>\n<p>【宜】降气、消痰、辛凉、甘寒、苦平。苏子、枇杷叶、贝母、桑根白皮、栝楼根、竹沥、天门冬、麦门冬、百部、百合、薄荷、马兜铃、款冬花、沙参、前胡、白前、射干。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104035,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '35、齁喘，属肺虚有热，因而痰壅。 【忌】破气、升、发散、收涩。诃子、亚芙蓉、粟壳（已上收涩）。馀忌药俱见前。 【宜】降气、消痰、辛凉、甘寒、苦平。苏子、枇杷叶、贝母、桑根白皮、栝楼根、竹沥、天门冬、麦门冬、百部、百合、薄荷、马兜铃、款冬花、沙参、前胡、白前、射干。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m84qDycvTNM', 4, '{"title":"第400104034条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>34、肺虚（七证）</p>\n<p>【忌】补气、升散、辛燥、温热。诸药俱见前。</p>\n<p>【宜】清热、降气、酸敛、润燥。天门冬、麦门冬、苏子、枇杷叶、贝母、沙参、百部、百合、桑白皮、五味子、杏仁、五倍子、蜜、梨、柿。无热者加：人参。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '34、肺虚（七证） 【忌】补气、升散、辛燥、温热。诸药俱见前。 【宜】清热、降气、酸敛、润燥。天门冬、麦门冬、苏子、枇杷叶、贝母、沙参、百部、百合、桑白皮、五味子、杏仁、五倍子、蜜、梨、柿。无热者加：人参。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dc4XfnhwMR8', 4, '{"title":"第400104033条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>33、痞气，属脾气虚及气郁所致。</p>\n<p>【忌】破气、下、湿润、苦寒。诸药俱见前。</p>\n<p>【宜】健脾，兼散结滞、甘温、辛香。人参、白芍药、橘红、缩砂蜜、藿香、吴茱萸、谷糵、麦糵、红曲、香附、木香。参用东垣痞气丸治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '33、痞气，属脾气虚及气郁所致。 【忌】破气、下、湿润、苦寒。诸药俱见前。 【宜】健脾，兼散结滞、甘温、辛香。人参、白芍药、橘红、缩砂蜜、藿香、吴茱萸、谷糵、麦糵、红曲、香附、木香。参用东垣痞气丸治之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qFXRwGig88j', 4, '{"title":"第400104032条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>32、脾虚腹痛，按之则止，属血虚。</p>\n<p>【忌】破气、破血、香燥、苦寒。诸药俱见前。</p>\n<p>【宜】益气补血、甘温、酸平。人参、炙甘草、龙眼肉、大枣、酸枣仁、石斛、麦门冬、白芍药。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104032,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '32、脾虚腹痛，按之则止，属血虚。 【忌】破气、破血、香燥、苦寒。诸药俱见前。 【宜】益气补血、甘温、酸平。人参、炙甘草、龙眼肉、大枣、酸枣仁、石斛、麦门冬、白芍药。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GKl2rwLUjjM', 4, '{"title":"第400104031条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>31、倦怠嗜卧，属脾气不足。</p>\n<p>【忌】破气、消导、苦寒。诸药俱见前。</p>\n<p>【宜】补气，兼健脾、甘温、辛香。人参、白术、黄耆、茯苓、薯蓣、炙甘草、谷糵、白扁豆、缩砂蜜、橘皮、藿香、白豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '31、倦怠嗜卧，属脾气不足。 【忌】破气、消导、苦寒。诸药俱见前。 【宜】补气，兼健脾、甘温、辛香。人参、白术、黄耆、茯苓、薯蓣、炙甘草、谷糵、白扁豆、缩砂蜜、橘皮、藿香、白豆蔻。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NzF805Hfl9y', 4, '{"title":"第400104030条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>30、健忘，属气血两虚。</p>\n<p>【忌】升、燥热，复忌苦寒、辛散。诸药俱见前。</p>\n<p>【宜】益脾阴，兼补气，酸敛、甘温、甘寒、辛平以通窍。酸枣仁、白芍药、五味子、人参、炙甘草、黄耆、龙眼肉、柏子仁、麦门冬、丹参、茯苓、茯神、石菖蒲、远志。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '30、健忘，属气血两虚。 【忌】升、燥热，复忌苦寒、辛散。诸药俱见前。 【宜】益脾阴，兼补气，酸敛、甘温、甘寒、辛平以通窍。酸枣仁、白芍药、五味子、人参、炙甘草、黄耆、龙眼肉、柏子仁、麦门冬、丹参、茯苓、茯神、石菖蒲、远志。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UmklFv18VqM', 4, '{"title":"第400104029条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>29、脾泄，属气虚。</p>\n<p>【忌】破气、下、消导、苦寒。诸药俱见前。</p>\n<p>【宜】温中补气、升清、甘温、甘平，佐以辛香。人参、术、炙甘草、薯蓣、莲肉、白扁豆、茯苓、车前子、白芍药、升麻、柴胡、肉豆蔻、缩砂蜜、橘皮、木香、丁香、藿香、白莱菔。兼有湿及痰，经年不愈，粪色白者，须服九制松脂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '29、脾泄，属气虚。 【忌】破气、下、消导、苦寒。诸药俱见前。 【宜】温中补气、升清、甘温、甘平，佐以辛香。人参、术、炙甘草、薯蓣、莲肉、白扁豆、茯苓、车前子、白芍药、升麻、柴胡、肉豆蔻、缩砂蜜、橘皮、木香、丁香、藿香、白莱菔。兼有湿及痰，经年不愈，粪色白者，须服九制松脂。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fd5a6WNDXm4', 4, '{"title":"第400104028条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>28、噎膈，属气血两虚，由于血液衰少，而非痰气壅逆所成。</p>\n<p>【忌】破气、升，复忌下、消导、燥、苦寒、辛热。诸药俱见前。</p>\n<p>【宜】降、清热润燥，甘温、甘平以益血，略佐辛香以顺气。苏子、橘红、枇杷叶、人参、白芍药、酸枣仁、龙眼肉、人乳、牛乳、蔗浆、梨汁、韭汁、芦根汁、姜汁、白豆蔻仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '28、噎膈，属气血两虚，由于血液衰少，而非痰气壅逆所成。 【忌】破气、升，复忌下、消导、燥、苦寒、辛热。诸药俱见前。 【宜】降、清热润燥，甘温、甘平以益血，略佐辛香以顺气。苏子、橘红、枇杷叶、人参、白芍药、酸枣仁、龙眼肉、人乳、牛乳、蔗浆、梨汁、韭汁、芦根汁、姜汁、白豆蔻仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XnbOp314foK', 4, '{"title":"第400104027条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>27、脾虚中满，属脾气虚，兼脾阴虚。</p>\n<p>【忌】破气、下、消导、利水、甘。饴糖、大枣、蜜、甘草（已上甘）。馀忌药俱见前。</p>\n<p>昼剧夜静，属脾气虚。【宜】补气键脾、甘温、淡渗，佐以辛香。人参、二术、白芍药、桑白皮、茯苓、车前子、橘红、姜皮、藿香、缩砂蜜。无热证者佐以桂。</p>\n<p>夜剧昼静，属脾阴虚。【宜】补脾阴，兼制肝清热、甘平、酸寒、淡渗。酸枣仁、白芍药、石斛、白扁豆、莲肉、橘皮、山药、苏子、五味子、木瓜、桑白皮、车前子、茯苓。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '27、脾虚中满，属脾气虚，兼脾阴虚。 【忌】破气、下、消导、利水、甘。饴糖、大枣、蜜、甘草（已上甘）。馀忌药俱见前。 昼剧夜静，属脾气虚。【宜】补气键脾、甘温、淡渗，佐以辛香。人参、二术、白芍药、桑白皮、茯苓、车前子、橘红、姜皮、藿香、缩砂蜜。无热证者佐以桂。 夜剧昼静，属脾阴虚。【宜】补脾阴，兼制肝清热、甘平、酸寒、淡渗。酸枣仁、白芍药、石斛、白扁豆、莲肉、橘皮、山药、苏子、五味子、木瓜、桑白皮、车前子、茯苓。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Onw3lm7V7gR', 4, '{"title":"第400104026条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>26、水肿，属脾气虚。</p>\n<p>【忌】破气、下泄、湿润、咸、苦寒。食盐、商陆（已上咸）。馀忌药俱见前。</p>\n<p>【宜】补脾益气、燥湿、利水、辛香、甘温，佐以淡渗。人参、二术、橘皮、薯蓣、木瓜、薏苡仁、桑白皮、茯苓、赤小豆、香薷、乌蠡鱼、车前子、猪苓、泽泻、姜皮、乌芋、缩砂蜜、通草。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '26、水肿，属脾气虚。 【忌】破气、下泄、湿润、咸、苦寒。食盐、商陆（已上咸）。馀忌药俱见前。 【宜】补脾益气、燥湿、利水、辛香、甘温，佐以淡渗。人参、二术、橘皮、薯蓣、木瓜、薏苡仁、桑白皮、茯苓、赤小豆、香薷、乌蠡鱼、车前子、猪苓、泽泻、姜皮、乌芋、缩砂蜜、通草。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FJK6EtvpsoS', 4, '{"title":"第400104025条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>25、停饮，为恣饮汤水，或冷茶、冷酒所致。</p>\n<p>【忌】下、酸敛、湿润、滞腻。诸药俱见前，加忌栝楼根及仁、桃仁、郁李仁。</p>\n<p>【宜】健脾利水、淡渗，兼辛散。人参、白术、半夏、茯苓、橘皮、泽泻、猪苓、木通、桑白皮、旋覆花、紫苏、白豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '25、停饮，为恣饮汤水，或冷茶、冷酒所致。 【忌】下、酸敛、湿润、滞腻。诸药俱见前，加忌栝楼根及仁、桃仁、郁李仁。 【宜】健脾利水、淡渗，兼辛散。人参、白术、半夏、茯苓、橘皮、泽泻、猪苓、木通、桑白皮、旋覆花、紫苏、白豆蔻。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dE1rN109SPd', 4, '{"title":"第400104024条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>24、伤食，必恶食。</p>\n<p>【忌】润湿、苦寒。当归、肉苁蓉、锁阳、天门冬、地黄、知母、玄参、猪脂、茄子、酒、糟、面食（已上湿润）。苦寒诸药见前。</p>\n<p>【宜】健脾消导、甘温、辛香。橘皮、薯蓣、莲肉、白扁豆、白芍药、白茯苓、草果、山查、麦芽、草豆蔻、缩砂蜜、谷糵。如腹痛大便不通，宜下之：枳实、槟榔、厚朴、大黄。元气虚人不可下，宜加：参、术。伤肉食，轻者宜蒜、山查，兼黄连；重者宜矾红、枣肉为丸。服二钱，不可过，终身忌荞麦。伤面食，宜炒莱菔子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '24、伤食，必恶食。 【忌】润湿、苦寒。当归、肉苁蓉、锁阳、天门冬、地黄、知母、玄参、猪脂、茄子、酒、糟、面食（已上湿润）。苦寒诸药见前。 【宜】健脾消导、甘温、辛香。橘皮、薯蓣、莲肉、白扁豆、白芍药、白茯苓、草果、山查、麦芽、草豆蔻、缩砂蜜、谷糵。如腹痛大便不通，宜下之：枳实、槟榔、厚朴、大黄。元气虚人不可下，宜加：参、术。伤肉食，轻者宜蒜、山查，兼黄连；重者宜矾红、枣肉为丸。服二钱，不可过，终身忌荞麦。伤面食，宜炒莱菔子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wjATpkN1Zim', 4, '{"title":"第400104023条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>23、饮食不消化，属脾气虚。</p>\n<p>【忌】破气、消导克伐、苦寒、复忌燥。草果、枳实、槟榔、蓬荗、三棱、绿矾（已上消导）。馀忌药见前。</p>\n<p>【宜】益真气、香、甘温、甘辛。同脾虚，加：谷糵、麦糵、肉豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '23、饮食不消化，属脾气虚。 【忌】破气、消导克伐、苦寒、复忌燥。草果、枳实、槟榔、蓬荗、三棱、绿矾（已上消导）。馀忌药见前。 【宜】益真气、香、甘温、甘辛。同脾虚，加：谷糵、麦糵、肉豆蔻。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ni2ykq6SGkO', 4, '{"title":"第400104022条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>22、饮食劳倦、伤脾发热。</p>\n<p>【忌】破气、发散、下、苦寒。诸药俱见前。</p>\n<p>【宜】补中益气、甘温、升、酸。人参、黄耆、术、炙甘草、大枣、柴胡、升麻、石斛、麦门冬、橘红、白芍药、酸枣仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '22、饮食劳倦、伤脾发热。 【忌】破气、发散、下、苦寒。诸药俱见前。 【宜】补中益气、甘温、升、酸。人参、黄耆、术、炙甘草、大枣、柴胡、升麻、石斛、麦门冬、橘红、白芍药、酸枣仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tt4PgO6kXhU', 4, '{"title":"第400104021条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>21、脾虚（十二证）</p>\n<p>【忌】下、降泄、破气、苦寒。诸药俱见前。</p>\n<p>【宜】甘温，佐以辛香、酸平。人参、大枣、黄耆、薯蓣、炙甘草、莲肉、白茯苓、白扁豆、缩砂蜜、橘红、白豆蔻、藿香、木瓜、白芍药、酸枣仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '21、脾虚（十二证） 【忌】下、降泄、破气、苦寒。诸药俱见前。 【宜】甘温，佐以辛香、酸平。人参、大枣、黄耆、薯蓣、炙甘草、莲肉、白茯苓、白扁豆、缩砂蜜、橘红、白豆蔻、藿香、木瓜、白芍药、酸枣仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D5VLoFmplER', 4, '{"title":"第400104020条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>20、肥气，属气血两虚，肝气不和，逆气与瘀血相并而成。</p>\n<p>【忌】破气、下、苦寒。诸药俱见前。</p>\n<p>【宜】和肝散结气，兼行气血凝滞、甘温、甘平。川芎、当归、沉香、干姜、肉桂、橘皮、红花、郁金、延胡索、香附、山查、赤芍药、红曲、砂仁。参用东垣肥气丸治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '20、肥气，属气血两虚，肝气不和，逆气与瘀血相并而成。 【忌】破气、下、苦寒。诸药俱见前。 【宜】和肝散结气，兼行气血凝滞、甘温、甘平。川芎、当归、沉香、干姜、肉桂、橘皮、红花、郁金、延胡索、香附、山查、赤芍药、红曲、砂仁。参用东垣肥气丸治之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fLJU2F4Ne1p', 4, '{"title":"第400104019条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>19、目黑黯、眩晕，属血虚，兼肾水真阴不足。</p>\n<p>【忌】破气、燥、热、辛温。诸药俱见前。</p>\n<p>【宜】养血补肝、清热、甘寒、甘平、酸寒、苦寒。生地黄、枸杞子、甘菊花、当归、薯蓣、五味子、白蒺藜、甘草、山茱萸、白芍药、天门冬、黄檗。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '19、目黑黯、眩晕，属血虚，兼肾水真阴不足。 【忌】破气、燥、热、辛温。诸药俱见前。 【宜】养血补肝、清热、甘寒、甘平、酸寒、苦寒。生地黄、枸杞子、甘菊花、当归、薯蓣、五味子、白蒺藜、甘草、山茱萸、白芍药、天门冬、黄檗。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ethFy7Raq4t', 4, '{"title":"第400104018条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>18、偏头痛，属血虚、肝家有热，不急治，久之必损目。</p>\n<p>【忌】升、燥、热、苦寒。诸药俱见前。</p>\n<p>【宜】养血清虚热、甘寒、酸寒、辛寒。生地黄、天门冬、甘菊花、白芍药、当归、川芎、乌梅、炙甘草、土茯苓、金银藤、黑豆。有实火者可加：黄芩（酒炒）、大黄（酒蒸）、芎、雨前茶、石膏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '18、偏头痛，属血虚、肝家有热，不急治，久之必损目。 【忌】升、燥、热、苦寒。诸药俱见前。 【宜】养血清虚热、甘寒、酸寒、辛寒。生地黄、天门冬、甘菊花、白芍药、当归、川芎、乌梅、炙甘草、土茯苓、金银藤、黑豆。有实火者可加：黄芩（酒炒）、大黄（酒蒸）、芎、雨前茶、石膏。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zmupU4zNRu9', 4, '{"title":"第400104017条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>17、少腹连阴作痛、按之则止，属足厥阴经血虚。</p>\n<p>【忌】同角弓反张。</p>\n<p>【宜】同角弓反张，加：白胶。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '17、少腹连阴作痛、按之则止，属足厥阴经血虚。 【忌】同角弓反张。 【宜】同角弓反张，加：白胶。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O51LN4OPq88', 4, '{"title":"第400104016条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>16、亡血过多，角弓反张，属肝血虚有热。</p>\n<p>【忌】风燥、升、破气、下。诸药俱见前。</p>\n<p>【宜】补血清热、甘寒、甘温、酸寒、咸寒、辛润。当归、生地黄、白芍药、炙甘草、牛膝、麦门冬、牡丹皮、甘菊花、童便。有汗加：人参、黄耆、五味子、酸枣仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '16、亡血过多，角弓反张，属肝血虚有热。 【忌】风燥、升、破气、下。诸药俱见前。 【宜】补血清热、甘寒、甘温、酸寒、咸寒、辛润。当归、生地黄、白芍药、炙甘草、牛膝、麦门冬、牡丹皮、甘菊花、童便。有汗加：人参、黄耆、五味子、酸枣仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w9kKdUoDagD', 4, '{"title":"第400104015条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>15、目翳，属肝热，兼肾水不足。</p>\n<p>【忌】破气、升、燥热、苦寒。诸药俱见前。</p>\n<p>【宜】补肝血、除热、退翳。甘菊花、生地黄、决明子、石决明、沙苑蒺藜、女贞实、青羊胆、羚羊角、犀角、空青、黄连、天龙、伏翼粪、木贼、谷精草、蜜蒙花、人爪、蝉蜕、玛瑙、石蟹、珊瑚、真珠、琥珀、马目毒公、贝子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '15、目翳，属肝热，兼肾水不足。 【忌】破气、升、燥热、苦寒。诸药俱见前。 【宜】补肝血、除热、退翳。甘菊花、生地黄、决明子、石决明、沙苑蒺藜、女贞实、青羊胆、羚羊角、犀角、空青、黄连、天龙、伏翼粪、木贼、谷精草、蜜蒙花、人爪、蝉蜕、玛瑙、石蟹、珊瑚、真珠、琥珀、马目毒公、贝子。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('taYBeafRi2A', 4, '{"title":"第400104014条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>14、目昏，属肝血虚有热，兼肾水真阴不足。</p>\n<p>【忌】同前目光短。</p>\n<p>【宜】同目光短，加：黄檗、羚羊角。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '14、目昏，属肝血虚有热，兼肾水真阴不足。 【忌】同前目光短。 【宜】同目光短，加：黄檗、羚羊角。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m1VgWIq0ovc', 4, '{"title":"第400104013条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>13、目光短，属肝血虚，及肾水真阴不足。</p>\n<p>【忌】破气、升、燥、热。诸药俱见前。</p>\n<p>【宜】补肝兼滋肾、甘温益血、甘寒除热。甘枸杞、生地黄、甘菊花、沙苑蒺藜、谷精草、五味子、决明子、天门冬、麦门冬。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '13、目光短，属肝血虚，及肾水真阴不足。 【忌】破气、升、燥、热。诸药俱见前。 【宜】补肝兼滋肾、甘温益血、甘寒除热。甘枸杞、生地黄、甘菊花、沙苑蒺藜、谷精草、五味子、决明子、天门冬、麦门冬。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('15kWN0797op', 4, '{"title":"第400104012条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>12、转筋，属血虚。</p>\n<p>【忌】下，复忌升、燥热、闭气、苦寒、破气。二术、黄耆、银杏、猪脂、羊肉、面（已上闭气）。馀忌药俱见前。</p>\n<p>【宜】酸、辛、甘平。木瓜、牛膝、当归身、白芍药、石斛、续断、炙甘草、陈皮、缩砂蜜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '12、转筋，属血虚。 【忌】下，复忌升、燥热、闭气、苦寒、破气。二术、黄耆、银杏、猪脂、羊肉、面（已上闭气）。馀忌药俱见前。 【宜】酸、辛、甘平。木瓜、牛膝、当归身、白芍药、石斛、续断、炙甘草、陈皮、缩砂蜜。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3AtgIb4XMLZ', 4, '{"title":"第400104011条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>11、胸胁痛，属肝血虚，肝气实，因而上逆。</p>\n<p>【忌】敛、补气、破血。诸药俱见前。</p>\n<p>【宜】降气、养血和肝、辛甘、平缓。苏子、郁金、番降香、川通草、当归、生地黄、橘皮、甘草、白芍药、续断、鹿角胶。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '11、胸胁痛，属肝血虚，肝气实，因而上逆。 【忌】敛、补气、破血。诸药俱见前。 【宜】降气、养血和肝、辛甘、平缓。苏子、郁金、番降香、川通草、当归、生地黄、橘皮、甘草、白芍药、续断、鹿角胶。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TQo472MyoDh', 4, '{"title":"第400104010条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>10、肝虚（十证）</p>\n<p>【忌】收敛、破气、升散、苦寒、下。诸药俱见前。</p>\n<p>【宜】辛散、甘缓。当归、陈皮、生姜、地黄、甘菊、甘草、胡麻、谷精草、决明子、刺蒺藜、羊牛兔肝。因郁而虚者，加：细辛、木香、缩砂蜜、沉木香、川芎、香附。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '10、肝虚（十证） 【忌】收敛、破气、升散、苦寒、下。诸药俱见前。 【宜】辛散、甘缓。当归、陈皮、生姜、地黄、甘菊、甘草、胡麻、谷精草、决明子、刺蒺藜、羊牛兔肝。因郁而虚者，加：细辛、木香、缩砂蜜、沉木香、川芎、香附。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ah6TBmtkK5v', 4, '{"title":"第400104009条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>9、伏梁，属心经气血虚，以致邪留不去。</p>\n<p>【忌】破血、汗、下。三棱、蓬荗、姜黄、虻虫、䗪虫、红蓝花、水蛭、桃仁（已上破血）。汗、下诸药俱见前。</p>\n<p>【宜】活血、凉血、散热通结、辛咸。郁金、五灵脂、乳香、没药、当归、延胡索、赤芍药、远志、菖蒲、茯神、牡蛎。参用东垣伏梁丸治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '9、伏梁，属心经气血虚，以致邪留不去。 【忌】破血、汗、下。三棱、蓬荗、姜黄、虻虫、䗪虫、红蓝花、水蛭、桃仁（已上破血）。汗、下诸药俱见前。 【宜】活血、凉血、散热通结、辛咸。郁金、五灵脂、乳香、没药、当归、延胡索、赤芍药、远志、菖蒲、茯神、牡蛎。参用东垣伏梁丸治之。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6b71brToA1s', 4, '{"title":"第400104008条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>8、盗汗，属心血虚。汗者，心之液也。</p>\n<p>【忌】破气、辛散、燥热。诸药俱见前。</p>\n<p>【宜】补敛、清虚热、甘酸、甘平、甘寒、苦寒、咸寒。生地黄、当归、茯神、龙眼肉、黄耆、五味子、白芍药、酸枣仁、黄芩、黄檗、黄连、牡蛎。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '8、盗汗，属心血虚。汗者，心之液也。 【忌】破气、辛散、燥热。诸药俱见前。 【宜】补敛、清虚热、甘酸、甘平、甘寒、苦寒、咸寒。生地黄、当归、茯神、龙眼肉、黄耆、五味子、白芍药、酸枣仁、黄芩、黄檗、黄连、牡蛎。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8uVWtWdp3Dr', 4, '{"title":"第400104007条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>7、心澹澹动。忌、宜俱同心虚。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '7、心澹澹动。忌、宜俱同心虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G55sdKlYWJJ', 4, '{"title":"第400104006条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>6、怔忡，属心血不足。忌、宜俱同心虚。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '6、怔忡，属心血不足。忌、宜俱同心虚。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1hUUJcz7a5f', 4, '{"title":"第400104005条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>5、不得眠，属心血虚有热。</p>\n<p>【忌】升、辛燥、热。诸药俱见前。</p>\n<p>【宜】敛、养阴血、清热。酸枣仁、五味子、龙眼肉、丹参、芍药、人参、石斛、竹叶、生地黄、茯神、远志、黄连、玄参、麦门冬、辰砂六一散、竹茹、木通、生甘草。</p>\n<p>心烦，属心家有热。</p>\n<p>【忌】升、破气、燥热。诸药俱见前。</p>\n<p>【宜】清热、生津液、甘寒、甘平、辛酸。参用不得眠中诸药：竹叶、麦门冬、生甘草、石斛、丹参、龙眼肉、生地黄、玄参、沙参、茯神、远志、知母、酸枣仁。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '5、不得眠，属心血虚有热。 【忌】升、辛燥、热。诸药俱见前。 【宜】敛、养阴血、清热。酸枣仁、五味子、龙眼肉、丹参、芍药、人参、石斛、竹叶、生地黄、茯神、远志、黄连、玄参、麦门冬、辰砂六一散、竹茹、木通、生甘草。 心烦，属心家有热。 【忌】升、破气、燥热。诸药俱见前。 【宜】清热、生津液、甘寒、甘平、辛酸。参用不得眠中诸药：竹叶、麦门冬、生甘草、石斛、丹参、龙眼肉、生地黄、玄参、沙参、茯神、远志、知母、酸枣仁。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZdmmYRDqkbU', 4, '{"title":"第400104004条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>4、癫痫，属心气虚有热。</p>\n<p>【忌】补敛、升。诸药俱见前。</p>\n<p>【宜】降、清热、豁痰。诸药见惊邪条，加：贝母、丹参、钓藤钩、郁金、铅丹、神水、白矾。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '4、癫痫，属心气虚有热。 【忌】补敛、升。诸药俱见前。 【宜】降、清热、豁痰。诸药见惊邪条，加：贝母、丹参、钓藤钩、郁金、铅丹、神水、白矾。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BnhH3N5dQ70', 4, '{"title":"第400104003条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>3、惊邪，属心气虚。</p>\n<p>【忌】升、破气。诸药俱见前。</p>\n<p>【宜】降、清热、豁痰、平。《经》曰：惊者平之。犀角、丹砂、琥珀、真珠、龙齿、金箔、牛黄、代赭石、羚羊角、麦门冬、石斛、桔梗、胆星、麝香、竹沥、天竺黄、远志、鬼臼。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '2024-12-23T03:22:16.000Z', '3、惊邪，属心气虚。 【忌】升、破气。诸药俱见前。 【宜】降、清热、豁痰、平。《经》曰：惊者平之。犀角、丹砂、琥珀、真珠、龙齿、金箔、牛黄、代赭石、羚羊角、麦门冬、石斛、桔梗、胆星、麝香、竹沥、天竺黄、远志、鬼臼。', '2024-12-23T03:22:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pHlhZlpAJg6', 4, '{"title":"第400104142条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>142、赤白游风，属血热，热则生风，故善游走，俗名火丹。小儿多患此，大人亦时有之。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】清热、凉血，兼行血、辛寒、甘寒、苦寒、咸寒。生地黄、黄连、黄檗、生甘草、牡丹皮、蒲黄、红蓝花、连翘、玄参、鼠粘子、牛膝、蓝汁、苎根、童便、赤芍药。宜兼外治，砭出热血，及用漆姑草、慎火草捣烂敷之，即易愈。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104142,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '142、赤白游风，属血热，热则生风，故善游走，俗名火丹。小儿多患此，大人亦时有之。 【忌】同三焦实。 【宜】清热、凉血，兼行血、辛寒、甘寒、苦寒、咸寒。生地黄、黄连、黄檗、生甘草、牡丹皮、蒲黄、红蓝花、连翘、玄参、鼠粘子、牛膝、蓝汁、苎根、童便、赤芍药。宜兼外治，砭出热血，及用漆姑草、慎火草捣烂敷之，即易愈。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RWKQG1CRvei', 4, '{"title":"第400104141条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>141、头面赤热，属上焦火升。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】降、清热、甘缓，佐以酸敛。苏子、枇杷叶、天门冬、麦门冬、玄参、薄荷、栝楼根、梨、柿、蔗、童便、白芍药、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104141,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '141、头面赤热，属上焦火升。 【忌】同三焦实。 【宜】降、清热、甘缓，佐以酸敛。苏子、枇杷叶、天门冬、麦门冬、玄参、薄荷、栝楼根、梨、柿、蔗、童便、白芍药、五味子。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tf041yZfDm6', 4, '{"title":"第400104140条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>140、喉痹，即缠喉风。属少阳相火、少阴君火并炽。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也。一阳者，少阳相火也。</p>\n<p>【忌】同三焦实。</p>\n<p>【宜】辛散，佐以苦寒、咸寒。急则有针法、吹法、吐法。鼠粘子、山豆根、射干、黄连、黄檗、知母、玄参、童便、苏子、麦门冬、贝母、甘草、生犀角、山慈菇、苦桔梗、续随子。急治用胆矾、朴硝、牛黄为末，和匀吹入喉中。又法：用明矾三钱、巴豆七粒去壳，同矾煅，矾枯，去巴豆，即取矾为细末，吹入喉中，流出热涎即宽。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104140,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '140、喉痹，即缠喉风。属少阳相火、少阴君火并炽。《经》曰：一阴一阳结为喉痹。一阴者，少阴君火也。一阳者，少阳相火也。 【忌】同三焦实。 【宜】辛散，佐以苦寒、咸寒。急则有针法、吹法、吐法。鼠粘子、山豆根、射干、黄连、黄檗、知母、玄参、童便、苏子、麦门冬、贝母、甘草、生犀角、山慈菇、苦桔梗、续随子。急治用胆矾、朴硝、牛黄为末，和匀吹入喉中。又法：用明矾三钱、巴豆七粒去壳，同矾煅，矾枯，去巴豆，即取矾为细末，吹入喉中，流出热涎即宽。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zh9z2nD2sI0', 4, '{"title":"第400104139条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>139、三焦实（三证）</p>\n<p>【忌】补敛、升、燥热。诸药俱见前。</p>\n<p>【宜】降、清热、调气、甘寒、苦寒、咸寒。苏子、麦门冬、知母、黄檗、玄参、山栀、黄芩、黄连、童便。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104139,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '139、三焦实（三证） 【忌】补敛、升、燥热。诸药俱见前。 【宜】降、清热、调气、甘寒、苦寒、咸寒。苏子、麦门冬、知母、黄檗、玄参、山栀、黄芩、黄连、童便。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a7X8LXkk8B2', 4, '{"title":"第400104138条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>138、膀胱实（一证）</p>\n<p>【忌】燥、热、收涩。诸药俱见前。</p>\n<p>【宜】润、淡渗。知母、黄檗、车前子、木通、瞿麦、滑石、茯苓、猪苓、泽泻。</p>\n<p>癃闭，属膀胱实热。</p>\n<p>【忌】破气、发散、燥、热。如属水液不足，兼忌利小便。诸药俱见前。</p>\n<p>【宜】同膀胱实，佐以升提。升麻、柴胡。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104138,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '138、膀胱实（一证） 【忌】燥、热、收涩。诸药俱见前。 【宜】润、淡渗。知母、黄檗、车前子、木通、瞿麦、滑石、茯苓、猪苓、泽泻。 癃闭，属膀胱实热。 【忌】破气、发散、燥、热。如属水液不足，兼忌利小便。诸药俱见前。 【宜】同膀胱实，佐以升提。升麻、柴胡。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1F0s2PUp5Sx', 4, '{"title":"第400104137条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>137、肠痈，属大肠实火。</p>\n<p>【忌】同肠风下血。</p>\n<p>【宜】下、苦寒、解毒。大黄、白药子、白芷、白及、白敛、连翘、忍冬藤、天明精、甘草、黄耆、生地黄、明矾、黄蜡、生蜜（已上三味作丸）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104137,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '137、肠痈，属大肠实火。 【忌】同肠风下血。 【宜】下、苦寒、解毒。大黄、白药子、白芷、白及、白敛、连翘、忍冬藤、天明精、甘草、黄耆、生地黄、明矾、黄蜡、生蜜（已上三味作丸）。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eeye2Rq1ICN', 4, '{"title":"第400104136条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>136、脏毒，属血热。</p>\n<p>【忌】同肠风下血。</p>\n<p>【宜】同肠风下血，加：忍冬、麦门冬、倍加地榆、蒲黄。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104136,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '136、脏毒，属血热。 【忌】同肠风下血。 【宜】同肠风下血，加：忍冬、麦门冬、倍加地榆、蒲黄。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TavkCjvCDxz', 4, '{"title":"第400104135条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>135、肠风下血，属大肠湿热。</p>\n<p>【忌】下、燥、热。诸药俱见前。</p>\n<p>【宜】清热凉血、兼升、甘寒、苦寒。生地黄、槐花、地榆、黄连、黄芩、荆芥、防风、甘草、红曲、白芍药、侧柏叶、白头翁、蒲黄、鸡子、葛谷。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104135,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '135、肠风下血，属大肠湿热。 【忌】下、燥、热。诸药俱见前。 【宜】清热凉血、兼升、甘寒、苦寒。生地黄、槐花、地榆、黄连、黄芩、荆芥、防风、甘草、红曲、白芍药、侧柏叶、白头翁、蒲黄、鸡子、葛谷。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m78VHkW2eKk', 4, '{"title":"第400104134条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>134、便硬闭。</p>\n<p>【忌】同大肠实。</p>\n<p>【宜】同大肠实，加：芒硝、猪胆、槟榔、郁李仁、石蜜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104134,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '134、便硬闭。 【忌】同大肠实。 【宜】同大肠实，加：芒硝、猪胆、槟榔、郁李仁、石蜜。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yddpRP51biz', 4, '{"title":"第400104133条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>133、大肠实（四证）</p>\n<p>【忌】补敛、燥、热。诸药俱见前。</p>\n<p>【宜】润下、苦寒、辛寒。生地黄、麻仁、桃仁、黄连、黄芩、槐花、大黄、石膏、知母、枳壳。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104133,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '133、大肠实（四证） 【忌】补敛、燥、热。诸药俱见前。 【宜】润下、苦寒、辛寒。生地黄、麻仁、桃仁、黄连、黄芩、槐花、大黄、石膏、知母、枳壳。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lJiJ5nOn66a', 4, '{"title":"第400104132条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>132、吞酸，属胃火。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同嘈杂。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104132,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '132、吞酸，属胃火。 【忌】同胃实。 【宜】同嘈杂。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('278IyIFE5e2', 4, '{"title":"第400104131条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>131、呕吐，属胃火者，必面赤，小便短赤或涩，大便多燥，口苦或干渴。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同胃实，加：枇杷叶、竹茹、木瓜、芦根、橘皮、通草、白茯苓。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104131,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '131、呕吐，属胃火者，必面赤，小便短赤或涩，大便多燥，口苦或干渴。 【忌】同胃实。 【宜】同胃实，加：枇杷叶、竹茹、木瓜、芦根、橘皮、通草、白茯苓。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('joXnre4v0TE', 4, '{"title":"第400104130条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>130、口淡，属胃热。忌、宜俱同口臭。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104130,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '130、口淡，属胃热。忌、宜俱同口臭。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kpg6hqss70m', 4, '{"title":"第400104129条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>129、嘈杂，属胃火。</p>\n<p>【忌】同口臭。</p>\n<p>【宜】同口臭，略兼消导。山查、麦芽、橘红、神曲。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104129,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '129、嘈杂，属胃火。 【忌】同口臭。 【宜】同口臭，略兼消导。山查、麦芽、橘红、神曲。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2MdLSIIRofH', 4, '{"title":"第400104128条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>128、口臭，数欲饮食，属胃火。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】清热降火、苦寒、甘寒、辛寒。黄连、青黛、连翘、麦门冬、石斛、芦根汁、竹叶、石膏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104128,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '128、口臭，数欲饮食，属胃火。 【忌】同胃实。 【宜】清热降火、苦寒、甘寒、辛寒。黄连、青黛、连翘、麦门冬、石斛、芦根汁、竹叶、石膏。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TKdKYZa8hg7', 4, '{"title":"第400104127条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>127、谵语发狂、发斑，弃衣而走，登高而歌，属胃家邪热实。</p>\n<p>【忌】同胃实。</p>\n<p>【宜】同胃实。如大便结者，加芒硝，亟下之；发斑者，加鼠粘子、玄参、栝楼根，多用石膏为君。便结亦加大黄下之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104127,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '127、谵语发狂、发斑，弃衣而走，登高而歌，属胃家邪热实。 【忌】同胃实。 【宜】同胃实。如大便结者，加芒硝，亟下之；发斑者，加鼠粘子、玄参、栝楼根，多用石膏为君。便结亦加大黄下之。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ex3DjFcIg6w', 4, '{"title":"第400104126条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>126、胃实（六证）</p>\n<p>【忌】升、补敛、辛温、燥、热、湿润。诸药俱见前。</p>\n<p>【宜】下。如邪未结，宜清热发散、苦寒、辛寒、甘寒。大黄、枳实、知母、石膏、葛根、竹叶、大青、小青、青黛、麦冬、甘草。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104126,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '126、胃实（六证） 【忌】升、补敛、辛温、燥、热、湿润。诸药俱见前。 【宜】下。如邪未结，宜清热发散、苦寒、辛寒、甘寒。大黄、枳实、知母、石膏、葛根、竹叶、大青、小青、青黛、麦冬、甘草。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QS7TRK8B09Z', 4, '{"title":"第400104125条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>125、鼻渊，属胆移热于脑。</p>\n<p>【忌】辛温、燥、热。诸药俱见前。</p>\n<p>【宜】清热、补脑、甘寒、甘平、佐以辛寒。天门冬、甘菊花、生地黄、沙苑蒺藜、山茱萸、沙参、薄荷、柴胡、辛夷、黄芩、玄参、知母。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104125,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '125、鼻渊，属胆移热于脑。 【忌】辛温、燥、热。诸药俱见前。 【宜】清热、补脑、甘寒、甘平、佐以辛寒。天门冬、甘菊花、生地黄、沙苑蒺藜、山茱萸、沙参、薄荷、柴胡、辛夷、黄芩、玄参、知母。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8bko2v9pxKr', 4, '{"title":"第400104124条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>124、口苦耳聋胁痛，往来寒热。</p>\n<p>【忌】同胆实。</p>\n<p>【宜】用仲景小柴胡汤，随所见兼证加减。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104124,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '124、口苦耳聋胁痛，往来寒热。 【忌】同胆实。 【宜】用仲景小柴胡汤，随所见兼证加减。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iANCJRGzI2H', 4, '{"title":"第400104123条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>123、胆实（二证）</p>\n<p>【忌】汗、吐、下。诸药俱见前。</p>\n<p>【宜】和解、辛寒、甘寒、苦寒、辛温。柴胡、黄芩、半夏、生姜、甘草、橘皮、龙胆草。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104123,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '123、胆实（二证） 【忌】汗、吐、下。诸药俱见前。 【宜】和解、辛寒、甘寒、苦寒、辛温。柴胡、黄芩、半夏、生姜、甘草、橘皮、龙胆草。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('inI7scSfX4F', 4, '{"title":"第400104122条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>122、小肠实（一证）</p>\n<p>【忌】敛涩、补气。诸药俱见前。</p>\n<p>【宜】通利、淡渗、苦寒、甘寒、咸寒。车前子、白茯苓、木通、生甘草、黄檗、知母、黄芩、黄连、牛膝、麦门冬、生地黄、童溺。</p>\n<p>小水不利，及赤、或涩痛尿血。忌、宜俱同小肠实。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104122,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '122、小肠实（一证） 【忌】敛涩、补气。诸药俱见前。 【宜】通利、淡渗、苦寒、甘寒、咸寒。车前子、白茯苓、木通、生甘草、黄檗、知母、黄芩、黄连、牛膝、麦门冬、生地黄、童溺。 小水不利，及赤、或涩痛尿血。忌、宜俱同小肠实。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q7eL1z7mIMu', 4, '{"title":"第400104121条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>121、水窍涩痛，属命门实火。</p>\n<p>【忌】同命门实。</p>\n<p>【宜】清热、利窍、甘寒、苦寒、咸寒，佐以淡渗。黄檗、知母、车前子、生地黄、天门冬、生甘草、黄芩、牛膝、麦门冬、童便、茯苓、木通。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104121,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '121、水窍涩痛，属命门实火。 【忌】同命门实。 【宜】清热、利窍、甘寒、苦寒、咸寒，佐以淡渗。黄檗、知母、车前子、生地黄、天门冬、生甘草、黄芩、牛膝、麦门冬、童便、茯苓、木通。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5tJXteS7v1h', 4, '{"title":"第400104120条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>120、强阳不倒，属命门火实，孤阳无阴所致。此证多不治。</p>\n<p>【忌】同命门实。</p>\n<p>【宜】同命门实，加：五味子、童便、生地黄。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104120,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '120、强阳不倒，属命门火实，孤阳无阴所致。此证多不治。 【忌】同命门实。 【宜】同命门实，加：五味子、童便、生地黄。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R0k05BSXnkO', 4, '{"title":"第400104119条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>119、命门实（二证）</p>\n<p>【忌】补气、温、热。诸药俱见前。</p>\n<p>【宜】苦寒、甘寒、咸寒。黄檗、知母、玄参、天门冬、麦门冬、牡丹皮、车前子、木通、泽泻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104119,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '119、命门实（二证） 【忌】补气、温、热。诸药俱见前。 【宜】苦寒、甘寒、咸寒。黄檗、知母、玄参、天门冬、麦门冬、牡丹皮、车前子、木通、泽泻。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N4lHqj8vtXp', 4, '{"title":"第400104118条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>118、肾无实，故无泻法。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104118,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '118、肾无实，故无泻法。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FA7B8bbgKjm', 4, '{"title":"第400104117条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>117、上消，属肺家实火，及上焦热。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】降气、清热、补肺、生津、甘寒、苦寒、酸寒、辛寒。苏子、麦门冬、枇杷叶、桑白皮、桔梗、百部、百合、黄芩、天门冬、沙参、黄连、栝楼根、葛根、知母、玄参、石膏、甘草、五味子、白芍药、䈽竹叶、芦根、冬瓜、人乳、天酒。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104117,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '117、上消，属肺家实火，及上焦热。 【忌】同肺实。 【宜】降气、清热、补肺、生津、甘寒、苦寒、酸寒、辛寒。苏子、麦门冬、枇杷叶、桑白皮、桔梗、百部、百合、黄芩、天门冬、沙参、黄连、栝楼根、葛根、知母、玄参、石膏、甘草、五味子、白芍药、䈽竹叶、芦根、冬瓜、人乳、天酒。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lVwf6dr7pa3', 4, '{"title":"第400104116条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>116、喉癣，属肺热。</p>\n<p>【忌】同肺热。</p>\n<p>【宜】同肺实，加：鼠粘子、玄参、射干。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104116,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '116、喉癣，属肺热。 【忌】同肺热。 【宜】同肺实，加：鼠粘子、玄参、射干。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wfNZlkUAviV', 4, '{"title":"第400104115条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>115、吐脓血、血痰，咳嗽嗽血，属肺家火实热甚。此正 “邪气胜则实” 之谓。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】清热降气、凉血、豁痰。童便、苏子、枇杷叶、桑白皮、麦门冬、剪草、蒲黄、生地黄、天门冬、百部、桑黄、百合、薏苡仁、甘草、贝母、白芍药、白及、梧梗、款冬花、紫菀。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104115,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '115、吐脓血、血痰，咳嗽嗽血，属肺家火实热甚。此正 “邪气胜则实” 之谓。 【忌】同肺实。 【宜】清热降气、凉血、豁痰。童便、苏子、枇杷叶、桑白皮、麦门冬、剪草、蒲黄、生地黄、天门冬、百部、桑黄、百合、薏苡仁、甘草、贝母、白芍药、白及、梧梗、款冬花、紫菀。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
