INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5jzu1yGg14E', 4, '{"title":"第400104110条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>110、喘急，属肺有实热，及肺气上逆。</p>\n<p>【忌】同肺实。</p>\n<p>【宜】同肺实，加：桔梗、甘草、栝楼仁、玄参、青黛。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104110,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '110、喘急，属肺有实热，及肺气上逆。 【忌】同肺实。 【宜】同肺实，加：桔梗、甘草、栝楼仁、玄参、青黛。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('prxnWSbQa5v', 4, '{"title":"第400104109条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>109、肺实（八证）</p>\n<p>【忌】敛涩、补气、升、燥热、酸、咸。诸药俱见前。</p>\n<p>【宜】降气、润、甘寒、苦寒，佐以辛散。苏子、枇杷叶、桑白皮、天门冬、贝母、栝楼根、杏仁、白前、前胡、知母、车前子、桑黄、石膏、黄芩。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104109,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '109、肺实（八证） 【忌】敛涩、补气、升、燥热、酸、咸。诸药俱见前。 【宜】降气、润、甘寒、苦寒，佐以辛散。苏子、枇杷叶、桑白皮、天门冬、贝母、栝楼根、杏仁、白前、前胡、知母、车前子、桑黄、石膏、黄芩。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qXZMRnq2eHE', 4, '{"title":"第400104108条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>108、湿热腹痛，按之愈甚。</p>\n<p>【忌】闷气、酸敛、温热、燥。诸药俱见前。</p>\n<p>【宜】利小便，兼升提、苦寒。滑石、车前子、木通、黄连、黄芩、升麻、柴胡、葛根、防风。不愈加熟大黄，即 “土郁则夺之” 之义也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104108,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '108、湿热腹痛，按之愈甚。 【忌】闷气、酸敛、温热、燥。诸药俱见前。 【宜】利小便，兼升提、苦寒。滑石、车前子、木通、黄连、黄芩、升麻、柴胡、葛根、防风。不愈加熟大黄，即 “土郁则夺之” 之义也。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MIZ19sMwfby', 4, '{"title":"第400104107条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>107、中消，属脾家实火。</p>\n<p>【忌】破气、下、温燥、热。诸药俱见前。</p>\n<p>【宜】服诸药同口唇生疮，加人参。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '107、中消，属脾家实火。 【忌】破气、下、温燥、热。诸药俱见前。 【宜】服诸药同口唇生疮，加人参。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bTCBsZpWgA0', 4, '{"title":"第400104106条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>106、口糜。忌、宜俱同口唇生疮。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '106、口糜。忌、宜俱同口唇生疮。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SyndJBFliXA', 4, '{"title":"第400104105条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>105、口唇生疮。</p>\n<p>【忌】温燥、热。诸药俱见前。</p>\n<p>【宜】甘寒、酸寒、苦寒、辛寒。麦门冬、生地黄、甘草、白芍药、乌梅、黄连、黄檗、玄参、连翘、栝楼根、干葛、石膏、龙胆草、大青、竹叶。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '105、口唇生疮。 【忌】温燥、热。诸药俱见前。 【宜】甘寒、酸寒、苦寒、辛寒。麦门冬、生地黄、甘草、白芍药、乌梅、黄连、黄檗、玄参、连翘、栝楼根、干葛、石膏、龙胆草、大青、竹叶。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DPaRIliaOAa', 4, '{"title":"第400104104条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>104、易饥，属脾家邪火。</p>\n<p>【忌】升、辛易、大热、香燥。沉香、麝香、龙脑、缩砂蜜、豆蔻、藿香（已上香燥）。馀忌药俱见前。</p>\n<p>【宜】清火除热、生津液、益脾阴、甘寒、苦寒、酸寒。黄连、青黛、连翘、山栀、石膏、竹叶、麦冬、石斛、白芍药、酸枣仁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104104,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '104、易饥，属脾家邪火。 【忌】升、辛易、大热、香燥。沉香、麝香、龙脑、缩砂蜜、豆蔻、藿香（已上香燥）。馀忌药俱见前。 【宜】清火除热、生津液、益脾阴、甘寒、苦寒、酸寒。黄连、青黛、连翘、山栀、石膏、竹叶、麦冬、石斛、白芍药、酸枣仁。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h00Y5f9kjqU', 4, '{"title":"第400104103条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>103、蛊胀，由于脾家湿热积滞，或内伤瘀血停积而成。</p>\n<p>【忌】补气、甘温、燥热。诸药俱见前。</p>\n<p>【宜】除湿、清热、利小便、消积。木通、防己、车前子、猪苓、泽泻、茯苓、葶苈、乌蠡鱼、桑白皮、山查、红曲、三棱、蓬术。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104103,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '103、蛊胀，由于脾家湿热积滞，或内伤瘀血停积而成。 【忌】补气、甘温、燥热。诸药俱见前。 【宜】除湿、清热、利小便、消积。木通、防己、车前子、猪苓、泽泻、茯苓、葶苈、乌蠡鱼、桑白皮、山查、红曲、三棱、蓬术。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('55tvEbdRYww', 4, '{"title":"第400104102条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>102、脾实（六证）</p>\n<p>即湿热邪胜。</p>\n<p>【忌】湿润、收涩、滞腻、热、咸、甘。诸药俱见前。</p>\n<p>【宜】除湿清热、利小便、辛散、风燥、苦寒。术、山栀、猪苓、泽泻、滑石、车前子、茯苓、白豆蔻、防风、干葛、黄连、枳实。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '102、脾实（六证） 即湿热邪胜。 【忌】湿润、收涩、滞腻、热、咸、甘。诸药俱见前。 【宜】除湿清热、利小便、辛散、风燥、苦寒。术、山栀、猪苓、泽泻、滑石、车前子、茯苓、白豆蔻、防风、干葛、黄连、枳实。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u47pD4TJy2Q', 4, '{"title":"第400104101条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>101、目赤肿痛，属血热。</p>\n<p>【忌】同肝实善怒。</p>\n<p>【宜】凉血清热、甘寒、苦寒、酸寒。生地黄、赤芍药、甘草、甘菊、谷精草、蜜蒙花、荆芥、黄檗、大黄、黄连、连翘、玄参、山栀、竹叶、龙胆草、空青、曾青、木通、童便。外治：铜青、芒硝、石胆、蕤核。急者宜以三棱针刺破眼眶肿处，捋出热血，立解。迟则血贯瞳人，目损矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '101、目赤肿痛，属血热。 【忌】同肝实善怒。 【宜】凉血清热、甘寒、苦寒、酸寒。生地黄、赤芍药、甘草、甘菊、谷精草、蜜蒙花、荆芥、黄檗、大黄、黄连、连翘、玄参、山栀、竹叶、龙胆草、空青、曾青、木通、童便。外治：铜青、芒硝、石胆、蕤核。急者宜以三棱针刺破眼眶肿处，捋出热血，立解。迟则血贯瞳人，目损矣。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('27oht35Pj43', 4, '{"title":"第400104100条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>100、发搐，属肝家邪热，热则生风，风主掉眩故也。</p>\n<p>【忌】同善怒。</p>\n<p>【宜】清热、降气、利小便、缓中。生地黄、白芍药、黄连、丹砂、羚羊角、童便、苏子、麦门冬、生甘草、竹叶、甘菊花、白茯苓、木通。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104100,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '100、发搐，属肝家邪热，热则生风，风主掉眩故也。 【忌】同善怒。 【宜】清热、降气、利小便、缓中。生地黄、白芍药、黄连、丹砂、羚羊角、童便、苏子、麦门冬、生甘草、竹叶、甘菊花、白茯苓、木通。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YqoeT3iQGTN', 4, '{"title":"第400104099条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>99、胁痛呕血，属肝气逆，肝火盛，肝血虚。忌、宜俱同善怒。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104099,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '99、胁痛呕血，属肝气逆，肝火盛，肝血虚。忌、宜俱同善怒。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
