INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qYcnc4tDOZM', 4, '{"title":"第400104097条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>97、善怒，怒则气上逆，甚则呕血及飧泄。</p>\n<p>【忌】补、升、热、燥、闭气。诸药俱见前。</p>\n<p>【宜】降气、清热、甘寒、酸寒、咸寒，佐以辛散。苏子、郁金、番降香、生甘草、青黛、麦冬、生地黄、赤芍药、橘皮、蒲黄、当归、延胡索、砂仁、香附、童便。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104097,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '97、善怒，怒则气上逆，甚则呕血及飧泄。 【忌】补、升、热、燥、闭气。诸药俱见前。 【宜】降气、清热、甘寒、酸寒、咸寒，佐以辛散。苏子、郁金、番降香、生甘草、青黛、麦冬、生地黄、赤芍药、橘皮、蒲黄、当归、延胡索、砂仁、香附、童便。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
