INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gllQhmK2HbZ', 4, '{"title":"第400104090条・卷之二_续序例下_五脏六腑虚实门   　","description":"<p>90、心实（五证）</p>\n<p>即实火实热。</p>\n<p>【忌】补敛、升、热、温燥。诸药俱见前。</p>\n<p>【宜】降火清热，苦寒以折之，辛寒以散之，甘寒以缓之，咸寒以润之。黄连、犀角、石膏、丹砂、牡丹皮、滑石、生甘草、麦门冬、竹叶、童便。大便结燥，加：芒硝、大黄。发狂亦如之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104090,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '2024-12-23T03:49:44.000Z', '90、心实（五证） 即实火实热。 【忌】补敛、升、热、温燥。诸药俱见前。 【宜】降火清热，苦寒以折之，辛寒以散之，甘寒以缓之，咸寒以润之。黄连、犀角、石膏、丹砂、牡丹皮、滑石、生甘草、麦门冬、竹叶、童便。大便结燥，加：芒硝、大黄。发狂亦如之。', '2024-12-23T03:49:44.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'zdblnqWOPQO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a8pgWj9dG4x', 4, '{"title":"第400104209条・卷之二_续序例下_六淫门","description":"<p>9、伤寒，太阳病、阳明病、少阳病、三阳合病、食、愈后劳复食复女劳复明阳易。冬月即病，宜从仲景冶法。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104209,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '9、伤寒，太阳病、阳明病、少阳病、三阳合病、食、愈后劳复食复女劳复明阳易。冬月即病，宜从仲景冶法。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('brcQHWlGDfE', 4, '{"title":"第400104208条・卷之二_续序例下_六淫门","description":"<p>8、伤寒，冬月即病，宜从仲景法。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104208,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '8、伤寒，冬月即病，宜从仲景法。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4dDxX8I4y93', 4, '{"title":"第400104207条・卷之二_续序例下_六淫门","description":"<p>7、中寒，忌宜同前。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104207,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '7、中寒，忌宜同前。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nkBVzQo0PlQ', 4, '{"title":"第400104206条・卷之二_续序例下_六淫门","description":"<p>6、寒（二证）</p>\n<p>诸病上下所出水液，澄澈清冷，癥瘕㿗疝坚痞，腹满急痛，下利清白，食已不饥，吐利腥秽，屈伸不便，厥逆禁固，皆属于寒。凡中寒，必本于阳虚。</p>\n<p>【忌】破气、苦寒、下、甘寒、辛寒。诸药俱见前。</p>\n<p>【宜】补气、散寒、辛甘、温热，轻者解表，重者温补。桂枝、干姜、麻黄、人参、附子、黄耆。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '6、寒（二证） 诸病上下所出水液，澄澈清冷，癥瘕㿗疝坚痞，腹满急痛，下利清白，食已不饥，吐利腥秽，屈伸不便，厥逆禁固，皆属于寒。凡中寒，必本于阳虚。 【忌】破气、苦寒、下、甘寒、辛寒。诸药俱见前。 【宜】补气、散寒、辛甘、温热，轻者解表，重者温补。桂枝、干姜、麻黄、人参、附子、黄耆。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FCRG3eJQg32', 4, '{"title":"第400104205条・卷之二_续序例下_六淫门","description":"<p>5、伤风热。</p>\n<p>【忌】同感冒风寒。</p>\n<p>【宜】辛寒、甘寒、发散。石膏、知母、甘草、竹叶、麦门冬、前胡、桔梗、薄荷、葛根、桑白皮。久而不愈者属虚。阳虚者加人参、黄耆；阴虚者，加五味子、地黄，倍门冬、白芍药。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104205,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '5、伤风热。 【忌】同感冒风寒。 【宜】辛寒、甘寒、发散。石膏、知母、甘草、竹叶、麦门冬、前胡、桔梗、薄荷、葛根、桑白皮。久而不愈者属虚。阳虚者加人参、黄耆；阴虚者，加五味子、地黄，倍门冬、白芍药。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r7Xa7JyEJHo', 4, '{"title":"第400104204条・卷之二_续序例下_六淫门","description":"<p>4、感冒风寒，俗名伤风。其证或头疼身热，轻者则否，鼻必塞，兼流清涕，必恶风寒，或声重，或声哑，甚者痰壅气喘咳嗽。</p>\n<p>【忌】补气、酸敛、闭气。诸药俱见前。</p>\n<p>【宜】发散、辛甘、温。芎、细辛、藁本、防风、甘草、荆芥、白芷、前胡、桑白皮、桔梗、紫苏、薄荷、杏仁、石膏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104204,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '4、感冒风寒，俗名伤风。其证或头疼身热，轻者则否，鼻必塞，兼流清涕，必恶风寒，或声重，或声哑，甚者痰壅气喘咳嗽。 【忌】补气、酸敛、闭气。诸药俱见前。 【宜】发散、辛甘、温。芎、细辛、藁本、防风、甘草、荆芥、白芷、前胡、桑白皮、桔梗、紫苏、薄荷、杏仁、石膏。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('avGWERib5qg', 4, '{"title":"第400104203条・卷之二_续序例下_六淫门","description":"<p>3、类中风，口眼歪斜，语言謇涩，半身不遂，口噤不言，四肢不举，痰涎壅盛，昏眊不省人事。</p>\n<p>【忌】汗、吐、下，大忌破气、温热、苦寒，及一切治风湿辛燥发散，并开窍走真气、行血诸药，慎勿犯之，犯之则轻必重，重必毙。麝香、苏合香、檀香、龙脑香、安息香（已上开窍走真气）。馀忌药俱见前。</p>\n<p>【宜】滋补，阳虚者补气，阴虚者补血，阴阳两虚则气血双补，兼宜清热、降气、豁痰，及保脾胃。天门冬（脾胃薄弱者勿多用）、麦门冬、荆沥、苏子、栝楼根、贝母、橘红、枇杷叶、甘草、竹沥、童便、霞天膏、梨汁、黄檗。次益血，于前药中加：胡麻仁、石斛、牛膝、生地黄、五味子、甘菊花、枸杞子、何首乌、薯蓣、菟丝子、白芍药、丹参、山茱萸、白蒺藜、酸枣仁、柏子仁、车前子、竹叶、羚羊角、鳖甲、木瓜、青蒿、远志、栝楼仁、沙参、巴戟天、茯苓、茯神。如便闭，加：肉苁蓉、当归，倍麻仁。如兼气虚，加人参、黄耆。有肺热者勿入人参。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104203,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '3、类中风，口眼歪斜，语言謇涩，半身不遂，口噤不言，四肢不举，痰涎壅盛，昏眊不省人事。 【忌】汗、吐、下，大忌破气、温热、苦寒，及一切治风湿辛燥发散，并开窍走真气、行血诸药，慎勿犯之，犯之则轻必重，重必毙。麝香、苏合香、檀香、龙脑香、安息香（已上开窍走真气）。馀忌药俱见前。 【宜】滋补，阳虚者补气，阴虚者补血，阴阳两虚则气血双补，兼宜清热、降气、豁痰，及保脾胃。天门冬（脾胃薄弱者勿多用）、麦门冬、荆沥、苏子、栝楼根、贝母、橘红、枇杷叶、甘草、竹沥、童便、霞天膏、梨汁、黄檗。次益血，于前药中加：胡麻仁、石斛、牛膝、生地黄、五味子、甘菊花、枸杞子、何首乌、薯蓣、菟丝子、白芍药、丹参、山茱萸、白蒺藜、酸枣仁、柏子仁、车前子、竹叶、羚羊角、鳖甲、木瓜、青蒿、远志、栝楼仁、沙参、巴戟天、茯苓、茯神。如便闭，加：肉苁蓉、当归，倍麻仁。如兼气虚，加人参、黄耆。有肺热者勿入人参。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0LRr8Ko82z0', 4, '{"title":"第400104202条・卷之二_续序例下_六淫门","description":"<p>2、真中风，猝僵仆，口噤不言，不省人事。如遗尿，直视，口开，手撒，汗出如珠，属不治证。西北高寒之地有之，东南无。</p>\n<p>【忌】破气、下、吐、苦寒、酸敛。诸药俱见前。</p>\n<p>【宜】辛甘发散、峻补真气。桂枝、附子、甘草、独活、羌活、天麻、麻黄、防风、芎、细辛、藁本、蔓荆实、牛黄、辛夷、牡荆实、白芷、人参、黄耆。有痰加：竹沥、南星、半夏、姜汁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2、真中风，猝僵仆，口噤不言，不省人事。如遗尿，直视，口开，手撒，汗出如珠，属不治证。西北高寒之地有之，东南无。 【忌】破气、下、吐、苦寒、酸敛。诸药俱见前。 【宜】辛甘发散、峻补真气。桂枝、附子、甘草、独活、羌活、天麻、麻黄、防风、芎、细辛、藁本、蔓荆实、牛黄、辛夷、牡荆实、白芷、人参、黄耆。有痰加：竹沥、南星、半夏、姜汁。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mAANWSWHeO9', 4, '{"title":"第400104201条・卷之二_续序例下_六淫门","description":"<p>1、风（四证）</p>\n<p>诸暴强直，支痛软戾，里急筋缩，皆属于风。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '2024-12-23T03:59:26.000Z', '1、风（四证） 诸暴强直，支痛软戾，里急筋缩，皆属于风。', '2024-12-23T03:59:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'd0PDBuKgLXR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qw37LvJ3ydr', 4, '{"title":"第400104301条・卷之二_续序例下_论伤寒古今时地不同，因之六经治法宜异","description":"<p>     夫伤寒者，大病也。时者，圣人所不能违者也。以关乎死生之大病，而药不从时，顾不殆哉！仲景，医门之圣也。其立法造论，后之明师，如华佗、孙思邈辈，莫不宗之。汉末去古未远，风景犹厚，形多壮伟，气尚敦厖。其药大都为北方感寒即病而设。况南北地殊，厚薄不侔，故其意可师也，其法不可改也。循至今时，千有余年，风气浇矣，人物脆矣。况在荆、扬、交、广、梁、益之地，与北土全别，故其药则有时而可改。非违仲景也，实师其意，变而通之，以从时也。如是则法不终穷矣，故作斯议，条列其方，稍为损益，以从时地。俾后之医师，知所适从，庶几患斯疾者，可免于夭枉尔！　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T04:00:23.000Z', '2024-12-23T04:00:23.000Z', '2024-12-23T04:00:23.000Z', '夫伤寒者，大病也。时者，圣人所不能违者也。以关乎死生之大病，而药不从时，顾不殆哉！仲景，医门之圣也。其立法造论，后之明师，如华佗、孙思邈辈，莫不宗之。汉末去古未远，风景犹厚，形多壮伟，气尚敦厖。其药大都为北方感寒即病而设。况南北地殊，厚薄不侔，故其意可师也，其法不可改也。循至今时，千有余年，风气浇矣，人物脆矣。况在荆、扬、交、广、梁、益之地，与北土全别，故其药则有时而可改。非违仲景也，实师其意，变而通之，以从时也。如是则法不终穷矣，故作斯议，条列其方，稍为损益，以从时地。俾后之医师，知所适从，庶几患斯疾者，可免于夭枉尔！', '2024-12-23T04:00:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'oZrDIippIjy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2pWA1WfYZH3', 4, '{"title":"第400104401条・卷之二_续序例下_辨验外感真伪法","description":"<p>       凡外感必头疼。其疼也，不间昼夜。探其舌本，必从喉咙内干出于外，多兼烦躁。不烦躁者，即轻证也。不头疼而发热，不发热而头疼，头虽疼而有时暂止，口虽干而舌本不燥，骨虽疼而头不疼，虽渴而不欲引饮，至夜或偶得寐，遇食不好亦不恶，居处虽若尪怯，而神气安静。凡若此者，皆非伤寒也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T04:01:07.000Z', '2024-12-23T04:01:07.000Z', '2024-12-23T04:01:07.000Z', '凡外感必头疼。其疼也，不间昼夜。探其舌本，必从喉咙内干出于外，多兼烦躁。不烦躁者，即轻证也。不头疼而发热，不发热而头疼，头虽疼而有时暂止，口虽干而舌本不燥，骨虽疼而头不疼，虽渴而不欲引饮，至夜或偶得寐，遇食不好亦不恶，居处虽若尪怯，而神气安静。凡若此者，皆非伤寒也。', '2024-12-23T04:01:07.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'VZ6HjEbNrN8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KqnVVVq1wIy', 4, '{"title":"第400104535条・卷之二_续序例下_三阳治法总要","description":"<p>35、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104535,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '35、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gzvocftGoFS', 4, '{"title":"第400104534条・卷之二_续序例下_三阳治法总要","description":"<p>34、伤寒六七日，无大热，其人烦躁者，此以阳去入阴故也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104534,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '34、伤寒六七日，无大热，其人烦躁者，此以阳去入阴故也。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3sJdHxVfWz1', 4, '{"title":"第400104533条・卷之二_续序例下_三阳治法总要","description":"<p>33、三阳合病，腹满身重，谵语遗尿，白虎汤加百合主之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104533,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '33、三阳合病，腹满身重，谵语遗尿，白虎汤加百合主之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q0fcqS2GLVh', 4, '{"title":"第400104532条・卷之二_续序例下_三阳治法总要","description":"<p>32、三阳合病，脉大上关上，但欲睡眠，目合则汗，药用百合（一两），麦门冬（五钱），炙甘草（一钱），知母（二钱），竹叶（五十片），栝楼根（二钱），鳖甲（如法三钱），白芍药（二钱）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104532,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '32、三阳合病，脉大上关上，但欲睡眠，目合则汗，药用百合（一两），麦门冬（五钱），炙甘草（一钱），知母（二钱），竹叶（五十片），栝楼根（二钱），鳖甲（如法三钱），白芍药（二钱）。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vRCf49cDKES', 4, '{"title":"第400104531条・卷之二_续序例下_三阳治法总要","description":"<p>31、阳明少阳并病，必下利，脉滑而数，有宿食也。当承气汤下之。若吐、下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104531,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '31、阳明少阳并病，必下利，脉滑而数，有宿食也。当承气汤下之。若吐、下、发汗、温针，谵语，柴胡汤证罢，此为坏病。知犯何逆，以法治之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mw0ty1UJjk1', 4, '{"title":"第400104530条・卷之二_续序例下_三阳治法总要","description":"<p>30、凡太阳病不解，传入少阳者，胁下硬满，干呕不能食，往来寒热，未经吐下，脉沉紧者，与小柴胡汤：柴胡（二钱四分），人参（九分），黄芩（九分），甘草（九分），半夏（一钱五分），生姜（九分），大枣（二枚），水煎，温服，日三。加减法：若胸中烦而不呕，去半夏、人参，加栝楼实（一枚）。若心下痞硬，去大枣，加牡蛎（二钱半）。若渴者，去半夏，加人参、栝楼根。若腹中痛者，去黄芩，加芍药（三钱）。若心下悸，小便不利者，去黄芩，加茯苓（二钱）。若不渴，外有微热者，去人参，加桂（一钱，夏勿用）。温覆，取微汗愈。若咳者，去人参、大枣，加五味子（一钱），少佐以干姜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104530,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '30、凡太阳病不解，传入少阳者，胁下硬满，干呕不能食，往来寒热，未经吐下，脉沉紧者，与小柴胡汤：柴胡（二钱四分），人参（九分），黄芩（九分），甘草（九分），半夏（一钱五分），生姜（九分），大枣（二枚），水煎，温服，日三。加减法：若胸中烦而不呕，去半夏、人参，加栝楼实（一枚）。若心下痞硬，去大枣，加牡蛎（二钱半）。若渴者，去半夏，加人参、栝楼根。若腹中痛者，去黄芩，加芍药（三钱）。若心下悸，小便不利者，去黄芩，加茯苓（二钱）。若不渴，外有微热者，去人参，加桂（一钱，夏勿用）。温覆，取微汗愈。若咳者，去人参、大枣，加五味子（一钱），少佐以干姜。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eAylgbDVaIb', 4, '{"title":"第400104529条・卷之二_续序例下_三阳治法总要","description":"<p>29、伤寒三日，少阳脉小者，欲己也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104529,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '29、伤寒三日，少阳脉小者，欲己也。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xTOTvXOxokP', 4, '{"title":"第400104528条・卷之二_续序例下_三阳治法总要","description":"<p>28、少阳病其证口苦，咽干，目眩，往来寒热，胸胁痛，胸满或痛，耳聋。脉法弦细。头痛发热者，属少阳。少阳不可发汗，发汗则谵语。胃和者，当自愈；不和者，则烦而悸。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104528,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '28、少阳病其证口苦，咽干，目眩，往来寒热，胸胁痛，胸满或痛，耳聋。脉法弦细。头痛发热者，属少阳。少阳不可发汗，发汗则谵语。胃和者，当自愈；不和者，则烦而悸。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wq6fcPLQFFT', 4, '{"title":"第400104527条・卷之二_续序例下_三阳治法总要","description":"<p>27、又二阳并病，太阳证罢，潮热，汗出，大便难，谵语者，宜大承气汤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104527,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '27、又二阳并病，太阳证罢，潮热，汗出，大便难，谵语者，宜大承气汤。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VEK9wIPbjcZ', 4, '{"title":"第400104526条・卷之二_续序例下_三阳治法总要","description":"<p>26、太阳阳明并病六七日，表证仍在，其人发狂者，以热在下焦，少腹当硬满，小便自利，下其血乃愈，当用桃仁承气汤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104526,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '26、太阳阳明并病六七日，表证仍在，其人发狂者，以热在下焦，少腹当硬满，小便自利，下其血乃愈，当用桃仁承气汤。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KNgPgrKXypN', 4, '{"title":"第400104525条・卷之二_续序例下_三阳治法总要","description":"<p>25、太阳阳明病协热下利者，宜六一散，以黄连煎汤调服之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104525,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '25、太阳阳明病协热下利者，宜六一散，以黄连煎汤调服之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pIQW9xvfVzg', 4, '{"title":"第400104524条・卷之二_续序例下_三阳治法总要","description":"<p>24、阳明病发狂，弃衣而走，登高而歌，此阳明实也。以承气汤亟下之。如便不结者，大剂白虎汤灌之。石膏（四两），麦冬（二两），知母（一两五钱），加大青（一两），甘草（七钱）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104524,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '24、阳明病发狂，弃衣而走，登高而歌，此阳明实也。以承气汤亟下之。如便不结者，大剂白虎汤灌之。石膏（四两），麦冬（二两），知母（一两五钱），加大青（一两），甘草（七钱）。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oXBiWKmhvH3', 4, '{"title":"第400104523条・卷之二_续序例下_三阳治法总要","description":"<p>23、阳明实则谵语，虚则郑声。郑声者，重语也。直视、谵语、喘满者死。下利者亦死。发汗多，若重发其汗，谵语脉短者死；脉和者，不死。若吐、若下后不解，不大便五六日，或至十余日，日晡时发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣妄撮，惕而不安，微喘直视，脉弦者生，涩者死（涩者阳证见阴脉也）。微者但发热谵语者，大承气汤下之。利，勿再服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104523,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '23、阳明实则谵语，虚则郑声。郑声者，重语也。直视、谵语、喘满者死。下利者亦死。发汗多，若重发其汗，谵语脉短者死；脉和者，不死。若吐、若下后不解，不大便五六日，或至十余日，日晡时发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣妄撮，惕而不安，微喘直视，脉弦者生，涩者死（涩者阳证见阴脉也）。微者但发热谵语者，大承气汤下之。利，勿再服。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bj8fYTSDgl2', 4, '{"title":"第400104522条・卷之二_续序例下_三阳治法总要","description":"<p>22、阳明病，协热下利者，宜六一散。心下痞者，以黄连栝楼汤调服之。脉浮迟，表热里寒，下利清谷者，四逆汤主之：附子、干姜、甘草。趺阳脉浮而涩，小便数，大便硬，其脾为约，麻子仁丸主之。麻仁（十三两），芍药（四两），枳实（四两），大黄（八两），厚朴（三两），杏仁（六两），蜜丸如梧子大，每用十丸，日三服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104522,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '22、阳明病，协热下利者，宜六一散。心下痞者，以黄连栝楼汤调服之。脉浮迟，表热里寒，下利清谷者，四逆汤主之：附子、干姜、甘草。趺阳脉浮而涩，小便数，大便硬，其脾为约，麻子仁丸主之。麻仁（十三两），芍药（四两），枳实（四两），大黄（八两），厚朴（三两），杏仁（六两），蜜丸如梧子大，每用十丸，日三服。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MU4CFzjlp7F', 4, '{"title":"第400104521条・卷之二_续序例下_三阳治法总要","description":"<p>21、阳阳明病脉浮紧，咽燥口苦，腹满而喘，发热汗出，恶热身重。若下之，则胃中空虚，客气动膈，心中懊憹，舌上有胎者，栀子豉汤主之。若渴欲饮水，舌燥者，白虎汤加人参主之，若脉浮，发热口渴，小便不利者，猪苓汤主之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104521,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '21、阳阳明病脉浮紧，咽燥口苦，腹满而喘，发热汗出，恶热身重。若下之，则胃中空虚，客气动膈，心中懊憹，舌上有胎者，栀子豉汤主之。若渴欲饮水，舌燥者，白虎汤加人参主之，若脉浮，发热口渴，小便不利者，猪苓汤主之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4MkmJ8huqTK', 4, '{"title":"第400104520条・卷之二_续序例下_三阳治法总要","description":"<p>20、阳明病，下血谵语者，此为热入血室，汗止在头。用荆芥（三钱），葛根（三钱），黄芩（一钱五分），麦冬（五钱），牡丹皮（一钱五分），生蒲黄（二钱），浓煎，以童便对饮之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104520,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '20、阳明病，下血谵语者，此为热入血室，汗止在头。用荆芥（三钱），葛根（三钱），黄芩（一钱五分），麦冬（五钱），牡丹皮（一钱五分），生蒲黄（二钱），浓煎，以童便对饮之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D5QG3qYbVSU', 4, '{"title":"第400104519条・卷之二_续序例下_三阳治法总要","description":"<p>19、阳明病谵语，发潮热，脉滑而数者，小承气汤主之。服药后腹中转气者，更与一服。若不转气者，勿更与之。若服药后次日不大便，脉反微涩者，里虚也，为难治。勿复议下。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104519,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '19、阳明病谵语，发潮热，脉滑而数者，小承气汤主之。服药后腹中转气者，更与一服。若不转气者，勿更与之。若服药后次日不大便，脉反微涩者，里虚也，为难治。勿复议下。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JbhZUoKLX0U', 4, '{"title":"第400104518条・卷之二_续序例下_三阳治法总要","description":"<p>18、凡阳明病多汗，津液外出，胃中燥，大便必硬，硬则谵语，以小承气汤下之。若一服谵语止者，勿再服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104518,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '18、凡阳明病多汗，津液外出，胃中燥，大便必硬，硬则谵语，以小承气汤下之。若一服谵语止者，勿再服。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d4LJDdx2BrK', 4, '{"title":"第400104517条・卷之二_续序例下_三阳治法总要","description":"<p>17、食谷欲呕，属阳明，非少阳也。胸中烦热者，竹茹汤主之：竹茹（三钱），麦门冬（五钱），枇杷叶（三大片），芦根（三两）。内无热证者，小便利，口不渴，此为阳明虚也。吴茱萸汤主之。吴茱萸（二钱），人参（三钱），生姜（一钱五分），大枣（三枚），水煎，日三服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104517,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '17、食谷欲呕，属阳明，非少阳也。胸中烦热者，竹茹汤主之：竹茹（三钱），麦门冬（五钱），枇杷叶（三大片），芦根（三两）。内无热证者，小便利，口不渴，此为阳明虚也。吴茱萸汤主之。吴茱萸（二钱），人参（三钱），生姜（一钱五分），大枣（三枚），水煎，日三服。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yNYJooe5VIt', 4, '{"title":"第400104516条・卷之二_续序例下_三阳治法总要","description":"<p>16、阳明病自汗出，或发汗后，小便利，津液内竭，大便虽硬，不可攻之。须俟其自大便，或用蜜导、胆导法通之。大下后，六七日不大便，烦不解，腹满痛，本有宿食，宜再用承气汤下之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104516,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '16、阳明病自汗出，或发汗后，小便利，津液内竭，大便虽硬，不可攻之。须俟其自大便，或用蜜导、胆导法通之。大下后，六七日不大便，烦不解，腹满痛，本有宿食，宜再用承气汤下之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mbe7VhOH8yC', 4, '{"title":"第400104515条・卷之二_续序例下_三阳治法总要","description":"<p>15、阳明病，发潮热，大便溏，胸满不去者，与小柴胡汤去人参，加栝楼、黄连。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104515,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '15、阳明病，发潮热，大便溏，胸满不去者，与小柴胡汤去人参，加栝楼、黄连。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('64bu8Jcrz8L', 4, '{"title":"第400104514条・卷之二_续序例下_三阳治法总要","description":"<p>14、阳明病，下之早，外有热，手足温，不结胸，心中懊憹不能食，但头汗出，栀子豉汤主之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104514,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '14、阳明病，下之早，外有热，手足温，不结胸，心中懊憹不能食，但头汗出，栀子豉汤主之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jDkVehuCrZM', 4, '{"title":"第400104513条・卷之二_续序例下_三阳治法总要","description":"<p>13、阳明病发汗不解，腹满急者，亟下之。伤寒六七日，目中不了了，睛不和，无表证，大便难，宜承气汤下之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104513,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '13、阳明病发汗不解，腹满急者，亟下之。伤寒六七日，目中不了了，睛不和，无表证，大便难，宜承气汤下之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KB5Ub4Y0Uf7', 4, '{"title":"第400104512条・卷之二_续序例下_三阳治法总要","description":"<p>12、阳明病邪结于里，汗出身重，短气，腹满而喘，潮热，手足濈然汗出者，此大便已硬也。六七日已来，宜下之，用小承气汤。不行，换大承气汤，勿大其剂。若大便不硬者，慎勿轻下。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104512,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '12、阳明病邪结于里，汗出身重，短气，腹满而喘，潮热，手足濈然汗出者，此大便已硬也。六七日已来，宜下之，用小承气汤。不行，换大承气汤，勿大其剂。若大便不硬者，慎勿轻下。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ty2viSRzAfK', 4, '{"title":"第400104511条・卷之二_续序例下_三阳治法总要","description":"<p>11、阳明病衄血，此缘失于发汗，宜用荆芥（二钱），葛根（三钱），麦门冬（五钱），牡丹皮（一钱五分），蒲黄（二钱），茅根（二两），侧柏叶（二钱），生地黄（三钱），浓煎与之，兼饮童便。阳明病心下硬满者，此邪未入于腹中，慎勿下之。用竹叶石膏汤，加栝楼（一个，捣碎），桔梗（二钱），黄连（一钱）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104511,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '11、阳明病衄血，此缘失于发汗，宜用荆芥（二钱），葛根（三钱），麦门冬（五钱），牡丹皮（一钱五分），蒲黄（二钱），茅根（二两），侧柏叶（二钱），生地黄（三钱），浓煎与之，兼饮童便。阳明病心下硬满者，此邪未入于腹中，慎勿下之。用竹叶石膏汤，加栝楼（一个，捣碎），桔梗（二钱），黄连（一钱）。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JZCURDO0Nnh', 4, '{"title":"第400104510条・卷之二_续序例下_三阳治法总要","description":"<p>10、阳明病，头眩，咳而咽痛者，用葛根、甘草、桔梗、麦冬四味浓煎，数数与之。阳明病无汗，小便不利，心中懊憹者，当发黄。急用栀子、麦冬、淡豆豉，大剂浓煎与之。如已见身黄，急加茵陈为君主之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104510,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '10、阳明病，头眩，咳而咽痛者，用葛根、甘草、桔梗、麦冬四味浓煎，数数与之。阳明病无汗，小便不利，心中懊憹者，当发黄。急用栀子、麦冬、淡豆豉，大剂浓煎与之。如已见身黄，急加茵陈为君主之。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zHeHhFzJAeR', 4, '{"title":"第400104509条・卷之二_续序例下_三阳治法总要","description":"<p>9、阳明病，不能食。若其人本虚，勿轻议下。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '9、阳明病，不能食。若其人本虚，勿轻议下。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4cv6JNYlPU9', 4, '{"title":"第400104508条・卷之二_续序例下_三阳治法总要","description":"<p>8、若表证罢后，邪结于里，大便闭，小便短赤，宜用调胃承气汤或小承气汤下之。下后，按其腹中不作痛而和，病即已解。如作痛，是燥粪未尽也。再用前药下之。以腹中和，二便通利为度。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '8、若表证罢后，邪结于里，大便闭，小便短赤，宜用调胃承气汤或小承气汤下之。下后，按其腹中不作痛而和，病即已解。如作痛，是燥粪未尽也。再用前药下之。以腹中和，二便通利为度。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DPNJ7992SLp', 4, '{"title":"第400104507条・卷之二_续序例下_三阳治法总要","description":"<p>7、正阳阳明病</p>\n<p>正阳阳明者，胃家实热是也。其证不大便，自汗，潮热，口渴，咽干，鼻干，呕或干呕，目眴眴不得眠，畏人声、畏木声、畏火，不恶寒反恶热，或先恶寒不久旋发热，甚则谵语狂乱，循衣摸床，脉洪大而长。宜急解其表，用竹叶石膏汤，大剂与之。不呕，无汗，与葛根汤，亦须大剂。若表证已罢，脉缓，小便利，是病解矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104507,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '7、正阳阳明病 正阳阳明者，胃家实热是也。其证不大便，自汗，潮热，口渴，咽干，鼻干，呕或干呕，目眴眴不得眠，畏人声、畏木声、畏火，不恶寒反恶热，或先恶寒不久旋发热，甚则谵语狂乱，循衣摸床，脉洪大而长。宜急解其表，用竹叶石膏汤，大剂与之。不呕，无汗，与葛根汤，亦须大剂。若表证已罢，脉缓，小便利，是病解矣。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e6jkTxhDFpO', 4, '{"title":"第400104506条・卷之二_续序例下_三阳治法总要","description":"<p>6、太阳病不解，热结膀胱，其人如狂，血自下，下之愈。其外证不解者，不可下，当先解表。表证罢，少腹急结者，乃可下之，桃仁承气汤。无蓄血证，大承气汤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104506,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '6、太阳病不解，热结膀胱，其人如狂，血自下，下之愈。其外证不解者，不可下，当先解表。表证罢，少腹急结者，乃可下之，桃仁承气汤。无蓄血证，大承气汤。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I4c04E2oZRF', 4, '{"title":"第400104505条・卷之二_续序例下_三阳治法总要","description":"<p>5、如冬月即病太阳证，恶寒、畏风、头疼、遍身骨疼、自汗、不渴，宜用桂枝（八分），芍药（二钱），甘草（一钱），大枣（二枚），生姜（一片）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104505,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '5、如冬月即病太阳证，恶寒、畏风、头疼、遍身骨疼、自汗、不渴，宜用桂枝（八分），芍药（二钱），甘草（一钱），大枣（二枚），生姜（一片）。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DTK7DqxUpxD', 4, '{"title":"第400104504条・卷之二_续序例下_三阳治法总要","description":"<p>4、如自汗烦躁，头疼、遍身骨疼不解者，羌活（一钱），桂枝（七分），石膏（一两二钱），麦冬（六钱），知母（三钱），竹叶（一百二十片），白芍药（二钱），甘草（八分）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '4、如自汗烦躁，头疼、遍身骨疼不解者，羌活（一钱），桂枝（七分），石膏（一两二钱），麦冬（六钱），知母（三钱），竹叶（一百二十片），白芍药（二钱），甘草（八分）。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PjUdrjGnL4N', 4, '{"title":"第400104503条・卷之二_续序例下_三阳治法总要","description":"<p>3、如病人自觉烦躁，喜就清凉，不喜就热，兼口渴，即欲传入阳明也。若外证头疼，遍身骨疼不解，或带口渴、鼻干、目疼、不得卧，即系太阳阳明证。羌活汤中加石膏、知母、麦冬，大剂与之，得汗即解。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '3、如病人自觉烦躁，喜就清凉，不喜就热，兼口渴，即欲传入阳明也。若外证头疼，遍身骨疼不解，或带口渴、鼻干、目疼、不得卧，即系太阳阳明证。羌活汤中加石膏、知母、麦冬，大剂与之，得汗即解。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4O4VZObFlMH', 4, '{"title":"第400104502条・卷之二_续序例下_三阳治法总要","description":"<p>2、其药以羌活汤为主：羌活（三钱）、前胡（二钱）、甘草（八分）、葛根（二钱）、生姜（三片）、枣（二枚）、杏仁（九粒，去皮，研烂）</p>\n<p>水煎服。秋深冬月应用此方，亦可量加紫苏、葱白。如冬月天气严寒，感邪即病，服此方不得汗，本方加麻黄（一钱），生姜（四片），共前（七片），得汗，勿再服。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2、其药以羌活汤为主：羌活（三钱）、前胡（二钱）、甘草（八分）、葛根（二钱）、生姜（三片）、枣（二枚）、杏仁（九粒，去皮，研烂） 水煎服。秋深冬月应用此方，亦可量加紫苏、葱白。如冬月天气严寒，感邪即病，服此方不得汗，本方加麻黄（一钱），生姜（四片），共前（七片），得汗，勿再服。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQBN1VXHmZ2', 4, '{"title":"第400104501条・卷之二_续序例下_三阳治法总要","description":"<p>1、太阳病其证发热，恶寒恶风，头痛项强，腰脊强，遍身骨痛，脉虽浮洪而不数，多不传经。烦躁脉数急者，是欲传经。宜先发汗以解表邪。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '2024-12-23T05:46:09.000Z', '1、太阳病其证发热，恶寒恶风，头痛项强，腰脊强，遍身骨痛，脉虽浮洪而不数，多不传经。烦躁脉数急者，是欲传经。宜先发汗以解表邪。', '2024-12-23T05:46:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Il7ZOmChJB3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RWAyxJ2AM47', 4, '{"title":"第400104603条・卷之二_续序例下_三阴治法总要 ","description":"<p>3、三阴各经见证，悉从仲景《伤寒论》法治之。如少阴咽痛，咽中生疮，声不出，用苦酒汤，到咽即效。故知古人立法，非今人所及也。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104603,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '3、三阴各经见证，悉从仲景《伤寒论》法治之。如少阴咽痛，咽中生疮，声不出，用苦酒汤，到咽即效。故知古人立法，非今人所及也。', '2024-12-23T06:03:27.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'stqSBbvWj00');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D9qDmR1cp51', 4, '{"title":"第400104602条・卷之二_续序例下_三阴治法总要 ","description":"<p>2、若从无阳邪表证，从不头疼发热，寒邪直中阴经，此必元气素虚之人，或在极北高寒之地，始有是证。法宜温补以接其阳，附子、人参、干姜、官桂，大剂与之。阳回寒退，即以平补之剂调之。勿过用附、桂，以防其毒。　　</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '2、若从无阳邪表证，从不头疼发热，寒邪直中阴经，此必元气素虚之人，或在极北高寒之地，始有是证。法宜温补以接其阳，附子、人参、干姜、官桂，大剂与之。阳回寒退，即以平补之剂调之。勿过用附、桂，以防其毒。', '2024-12-23T06:03:27.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'stqSBbvWj00');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YXzauGiUZR5', 4, '{"title":"第400104601条・卷之二_续序例下_三阴治法总要 ","description":"<p>1、三阴病　其证有二。一者病发于三阳，不时解表，以致邪热传入于里。虽云阴分，病属于热。粪结宜下，腹满不可按宜下，有燥粪协热下利宜下。腹痛下利，宜芍药、黄芩、炙甘草以和之。如便脓血，即加滑石、黄连，佐以升麻、干葛。如邪虽入里，粪犹未结，宜清其热。渴者用白虎汤、竹叶石膏汤；不渴或心下痞者，宜黄连、黄芩、芍药、枳壳、麦冬、栝楼辈以清之。或邪未结于下焦，少腹不坚痛，而误用芒硝以伐真阴，洞泄不己，元气将脱，宜用人参、白术、炙甘草、大枣、干姜、芍药，大剂与之。不止，佐以升提，升麻、葛根、柴胡之类。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '2024-12-23T06:03:27.000Z', '1、三阴病 其证有二。一者病发于三阳，不时解表，以致邪热传入于里。虽云阴分，病属于热。粪结宜下，腹满不可按宜下，有燥粪协热下利宜下。腹痛下利，宜芍药、黄芩、炙甘草以和之。如便脓血，即加滑石、黄连，佐以升麻、干葛。如邪虽入里，粪犹未结，宜清其热。渴者用白虎汤、竹叶石膏汤；不渴或心下痞者，宜黄连、黄芩、芍药、枳壳、麦冬、栝楼辈以清之。或邪未结于下焦，少腹不坚痛，而误用芒硝以伐真阴，洞泄不己，元气将脱，宜用人参、白术、炙甘草、大枣、干姜、芍药，大剂与之。不止，佐以升提，升麻、葛根、柴胡之类。', '2024-12-23T06:03:27.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'stqSBbvWj00');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R2n8faDijqU', 4, '{"title":"第400104733条・卷之二_续序例下_春温夏热病大法","description":"<p>33、瞤瘈瞀瘈。</p>\n<p>【忌】同火。</p>\n<p>【宜】清热和肝、酸寒、苦寒、辛寒、甘寒。白芍药、生甘草、竹叶、玄参、黄连、黄檗、生地黄、甘菊花、麦门冬、知母、石膏。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104733,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '33、瞤瘈瞀瘈。 【忌】同火。 【宜】清热和肝、酸寒、苦寒、辛寒、甘寒。白芍药、生甘草、竹叶、玄参、黄连、黄檗、生地黄、甘菊花、麦门冬、知母、石膏。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oYzBd9AwXzm', 4, '{"title":"第400104732条・卷之二_续序例下_春温夏热病大法","description":"<p>32、气逆冲上。</p>\n<p>【忌】同火。</p>\n<p>【宜】降气、酸敛、甘寒、苦寒、咸寒。苏子、枇杷叶、橘红、五味子、番降香、山茱萸、白芍药、麦门冬、石斛、黄檗、牛膝、桑白皮、童溺。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104732,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '32、气逆冲上。 【忌】同火。 【宜】降气、酸敛、甘寒、苦寒、咸寒。苏子、枇杷叶、橘红、五味子、番降香、山茱萸、白芍药、麦门冬、石斛、黄檗、牛膝、桑白皮、童溺。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YqHm5CWAUcW', 4, '{"title":"第400104731条・卷之二_续序例下_春温夏热病大法","description":"<p>31、禁栗如丧神守。</p>\n<p>【忌】同火。</p>\n<p>【宜】同躁扰狂越。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104731,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '31、禁栗如丧神守。 【忌】同火。 【宜】同躁扰狂越。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zpuWtcMfEDC', 4, '{"title":"第400104730条・卷之二_续序例下_春温夏热病大法","description":"<p>30、躁扰狂越，骂詈惊骇。</p>\n<p>【忌】同火。</p>\n<p>【宜】清镇、苦寒、辛寒、咸寒。丹砂、牛黄、黄连、黄芩、山栀、滑石、知母、童便。大便闭者，加大黄下之。不行，加芒硝。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104730,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '30、躁扰狂越，骂詈惊骇。 【忌】同火。 【宜】清镇、苦寒、辛寒、咸寒。丹砂、牛黄、黄连、黄芩、山栀、滑石、知母、童便。大便闭者，加大黄下之。不行，加芒硝。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FzS2Mlw2R1Z', 4, '{"title":"第400104729条・卷之二_续序例下_春温夏热病大法","description":"<p>29、暴注。</p>\n<p>【忌】同火。</p>\n<p>【宜】利水、苦寒、酸寒。茯苓、黄连、黄芩、白芍药、生甘草、葛根、滑石、木通。虚者加：人参、莲肉、白扁豆。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104729,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '29、暴注。 【忌】同火。 【宜】利水、苦寒、酸寒。茯苓、黄连、黄芩、白芍药、生甘草、葛根、滑石、木通。虚者加：人参、莲肉、白扁豆。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4VXzfSFXPNg', 4, '{"title":"第400104728条・卷之二_续序例下_春温夏热病大法","description":"<p>28、暴瘄。</p>\n<p>【忌】同火。</p>\n<p>【宜】降气、发音声、苦、甘寒、辛凉、咸寒。苏子、枇杷叶、贝母、桔梗、百部、竹沥、梨汁、天门冬、麦门冬、甘草、薄荷、玄参、桑白皮、童便。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104728,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '28、暴瘄。 【忌】同火。 【宜】降气、发音声、苦、甘寒、辛凉、咸寒。苏子、枇杷叶、贝母、桔梗、百部、竹沥、梨汁、天门冬、麦门冬、甘草、薄荷、玄参、桑白皮、童便。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JJnUDVQzfOL', 4, '{"title":"第400104727条・卷之二_续序例下_春温夏热病大法","description":"<p>27、口干舌苦。忌、宜俱同火。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104727,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '27、口干舌苦。忌、宜俱同火。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X4EFWC4cUGu', 4, '{"title":"第400104726条・卷之二_续序例下_春温夏热病大法","description":"<p>26、忽大渴思冰水。</p>\n<p>【忌】同火。</p>\n<p>【宜】润、生津液、辛寒、甘寒、咸寒。石膏、知母、玄参、麦门冬、竹叶、栝楼根、五味子、梨汁、蔗浆、童便、凉水、冰。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104726,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '26、忽大渴思冰水。 【忌】同火。 【宜】润、生津液、辛寒、甘寒、咸寒。石膏、知母、玄参、麦门冬、竹叶、栝楼根、五味子、梨汁、蔗浆、童便、凉水、冰。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hgNFWDlodrA', 4, '{"title":"第400104725条・卷之二_续序例下_春温夏热病大法","description":"<p>25、头面赤肿。</p>\n<p>【忌】同火。</p>\n<p>【宜】清热解毒、发散、苦寒、辛寒、甘寒、咸寒。甘菊花、鼠粘子、连翘、荆芥、薄荷、蝉蜕、大黄、玄参、石膏、知母、竹叶、生甘草、童溺。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104725,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '25、头面赤肿。 【忌】同火。 【宜】清热解毒、发散、苦寒、辛寒、甘寒、咸寒。甘菊花、鼠粘子、连翘、荆芥、薄荷、蝉蜕、大黄、玄参、石膏、知母、竹叶、生甘草、童溺。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X0sr3RqP5tb', 4, '{"title":"第400104724条・卷之二_续序例下_春温夏热病大法","description":"<p>24、二便忽闭，以利小便为先。</p>\n<p>【忌】同火。</p>\n<p>【宜】降润、苦寒、甘寒、辛寒、利窍。大黄、苏子、生蜜、麻仁、桃仁、石膏、贝母、天门冬、麦门冬、黄芩、山栀、滑石、泽泻、猪苓、车前子、木通、海金沙。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104724,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '24、二便忽闭，以利小便为先。 【忌】同火。 【宜】降润、苦寒、甘寒、辛寒、利窍。大黄、苏子、生蜜、麻仁、桃仁、石膏、贝母、天门冬、麦门冬、黄芩、山栀、滑石、泽泻、猪苓、车前子、木通、海金沙。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IYd16uWzsqV', 4, '{"title":"第400104723条・卷之二_续序例下_春温夏热病大法","description":"<p>23、目暴赤肿痛甚，见肝实条内。忌、宜俱同。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104723,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '23、目暴赤肿痛甚，见肝实条内。忌、宜俱同。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mqYoE2942aU', 4, '{"title":"第400104722条・卷之二_续序例下_春温夏热病大法","description":"<p>22、猝心痛。</p>\n<p>【忌】同火。</p>\n<p>【宜】服山栀、白芍药、延胡索、生甘草、盐汤、苏子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104722,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '22、猝心痛。 【忌】同火。 【宜】服山栀、白芍药、延胡索、生甘草、盐汤、苏子。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FI3CPmALmCR', 4, '{"title":"第400104721条・卷之二_续序例下_春温夏热病大法","description":"<p>21、猝眩仆、九窍流血，多不治。</p>\n<p>【忌】同火。</p>\n<p>【宜】服童便、盐汤、竹沥、蓝汁、梨、生犀角汁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104721,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '21、猝眩仆、九窍流血，多不治。 【忌】同火。 【宜】服童便、盐汤、竹沥、蓝汁、梨、生犀角汁。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pGcS96UOtSa', 4, '{"title":"第400104720条・卷之二_续序例下_春温夏热病大法","description":"<p>20、火，诸热瞀瘈，暴瘖冒昧，躁扰狂越，骂詈惊骇，胕肿疼酸，气逆上冲，禁栗如丧神守，啑呕，疮疡，喉痹，耳鸣及聋，呕涌溢食不下，目昧不明，暴注，瞤瘈，暴病暴死者，皆属于火。</p>\n<p>【忌】补敛、升发、闭气、辛燥、温热。诸药俱见前。</p>\n<p>【宜】降折、下、咸寒、苦寒、辛寒、甘寒。大黄、童便、芒硝、黄芩、黄连、黄檗、连翘、石膏、山栀、玄参、生甘草、知母、天门冬、麦门冬、生地黄、蓝汁。虚者宜甘寒、咸寒以滋水，不宜用苦寒伤胃。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104720,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '20、火，诸热瞀瘈，暴瘖冒昧，躁扰狂越，骂詈惊骇，胕肿疼酸，气逆上冲，禁栗如丧神守，啑呕，疮疡，喉痹，耳鸣及聋，呕涌溢食不下，目昧不明，暴注，瞤瘈，暴病暴死者，皆属于火。 【忌】补敛、升发、闭气、辛燥、温热。诸药俱见前。 【宜】降折、下、咸寒、苦寒、辛寒、甘寒。大黄、童便、芒硝、黄芩、黄连、黄檗、连翘、石膏、山栀、玄参、生甘草、知母、天门冬、麦门冬、生地黄、蓝汁。虚者宜甘寒、咸寒以滋水，不宜用苦寒伤胃。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('araeopwguoW', 4, '{"title":"第400104719条・卷之二_续序例下_春温夏热病大法","description":"<p>19、燥火（十三证）</p>\n<p>诸涩枯涸，干劲皴揭，皆属于燥。角弓反张，筋挛急不舒，舌强不能言，二便闭涩，口渴，口干舌苦，皮肤皴揭，毛发脆折，津液不生，血枯胃槁，以致饮食不化，噎膈吐食。</p>\n<p>【忌】升散、破气、下、辛燥、大热、温。诸药俱见前。</p>\n<p>【宜】润、益血、辛、甘寒、酸寒、咸寒，有热证者宜兼清热。麦门冬、当归、地黄、肉苁蓉、酥、人乳、牛乳、蜜、胡桃、甘菊花、麻仁、胡麻、柏子仁、人参、松实、天门冬、五味子、酸枣仁、白芍药、蔗浆、芦根汁、童便、梨汁、韭汁。佐以姜汁。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104719,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '19、燥火（十三证） 诸涩枯涸，干劲皴揭，皆属于燥。角弓反张，筋挛急不舒，舌强不能言，二便闭涩，口渴，口干舌苦，皮肤皴揭，毛发脆折，津液不生，血枯胃槁，以致饮食不化，噎膈吐食。 【忌】升散、破气、下、辛燥、大热、温。诸药俱见前。 【宜】润、益血、辛、甘寒、酸寒、咸寒，有热证者宜兼清热。麦门冬、当归、地黄、肉苁蓉、酥、人乳、牛乳、蜜、胡桃、甘菊花、麻仁、胡麻、柏子仁、人参、松实、天门冬、五味子、酸枣仁、白芍药、蔗浆、芦根汁、童便、梨汁、韭汁。佐以姜汁。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T710EJt6TPK', 4, '{"title":"第400104718条・卷之二_续序例下_春温夏热病大法","description":"<p>18、脚气，由于湿热。</p>\n<p>【忌】温燥、湿热、补气，复忌破气、升。诸药俱见前。</p>\n<p>【宜】清热、除湿、利小便、甘平、酸寒、苦寒、辛温、淡渗。黄檗、石斛、麦门冬、木瓜、石菖蒲、车前子、茯苓、木通、泽泻、萆薢、防己。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '18、脚气，由于湿热。 【忌】温燥、湿热、补气，复忌破气、升。诸药俱见前。 【宜】清热、除湿、利小便、甘平、酸寒、苦寒、辛温、淡渗。黄檗、石斛、麦门冬、木瓜、石菖蒲、车前子、茯苓、木通、泽泻、萆薢、防己。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yfwqz6xqFAM', 4, '{"title":"第400104717条・卷之二_续序例下_春温夏热病大法","description":"<p>17、湿（一证）</p>\n<p>诸痉强直，积饮痞膈，中满霍乱，吐下体重，胕肿肉如泥，按之不起，皆属于湿。《经》曰：地之湿气，感则害人皮肉筋脉。故其病筋骨疼痛，腰重痛不可转侧，身重，四肢不利。湿在上，病呕吐、头重、胸满；湿在中，病腹胀、中满、泄泻；湿在下，病足胫跗肿，脚气臁疮久不愈。</p>\n<p>【忌】湿润、甘、咸。诸药俱见前。</p>\n<p>【宜】散、渗泄、燥、辛、苦。木瓜、薏苡仁、术、石斛、萆薢、石菖蒲、茯苓。佐以防风、葛根。寒湿加半夏、五加皮，风湿加独活，湿热加黄檗、车前子、木通，甚者加汉防己。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104717,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '17、湿（一证） 诸痉强直，积饮痞膈，中满霍乱，吐下体重，胕肿肉如泥，按之不起，皆属于湿。《经》曰：地之湿气，感则害人皮肉筋脉。故其病筋骨疼痛，腰重痛不可转侧，身重，四肢不利。湿在上，病呕吐、头重、胸满；湿在中，病腹胀、中满、泄泻；湿在下，病足胫跗肿，脚气臁疮久不愈。 【忌】湿润、甘、咸。诸药俱见前。 【宜】散、渗泄、燥、辛、苦。木瓜、薏苡仁、术、石斛、萆薢、石菖蒲、茯苓。佐以防风、葛根。寒湿加半夏、五加皮，风湿加独活，湿热加黄檗、车前子、木通，甚者加汉防己。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sPZTEP0xmMV', 4, '{"title":"第400104716条・卷之二_续序例下_春温夏热病大法","description":"<p>16、疰夏，由于脾胃薄弱，胃家有湿热，及留饮所致。</p>\n<p>【忌】同前。</p>\n<p>【宜】益气健脾、酸寒、苦寒、淡渗。人参、白术、半夏、橘皮、白茯苓、白扁豆、白芍药、木瓜、泽泻。兼服生脉散。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104716,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '16、疰夏，由于脾胃薄弱，胃家有湿热，及留饮所致。 【忌】同前。 【宜】益气健脾、酸寒、苦寒、淡渗。人参、白术、半夏、橘皮、白茯苓、白扁豆、白芍药、木瓜、泽泻。兼服生脉散。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ufiLp7c6hTD', 4, '{"title":"第400104715条・卷之二_续序例下_春温夏热病大法","description":"<p>15、霍乱，见胃虚条内。忌、宜俱同。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104715,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '15、霍乱，见胃虚条内。忌、宜俱同。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UUPSX51a5On', 4, '{"title":"第400104714条・卷之二_续序例下_春温夏热病大法","description":"<p>14、太阳病中暍。</p>\n<p>【忌】同暑。</p>\n<p>【宜】人参白虎汤。有肺热火病人，不能服参者，用竹叶石膏汤。脾胃作泻者，水调六一散。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104714,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '14、太阳病中暍。 【忌】同暑。 【宜】人参白虎汤。有肺热火病人，不能服参者，用竹叶石膏汤。脾胃作泻者，水调六一散。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AfW9HnxTAFx', 4, '{"title":"第400104713条・卷之二_续序例下_春温夏热病大法","description":"<p>13、中暑，猝昏晕，急以童便灌入即省。</p>\n<p></p>\n<p>       忌、宜俱同暑。又方：用丝瓜叶一片，白盐梅肉一枚，并取核中仁，共研如泥，新汲水调灌，立瘥。兼治中暑霍乱有神。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104713,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '13、中暑，猝昏晕，急以童便灌入即省。 忌、宜俱同暑。又方：用丝瓜叶一片，白盐梅肉一枚，并取核中仁，共研如泥，新汲水调灌，立瘥。兼治中暑霍乱有神。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jgQfB6GYwoX', 4, '{"title":"第400104712条・卷之二_续序例下_春温夏热病大法","description":"<p>12、暑（三证）</p>\n<p>诸病喘呕，暴注下迫，霍乱转筋，身热瞀郁，小便浊赤，皆属于暑。</p>\n<p>【忌】破气、升，复忌下、湿润、辛温、辛燥、热、发散、闭气。诸药俱见前。</p>\n<p>【宜】清暑益气、健脾、甘寒、甘温、辛寒、酸寒、苦寒。黄连、香薷、葛根、石膏、知母、甘草、人参、黄芪、白术、白扁豆、神曲、橘皮、白茯苓、木瓜、麦门冬、五味子、白芍药、白梅、乌梅。大约用清暑益气汤、香薷饮、生脉散。凡病暑之人，其气必虚。暑伤气，无气以动，故当补气为本。惟肺热多火者，忌人参、术。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104712,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '12、暑（三证） 诸病喘呕，暴注下迫，霍乱转筋，身热瞀郁，小便浊赤，皆属于暑。 【忌】破气、升，复忌下、湿润、辛温、辛燥、热、发散、闭气。诸药俱见前。 【宜】清暑益气、健脾、甘寒、甘温、辛寒、酸寒、苦寒。黄连、香薷、葛根、石膏、知母、甘草、人参、黄芪、白术、白扁豆、神曲、橘皮、白茯苓、木瓜、麦门冬、五味子、白芍药、白梅、乌梅。大约用清暑益气汤、香薷饮、生脉散。凡病暑之人，其气必虚。暑伤气，无气以动，故当补气为本。惟肺热多火者，忌人参、术。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4V7inPWsDam', 4, '{"title":"第400104711条・卷之二_续序例下_春温夏热病大法","description":"<p>11、时气伤寒（除阴证不可服。）</p>\n<p>        苦参（一两），水、酒各一碗，煎八分。重者水、醋各半服之。一汗而愈。不论伤寒久近，立效。本草云：天行尤良。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '11、时气伤寒（除阴证不可服。） 苦参（一两），水、酒各一碗，煎八分。重者水、醋各半服之。一汗而愈。不论伤寒久近，立效。本草云：天行尤良。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3sJUDnJR0Kf', 4, '{"title":"第400104710条・卷之二_续序例下_春温夏热病大法","description":"<p>10、近代医师鲁莽，既不明伤寒治法，又不识杂证类伤寒，往往妄投汗、下之药，以致虚人元气，变证丛生。元气本虚之人，未有不因之而毙者矣。戒之哉！汗、下之药，焉可尝试也！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '10、近代医师鲁莽，既不明伤寒治法，又不识杂证类伤寒，往往妄投汗、下之药，以致虚人元气，变证丛生。元气本虚之人，未有不因之而毙者矣。戒之哉！汗、下之药，焉可尝试也！', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7SdH7M5ANsG', 4, '{"title":"第400104709条・卷之二_续序例下_春温夏热病大法","description":"<p>9、百合病者，百脉一宗，悉致其病也。其证神思常默然，饮食不美、亦不恶，如寒无寒，如热无热，口苦，小便赤，百合地黄汤主之。汗后者，百合知母汤。下后者，滑石代赭汤。吐后者，百合鸡子汤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104709,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '9、百合病者，百脉一宗，悉致其病也。其证神思常默然，饮食不美、亦不恶，如寒无寒，如热无热，口苦，小便赤，百合地黄汤主之。汗后者，百合知母汤。下后者，滑石代赭汤。吐后者，百合鸡子汤。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Xcz4HeAls6', 4, '{"title":"第400104708条・卷之二_续序例下_春温夏热病大法","description":"<p>8、伤寒差已后，更发热者，小柴胡汤主之。脉浮者，以汗解之。脉沉实者，以下解之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '8、伤寒差已后，更发热者，小柴胡汤主之。脉浮者，以汗解之。脉沉实者，以下解之。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HbFOF8EW9St', 4, '{"title":"第400104707条・卷之二_续序例下_春温夏热病大法","description":"<p>7、大病差后，劳复者，枳实栀子汤主之：枳实（三枚）　栀子（十四枚）　豉（一升，绵裹），以清浆水七升，空煮取四升，内枳实、栀子，煮取二升，下豉，更煮五六沸，去滓，温分再服。覆令微似汗。若有宿食者，加大黄如博棋子大五六枚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '7、大病差后，劳复者，枳实栀子汤主之：枳实（三枚） 栀子（十四枚） 豉（一升，绵裹），以清浆水七升，空煮取四升，内枳实、栀子，煮取二升，下豉，更煮五六沸，去滓，温分再服。覆令微似汗。若有宿食者，加大黄如博棋子大五六枚。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('993foUskHYf', 4, '{"title":"第400104706条・卷之二_续序例下_春温夏热病大法","description":"<p>6、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取妇人中裈近阴处，剪，烧灰，以水和服方寸匕，日三。小便即利，阴头微肿则愈。妇人病，取男子裈裆烧灰。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '6、伤寒阴阳易之为病，其人身体重，少气，少腹里急，或引阴中拘挛，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取妇人中裈近阴处，剪，烧灰，以水和服方寸匕，日三。小便即利，阴头微肿则愈。妇人病，取男子裈裆烧灰。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cp0YCbdIzpP', 4, '{"title":"第400104705条・卷之二_续序例下_春温夏热病大法","description":"<p>5、邪在三阳，法宜速逐，迟则胃烂发斑，或传入于里，则属三阴。邪热炽者，令阴水枯竭，于法不治矣。此治之后时之过也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '5、邪在三阳，法宜速逐，迟则胃烂发斑，或传入于里，则属三阴。邪热炽者，令阴水枯竭，于法不治矣。此治之后时之过也。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AhskgQS0bOP', 4, '{"title":"第400104704条・卷之二_续序例下_春温夏热病大法","description":"<p>4、伤寒、温疫，三阳证中，往往多带阳明者，以手阳明经属大肠，与肺为表里，同开窍于鼻，足阳明经属胃，与脾为表里，同开窍于口。凡邪气之入，必从口鼻，故兼阳明证者独多。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '4、伤寒、温疫，三阳证中，往往多带阳明者，以手阳明经属大肠，与肺为表里，同开窍于鼻，足阳明经属胃，与脾为表里，同开窍于口。凡邪气之入，必从口鼻，故兼阳明证者独多。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LzRSLI6qZcZ', 4, '{"title":"第400104703条・卷之二_续序例下_春温夏热病大法","description":"<p>3、伤寒、温疫，其不可治及难治者，皆属下元虚。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '3、伤寒、温疫，其不可治及难治者，皆属下元虚。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('51HP74lrWDB', 4, '{"title":"第400104702条・卷之二_续序例下_春温夏热病大法","description":"<p>2、至夏变为热病，其表证大约与春温同，但热比于温，则邪气更烈耳。解表用白虎汤、竹叶石膏汤。有太阳证则加羌活，有少阳证则加柴胡、黄芩。如发斑，白虎汤、竹叶石膏汤，加玄参、栀子、桔梗、鼠粘子、连翘、大青、小青、青黛，大剂与之。二证若大便秘，宜按之。其邪已结于内，便硬宜察，邪结中焦，小承气汤、调胃承气汤下之；邪结下焦，少腹坚痛，始用大承气汤下之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2、至夏变为热病，其表证大约与春温同，但热比于温，则邪气更烈耳。解表用白虎汤、竹叶石膏汤。有太阳证则加羌活，有少阳证则加柴胡、黄芩。如发斑，白虎汤、竹叶石膏汤，加玄参、栀子、桔梗、鼠粘子、连翘、大青、小青、青黛，大剂与之。二证若大便秘，宜按之。其邪已结于内，便硬宜察，邪结中焦，小承气汤、调胃承气汤下之；邪结下焦，少腹坚痛，始用大承气汤下之。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f2yGHQKUXO5', 4, '{"title":"第400104701条・卷之二_续序例下_春温夏热病大法","description":"<p>1、冬伤于寒，至春变为温病，大都头疼发热，或渴或不渴。三阳证俱然。亦间有先微寒后即发热者。大抵发热其常也。药用辛温，佐以辛寒，以解表邪。太阳宜羌活汤，阳明宜白虎汤，无汗不呕者，间用葛根汤。少阳往来寒热等证，不可汗、吐、下，宜和解，小柴胡汤。渴者，去半夏，加栝楼根；耳聋，热盛，去人参，加麦冬、知母、栝楼根，渴亦加之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '2024-12-23T06:20:48.000Z', '1、冬伤于寒，至春变为温病，大都头疼发热，或渴或不渴。三阳证俱然。亦间有先微寒后即发热者。大抵发热其常也。药用辛温，佐以辛寒，以解表邪。太阳宜羌活汤，阳明宜白虎汤，无汗不呕者，间用葛根汤。少阳往来寒热等证，不可汗、吐、下，宜和解，小柴胡汤。渴者，去半夏，加栝楼根；耳聋，热盛，去人参，加麦冬、知母、栝楼根，渴亦加之。', '2024-12-23T06:20:48.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'x9Sl6hTKPIq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7cyMHualuzw', 4, '{"title":"第400104815条・卷之二_续序例下_杂证门","description":"<p>15、凡劳疟，病人阴不足，或作劳，或房劳，病发于阴，或间日一发，或三日一发。三日一发为病深，须以鳖甲、牛膝、何首乌为君，橘皮为佐。发于夜而便燥者，加当归。脾胃薄弱者勿加，佐以姜皮，热甚勿入。大剂与之，日三乃瘥。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104815,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '15、凡劳疟，病人阴不足，或作劳，或房劳，病发于阴，或间日一发，或三日一发。三日一发为病深，须以鳖甲、牛膝、何首乌为君，橘皮为佐。发于夜而便燥者，加当归。脾胃薄弱者勿加，佐以姜皮，热甚勿入。大剂与之，日三乃瘥。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P1POkuZj1YH', 4, '{"title":"第400104814条・卷之二_续序例下_杂证门","description":"<p>14、又，暑热湿之邪内伏，百药不效者，用独雄丸立愈。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104814,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '14、又，暑热湿之邪内伏，百药不效者，用独雄丸立愈。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tl16HGCgYVl', 4, '{"title":"第400104813条・卷之二_续序例下_杂证门","description":"<p>13、暑邪盛，解散不早，陷入于里，则变为滞下。急投芩、连、芍药、滑石、红曲、甘草，佐以葛根、升麻、柴胡，以表里分消之。脾胃薄弱者，加人参、扁豆、莲肉，大剂与之，以愈为度。滞下若愈，疟亦随止，即不止，其热必轻，仍随经随证以治之，不烦多药而自止也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104813,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '13、暑邪盛，解散不早，陷入于里，则变为滞下。急投芩、连、芍药、滑石、红曲、甘草，佐以葛根、升麻、柴胡，以表里分消之。脾胃薄弱者，加人参、扁豆、莲肉，大剂与之，以愈为度。滞下若愈，疟亦随止，即不止，其热必轻，仍随经随证以治之，不烦多药而自止也。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HSaOYMjjCiP', 4, '{"title":"第400104812条・卷之二_续序例下_杂证门","description":"<p>12、疟病多挟风。有风者必用何首乌为君，白术、橘皮为臣，葛根、姜皮、羌活以佐之。不头痛者除羌活。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104812,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '12、疟病多挟风。有风者必用何首乌为君，白术、橘皮为臣，葛根、姜皮、羌活以佐之。不头痛者除羌活。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6repSQ1a3RC', 4, '{"title":"第400104811条・卷之二_续序例下_杂证门","description":"<p>11、疟病多挟痰。以故热痰须用贝母为君，自三钱至八钱，竹沥、竹茹、栝楼根、橘红、白茯苓，称是以佐之。甚者可加霞天膏。如寒痰发疟，寒多不渴者，用半夏、白术、橘皮为君，多加生姜皮。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104811,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '11、疟病多挟痰。以故热痰须用贝母为君，自三钱至八钱，竹沥、竹茹、栝楼根、橘红、白茯苓，称是以佐之。甚者可加霞天膏。如寒痰发疟，寒多不渴者，用半夏、白术、橘皮为君，多加生姜皮。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pAz0G3oKQi5', 4, '{"title":"第400104810条・卷之二_续序例下_杂证门","description":"<p>10、足少阴经属肾，其证寒热俱甚，腰痛脊强，口渴，寒从下起，小便短赤。</p>\n<p>【宜】先服人参白虎汤加桂枝，以祛暑邪，后用鳖甲（四五钱），牛膝（两许），热甚者加知母、麦门冬（各四五钱）。寒甚者加桂枝钱许。</p>\n<p>呕则兼加姜皮（三四钱）。如热甚而呕者，去桂枝、姜皮，加竹茹（三钱），人参、橘皮（各三四钱）。用牛膝、桂枝者，肝肾同一治故也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104810,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '10、足少阴经属肾，其证寒热俱甚，腰痛脊强，口渴，寒从下起，小便短赤。 【宜】先服人参白虎汤加桂枝，以祛暑邪，后用鳖甲（四五钱），牛膝（两许），热甚者加知母、麦门冬（各四五钱）。寒甚者加桂枝钱许。 呕则兼加姜皮（三四钱）。如热甚而呕者，去桂枝、姜皮，加竹茹（三钱），人参、橘皮（各三四钱）。用牛膝、桂枝者，肝肾同一治故也。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('101PROWi9kM', 4, '{"title":"第400104809条・卷之二_续序例下_杂证门","description":"<p>9、足太阴经属脾，其证先寒后热，或寒多。若脾疟，必寒从中起，善呕，呕已乃衰，然后发热，热过汗出乃已。热甚者或渴，否则不渴喜火。</p>\n<p>【宜】服桂枝汤、建中汤。</p>\n<p>病人虚者，以人参、姜皮各两许浓煎，露一宿，五更温服。</p>\n<p>有痰者，宜加术、橘皮（各三四钱）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '9、足太阴经属脾，其证先寒后热，或寒多。若脾疟，必寒从中起，善呕，呕已乃衰，然后发热，热过汗出乃已。热甚者或渴，否则不渴喜火。 【宜】服桂枝汤、建中汤。 病人虚者，以人参、姜皮各两许浓煎，露一宿，五更温服。 有痰者，宜加术、橘皮（各三四钱）。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('70v8mH3dTmq', 4, '{"title":"第400104808条・卷之二_续序例下_杂证门","description":"<p>8、足厥阴经属肝，其证先寒后热，色苍苍然，善太息，甚者状如欲死，或头疼而渴。</p>\n<p>【宜】先服三黄石膏汤加柴胡、鳖甲、橘皮，以祛暑邪。后用当归（两许），橘皮（三四钱），鳖甲（四五钱），牛膝（两许），柴胡（一二钱），浓煎露一宿，发日五更温服。</p>\n<p>如热甚而渴，加栝楼根（三四钱），麦门冬（四五钱），竹叶（一百片），知母（三四钱），鳖甲（五六钱）。</p>\n<p>如脾胃薄弱，或溏泄，去当归，加人参（三五钱）。</p>\n<p>如有肺火，不可服参者，只照本方，多服自愈。</p>\n<p>寒多或寒甚，指爪青黯者，加桂枝、姜皮、人参。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '8、足厥阴经属肝，其证先寒后热，色苍苍然，善太息，甚者状如欲死，或头疼而渴。 【宜】先服三黄石膏汤加柴胡、鳖甲、橘皮，以祛暑邪。后用当归（两许），橘皮（三四钱），鳖甲（四五钱），牛膝（两许），柴胡（一二钱），浓煎露一宿，发日五更温服。 如热甚而渴，加栝楼根（三四钱），麦门冬（四五钱），竹叶（一百片），知母（三四钱），鳖甲（五六钱）。 如脾胃薄弱，或溏泄，去当归，加人参（三五钱）。 如有肺火，不可服参者，只照本方，多服自愈。 寒多或寒甚，指爪青黯者，加桂枝、姜皮、人参。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0YmNb1uDpNJ', 4, '{"title":"第400104807条・卷之二_续序例下_杂证门","description":"<p>7、以上三阳经疟邪客之者，其证多热多渴，亦易得汗，药宜大剂，急逐暑邪，毋得迟留，则病易愈。继以理脾开胃，大补真气，蔑不瘳矣。邪在三阳，药宜辛寒，如石膏、知母、柴胡；甘寒，如葛根、麦门冬、竹叶、粳米；苦寒，如黄芩之属为君，乃可以散暑邪，除热渴，坠头痛。兼寒甚者，则间用辛温，如姜皮、桂枝以为向导，以伏其邪，则病易退。凡寒甚者，病因于虚。或作劳者，亦因于虚，皆宜甘温。以人参、黄耆、术为君，佐以辛甘，如桂枝、姜皮之属。脾胃虚弱，饮食不消者，则补之以参、术，佐以消导，如白豆蔻、麦芽、砂仁、草豆蔻、枳实、橘皮、山查之属。在阴分者，则以当归、牛膝为君，佐以姜、桂。如热甚而渴者去姜、桂，加知母、麦门冬、竹叶、牛膝、鳖甲。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '7、以上三阳经疟邪客之者，其证多热多渴，亦易得汗，药宜大剂，急逐暑邪，毋得迟留，则病易愈。继以理脾开胃，大补真气，蔑不瘳矣。邪在三阳，药宜辛寒，如石膏、知母、柴胡；甘寒，如葛根、麦门冬、竹叶、粳米；苦寒，如黄芩之属为君，乃可以散暑邪，除热渴，坠头痛。兼寒甚者，则间用辛温，如姜皮、桂枝以为向导，以伏其邪，则病易退。凡寒甚者，病因于虚。或作劳者，亦因于虚，皆宜甘温。以人参、黄耆、术为君，佐以辛甘，如桂枝、姜皮之属。脾胃虚弱，饮食不消者，则补之以参、术，佐以消导，如白豆蔻、麦芽、砂仁、草豆蔻、枳实、橘皮、山查之属。在阴分者，则以当归、牛膝为君，佐以姜、桂。如热甚而渴者去姜、桂，加知母、麦门冬、竹叶、牛膝、鳖甲。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3ljuMnMoGgz', 4, '{"title":"第400104806条・卷之二_续序例下_杂证门","description":"<p>6、足少阳经属胆，其证往来寒热，口苦，耳聋，胸胁痛，或呕。宜服小柴胡汤。</p>\n<p>渴者，去半夏，加石膏、麦门冬。</p>\n<p>肺家有热者，去人参，加知母，倍门冬。</p>\n<p>有痰不渴者，本方加贝母（三钱至八钱），术、茯苓（各三钱），姜皮（一钱至三四钱）。</p>\n<p>病人阴虚而有热者，虽呕吐忌用半夏、生姜，误投则损人津液，令人声哑，宜用竹茹、橘皮、麦门冬、白茯苓、乌梅以代之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104806,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '6、足少阳经属胆，其证往来寒热，口苦，耳聋，胸胁痛，或呕。宜服小柴胡汤。 渴者，去半夏，加石膏、麦门冬。 肺家有热者，去人参，加知母，倍门冬。 有痰不渴者，本方加贝母（三钱至八钱），术、茯苓（各三钱），姜皮（一钱至三四钱）。 病人阴虚而有热者，虽呕吐忌用半夏、生姜，误投则损人津液，令人声哑，宜用竹茹、橘皮、麦门冬、白茯苓、乌梅以代之。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oSy2hDrKmZ5', 4, '{"title":"第400104805条・卷之二_续序例下_杂证门","description":"<p>5、足阳明经属胃，其证发热头疼，鼻干，渴欲引饮，目眴眴不得眠，甚则烦躁，畏火光、人声、木声。宜服大剂竹叶石膏汤。无汗或汗少不呕者，可加干葛（二三钱）。</p>\n<p>病人虚而作劳者，加人参。</p>\n<p>汗多，加白术。</p>\n<p>痰多，加贝母、橘红，得汗即解。</p>\n<p>寒热俱甚，渴甚，汗多，寒时指爪皆紫黯者，加桂枝（七八分）。</p>\n<p>久而不解属气虚，用人参（两许），姜皮（两许），煎成露一宿，五更温服。下午服理脾健胃药如前方，加减亦如之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104805,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '5、足阳明经属胃，其证发热头疼，鼻干，渴欲引饮，目眴眴不得眠，甚则烦躁，畏火光、人声、木声。宜服大剂竹叶石膏汤。无汗或汗少不呕者，可加干葛（二三钱）。 病人虚而作劳者，加人参。 汗多，加白术。 痰多，加贝母、橘红，得汗即解。 寒热俱甚，渴甚，汗多，寒时指爪皆紫黯者，加桂枝（七八分）。 久而不解属气虚，用人参（两许），姜皮（两许），煎成露一宿，五更温服。下午服理脾健胃药如前方，加减亦如之。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5XZ8rDnapgh', 4, '{"title":"第400104804条・卷之二_续序例下_杂证门","description":"<p>4、《内经》六经疟候汤液</p>\n<p>足太阳经属膀胱，其证令人腰痛，头痛头重，寒从背起，先寒后热，熇熇暍暍然，热止汗出难已，或遍身骨痛，小便短赤：</p>\n<p>羌活（一钱至三四钱），广陈皮（去白二钱五分），黄芩（二钱），前胡（二钱），甘草（炙五分），猪苓（一钱），知母（二钱五分）。</p>\n<p>若口渴者，即兼阳明，宜加石膏、麦门冬，倍知母。渴而汗少，或无汗，并加葛根。</p>\n<p>若涉深秋或入冬，无汗，宜多加姜皮。</p>\n<p>因虚而无汗，或汗少者，加人参（三五钱），麦门冬（四五钱），佐以姜皮（二三钱），露一宿，发日五更温服。</p>\n<p>因虚汗多者，加黄耆（三四钱），桂枝（七八分）。汗止，即去桂枝，不可多服。</p>\n<p>若病人素有热者，勿服桂枝，以芍药、五味子代之。</p>\n<p>若发于阴，并加当归。</p>\n<p>小便短涩或赤者，与六一散二三服。</p>\n<p>有湿者，以猪苓、茯苓代滑石。下午服理脾健胃药：</p>\n<p>橘红（二钱五分），白豆蔻（五分），白茯苓（三钱），山查（三钱），麦芽（炒三钱），藿香（一钱），人参（三钱），白术（二钱），白芍药（三钱），白扁豆（三钱）。</p>\n<p>有肺火者，去人参、白术，加麦门冬（五钱），石斛（三钱），乌梅肉（一枚）。</p>\n<p>停食者必恶食，加山查。伤肉食者加黄连、红曲。伤谷食者加枳实、草果（各七分）。伤面食者加炒莱菔子。食消即已，不可多服，多服则损中气。</p>\n<p>胃家素有湿痰者，其证不渴、寒多，方可用半夏、橘红、二术，大剂与之。呕甚者兼用姜皮。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '4、《内经》六经疟候汤液 足太阳经属膀胱，其证令人腰痛，头痛头重，寒从背起，先寒后热，熇熇暍暍然，热止汗出难已，或遍身骨痛，小便短赤： 羌活（一钱至三四钱），广陈皮（去白二钱五分），黄芩（二钱），前胡（二钱），甘草（炙五分），猪苓（一钱），知母（二钱五分）。 若口渴者，即兼阳明，宜加石膏、麦门冬，倍知母。渴而汗少，或无汗，并加葛根。 若涉深秋或入冬，无汗，宜多加姜皮。 因虚而无汗，或汗少者，加人参（三五钱），麦门冬（四五钱），佐以姜皮（二三钱），露一宿，发日五更温服。 因虚汗多者，加黄耆（三四钱），桂枝（七八分）。汗止，即去桂枝，不可多服。 若病人素有热者，勿服桂枝，以芍药、五味子代之。 若发于阴，并加当归。 小便短涩或赤者，与六一散二三服。 有湿者，以猪苓、茯苓代滑石。下午服理脾健胃药： 橘红（二钱五分），白豆蔻（五分），白茯苓（三钱），山查（三钱），麦芽（炒三钱），藿香（一钱），人参（三钱），白术（二钱），白芍药（三钱），白扁豆（三钱）。 有肺火者，去人参、白术，加麦门冬（五钱），石斛（三钱），乌梅肉（一枚）。 停食者必恶食，加山查。伤肉食者加黄连、红曲。伤谷食者加枳实、草果（各七分）。伤面食者加炒莱菔子。食消即已，不可多服，多服则损中气。 胃家素有湿痰者，其证不渴、寒多，方可用半夏、橘红、二术，大剂与之。呕甚者兼用姜皮。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('szaUxAAKiSq', 4, '{"title":"第400104803条・卷之二_续序例下_杂证门","description":"<p>3、误下则邪气陷于内，变为滞下，或腹满肿胀，呕恶不思食。凡属破气、下泄药，切戒勿施！</p>\n<p>【宜】清暑益气，健脾开胃，兼消痰。</p>\n<p>【宜】分脏腑手足六经所见证拖治。</p>\n<p>先清暑：热多者宜服白虎汤加减：硬石膏（自一两至四两），知母（自四钱至二两四钱），竹叶（自一百片至四百片），麦门冬（自八钱至三两二钱），粳米（自一小撮至二大撮）。病人素虚或作劳者，加人参（自三钱至一两）。</p>\n<p>有痰加广橘红（三钱），竹沥（一杯），大渴者，加栝楼根（三钱至六钱）。</p>\n<p>不渴者，用清暑益气汤。</p>\n<p>兼饮食停滞者，加枳实、青皮、草果一二剂，食消即止。勿多服。多服则损中气。其药俱宜黄昏煎，以井水澄冷，须露一宿，五更时温服。盖疟乃暑邪为病，暑得露则散也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '3、误下则邪气陷于内，变为滞下，或腹满肿胀，呕恶不思食。凡属破气、下泄药，切戒勿施！ 【宜】清暑益气，健脾开胃，兼消痰。 【宜】分脏腑手足六经所见证拖治。 先清暑：热多者宜服白虎汤加减：硬石膏（自一两至四两），知母（自四钱至二两四钱），竹叶（自一百片至四百片），麦门冬（自八钱至三两二钱），粳米（自一小撮至二大撮）。病人素虚或作劳者，加人参（自三钱至一两）。 有痰加广橘红（三钱），竹沥（一杯），大渴者，加栝楼根（三钱至六钱）。 不渴者，用清暑益气汤。 兼饮食停滞者，加枳实、青皮、草果一二剂，食消即止。勿多服。多服则损中气。其药俱宜黄昏煎，以井水澄冷，须露一宿，五更时温服。盖疟乃暑邪为病，暑得露则散也。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0da58FCtyQ', 4, '{"title":"第400104802条・卷之二_续序例下_杂证门","description":"<p>2、疟必由于中气虚，破气则伤中气，邪不得解，甚则中满不思食，作泄，恶寒，口干，惟伤食宜消，不同此法。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2、疟必由于中气虚，破气则伤中气，邪不得解，甚则中满不思食，作泄，恶寒，口干，惟伤食宜消，不同此法。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YWlOnxwYMxd', 4, '{"title":"第400104801条・卷之二_续序例下_杂证门","description":"<p>1、疟 </p>\n<p>      《经》曰：夏伤于暑，秋必痎疟。其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，或先寒后热，或先热后寒，或有汗、无汗，或汗少、汗多，或自汗、盗汗，或头疼骨痛，或大渴引饮，口苦舌干，或呕吐不思食，或烦躁不得眠，或大便燥结，或泻利，或连发，或间发，或三日发，或发于阳，或发于阴，要皆中气不足，脾胃虚弱，暑邪乘虚客之而作。虽随经随证投药解散，必先清暑益气，调理脾胃为主。有伤食者兼消导夺食，有风兼散风，有老痰伏饮者兼豁痰逐饮，感瘴疠者兼消瘴疠，汗多者固表，无汗者解表，泄利者升发、兼利小便，便燥者兼益阴润燥。病有阴阳，药分气血，证有缓急，治因先后，人有虚实，法异攻补。久而不解，必属于虚。气虚者补气，血虚者补血，两虚者气血兼补，非大补真气，大健脾胃不得瘳也。</p>\n<p>【忌】破气、下。</p>\n<p>诸药俱见前。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '2024-12-23T06:35:06.000Z', '1、疟 《经》曰：夏伤于暑，秋必痎疟。其证大都多热多寒，或热多寒少，或寒多热少，或单热不寒，或单寒不热，或先寒后热，或先热后寒，或有汗、无汗，或汗少、汗多，或自汗、盗汗，或头疼骨痛，或大渴引饮，口苦舌干，或呕吐不思食，或烦躁不得眠，或大便燥结，或泻利，或连发，或间发，或三日发，或发于阳，或发于阴，要皆中气不足，脾胃虚弱，暑邪乘虚客之而作。虽随经随证投药解散，必先清暑益气，调理脾胃为主。有伤食者兼消导夺食，有风兼散风，有老痰伏饮者兼豁痰逐饮，感瘴疠者兼消瘴疠，汗多者固表，无汗者解表，泄利者升发、兼利小便，便燥者兼益阴润燥。病有阴阳，药分气血，证有缓急，治因先后，人有虚实，法异攻补。久而不解，必属于虚。气虚者补气，血虚者补血，两虚者气血兼补，非大补真气，大健脾胃不得瘳也。 【忌】破气、下。 诸药俱见前。', '2024-12-23T06:35:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Nablzij19SG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DyJ9Pl5R62M', 4, '{"title":"第400104913条・卷之二_续序例下_附录：诸疟主治","description":"<p>13、头痛</p>\n<p>挟风寒者：忌补敛。诸药俱见前。</p>\n<p>【宜】辛温、发散。羌活、防风、细辛、荆芥、薄荷、川芎、藁本、升麻、白芷、蔓荆子、生姜、葱白。</p>\n<p></p>\n<p>挟邪热者：忌同挟风寒。</p>\n<p>【宜】辛寒、苦寒、解散。石膏、薄荷、黄芩（酒炒）、芽茶、黑豆、乌梅、甘菊花、土茯苓。</p>\n<p></p>\n<p>热极目昏便燥者，加酒蒸大黄。</p>\n<p>挟痰者：忌升、补敛、酸甘、滞腻。诸药俱见前。</p>\n<p>【宜】豁痰降气、辛燥。苏子、橘红、贝母、半夏、前胡、竹沥、术、天麻。</p>\n<p></p>\n<p>阴虚者：忌辛热发散。诸药俱见前。</p>\n<p>【宜】补血益阴、酸敛、甘寒、酸寒。生地黄、甘菊花、当归、天门冬、麦门冬、枸杞子、黄檗、白芍药、忍冬、五味子、乌梅。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104913,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '13、头痛 挟风寒者：忌补敛。诸药俱见前。 【宜】辛温、发散。羌活、防风、细辛、荆芥、薄荷、川芎、藁本、升麻、白芷、蔓荆子、生姜、葱白。 挟邪热者：忌同挟风寒。 【宜】辛寒、苦寒、解散。石膏、薄荷、黄芩（酒炒）、芽茶、黑豆、乌梅、甘菊花、土茯苓。 热极目昏便燥者，加酒蒸大黄。 挟痰者：忌升、补敛、酸甘、滞腻。诸药俱见前。 【宜】豁痰降气、辛燥。苏子、橘红、贝母、半夏、前胡、竹沥、术、天麻。 阴虚者：忌辛热发散。诸药俱见前。 【宜】补血益阴、酸敛、甘寒、酸寒。生地黄、甘菊花、当归、天门冬、麦门冬、枸杞子、黄檗、白芍药、忍冬、五味子、乌梅。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GZCveq06i9n', 4, '{"title":"第400104915条・卷之二_续序例下_附录：诸疟主治","description":"<p>15、齿痛</p>\n<p>【忌】升、补敛、燥热、辛温。诸药俱见前。</p>\n<p>【宜】清热凉血、苦寒、辛寒、甘寒、咸寒。麦门冬、生地黄、赤芍药、牡丹皮、竹叶、知母、黄连、黄芩、黄檗、玄参、石膏、薄荷、苏子、甘草、童便。</p>\n<p>上下龈属胃与大肠火，宜石膏、熟大黄、麦门冬、黄芩、黄连、赤芍药、生地黄、生甘草、青黛、细辛、西瓜皮灰、薄荷、枇杷叶、苏子、木通。</p>\n<p>真牙浮动及黑烂，属肾虚有火，已见肾虚条内，忌、宜俱同。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104915,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '15、齿痛 【忌】升、补敛、燥热、辛温。诸药俱见前。 【宜】清热凉血、苦寒、辛寒、甘寒、咸寒。麦门冬、生地黄、赤芍药、牡丹皮、竹叶、知母、黄连、黄芩、黄檗、玄参、石膏、薄荷、苏子、甘草、童便。 上下龈属胃与大肠火，宜石膏、熟大黄、麦门冬、黄芩、黄连、赤芍药、生地黄、生甘草、青黛、细辛、西瓜皮灰、薄荷、枇杷叶、苏子、木通。 真牙浮动及黑烂，属肾虚有火，已见肾虚条内，忌、宜俱同。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Skh1kzkej81', 4, '{"title":"第400104914条・卷之二_续序例下_附录：诸疟主治","description":"<p>14、眉棱骨痛</p>\n<p>忌、宜俱同阴虚头痛。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104914,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '14、眉棱骨痛 忌、宜俱同阴虚头痛。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G84BsMmZvM0', 4, '{"title":"第400104912条・卷之二_续序例下_附录：诸疟主治","description":"<p>12、蓄血</p>\n<p>俗名内伤。或积劳，或多怒，或饱后行房，或负重努力，或登高坠下，或奔逐过急，皆致蓄血。其证多发热，其热类外感而不头疼、不作渴。天明少间，至午复剧。有汗，汗多剂颈而还，自汗，无气以息，目光短，不思饮食，不得眠，二便自利，小便或赤，大便或泄。</p>\n<p>【忌】破气，复忌补气、下、苦寒、辛燥。诸药俱见前。</p>\n<p>【宜】行血、辛温，佐以咸寒，瘀血行后宜补血益脾，和肝。桃仁、红蓝花、延胡索、桂（有火之人勿用）、郁金、当归尾、苏方木、乳香、番降香、没药、穿山甲、䗪虫、赤芍药、五灵脂、蒲黄、红曲、麒麟竭、韭汁、童便、桃枭。</p>\n<p>甚者用大黄、花蕊石。瘀行则止，勿过剂。如元气虚，脾胃素弱者，慎勿轻用大黄。如瘀血行后，宜生地黄、川续断、白胶、当归身、麦门冬、牛膝、白芍药、炙甘草、酸枣仁、大枣、龙眼肉、枸杞子、山茱萸。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104912,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '12、蓄血 俗名内伤。或积劳，或多怒，或饱后行房，或负重努力，或登高坠下，或奔逐过急，皆致蓄血。其证多发热，其热类外感而不头疼、不作渴。天明少间，至午复剧。有汗，汗多剂颈而还，自汗，无气以息，目光短，不思饮食，不得眠，二便自利，小便或赤，大便或泄。 【忌】破气，复忌补气、下、苦寒、辛燥。诸药俱见前。 【宜】行血、辛温，佐以咸寒，瘀血行后宜补血益脾，和肝。桃仁、红蓝花、延胡索、桂（有火之人勿用）、郁金、当归尾、苏方木、乳香、番降香、没药、穿山甲、䗪虫、赤芍药、五灵脂、蒲黄、红曲、麒麟竭、韭汁、童便、桃枭。 甚者用大黄、花蕊石。瘀行则止，勿过剂。如元气虚，脾胃素弱者，慎勿轻用大黄。如瘀血行后，宜生地黄、川续断、白胶、当归身、麦门冬、牛膝、白芍药、炙甘草、酸枣仁、大枣、龙眼肉、枸杞子、山茱萸。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('62Ire5eYqma', 4, '{"title":"第400104911条・卷之二_续序例下_附录：诸疟主治","description":"<p>11、诸血</p>\n<p>吐血、咯血、鼻衄、齿衄、耳衄、舌上出血。</p>\n<p>【忌】升提发散、下、破血、补气、闭气、破气、温热、辛燥，复忌极苦寒伤胃。诸药俱见前。</p>\n<p>【宜】降气、清热、凉血益阴，兼行血、咸寒、酸寒、甘寒。苏子、麦门冬、橘皮、枇杷叶、降香、郁金、天门冬、沙参、牛膝、阿胶、生地黄、枸杞子、五味子、鳖甲、白芍药、犀角汁、牡丹皮、青蒿、剪草、白药子、童便、侧柏叶、小蓟、茅根、棕灰、藕节、当归、蒲黄。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104911,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '11、诸血 吐血、咯血、鼻衄、齿衄、耳衄、舌上出血。 【忌】升提发散、下、破血、补气、闭气、破气、温热、辛燥，复忌极苦寒伤胃。诸药俱见前。 【宜】降气、清热、凉血益阴，兼行血、咸寒、酸寒、甘寒。苏子、麦门冬、橘皮、枇杷叶、降香、郁金、天门冬、沙参、牛膝、阿胶、生地黄、枸杞子、五味子、鳖甲、白芍药、犀角汁、牡丹皮、青蒿、剪草、白药子、童便、侧柏叶、小蓟、茅根、棕灰、藕节、当归、蒲黄。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eRHGXiuKDsY', 4, '{"title":"第400104910条・卷之二_续序例下_附录：诸疟主治","description":"<p>10、哕</p>\n<p>俗呼呃逆。久病沉痼而发者，属真气虚，多不治。</p>\n<p>【忌】破气、升、散。诸药俱见前。</p>\n<p>【宜】补敛、甘温、甘寒。人参、黄耆、炙甘草、麦门冬、五味子、益智子、白芍药、石斛。</p>\n<p>伤寒失下而发者，忌补敛、酸、燥热、滞腻。诸药俱见前。</p>\n<p>大便硬闭宜下，大小承气之类。便不硬闭，按之腹中和软，未经汗吐者，宜辛寒解表，白虎汤之类。</p>\n<p>因气逆冲上而发者，忌升、补。诸药俱见前。</p>\n<p>【宜】降气、甘寒、咸寒。苏子、橘红、枇杷叶、竹茹、芦根汁、麦门冬、童便。</p>\n<p>因痰水停膈而发者，忌升、润、苦寒、甘寒、酸寒。诸药俱见前。</p>\n<p>【宜】降气、开痰、辛散。橘红、苏子、贝母、桑白皮、半夏、旋覆花、生姜、白豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104910,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '10、哕 俗呼呃逆。久病沉痼而发者，属真气虚，多不治。 【忌】破气、升、散。诸药俱见前。 【宜】补敛、甘温、甘寒。人参、黄耆、炙甘草、麦门冬、五味子、益智子、白芍药、石斛。 伤寒失下而发者，忌补敛、酸、燥热、滞腻。诸药俱见前。 大便硬闭宜下，大小承气之类。便不硬闭，按之腹中和软，未经汗吐者，宜辛寒解表，白虎汤之类。 因气逆冲上而发者，忌升、补。诸药俱见前。 【宜】降气、甘寒、咸寒。苏子、橘红、枇杷叶、竹茹、芦根汁、麦门冬、童便。 因痰水停膈而发者，忌升、润、苦寒、甘寒、酸寒。诸药俱见前。 【宜】降气、开痰、辛散。橘红、苏子、贝母、桑白皮、半夏、旋覆花、生姜、白豆蔻。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3eBM4FgkS0v', 4, '{"title":"第400104909条・卷之二_续序例下_附录：诸疟主治","description":"<p>9、关格</p>\n<p>不得大小便为关，是热在丹田也。吐逆水浆不得下为格，是寒反在胸中也。是阴阳易位，故上下俱病。先投辛香通窍下降之药以治其上，次用下泄苦寒之药以通二便。此急证，法难缓治。纵有里虚，通后再补。</p>\n<p>【忌】升、补敛、闭气、酸。诸药俱见前。</p>\n<p>【宜】降下、辛寒、辛温。沉香、白豆蔻、丁香、苏子、龙脑香、苏合香、橘红、生姜、藿香。</p>\n<p>次用大黄、黄檗、知母、滑石、木通、车前子、牛膝。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104909,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '9、关格 不得大小便为关，是热在丹田也。吐逆水浆不得下为格，是寒反在胸中也。是阴阳易位，故上下俱病。先投辛香通窍下降之药以治其上，次用下泄苦寒之药以通二便。此急证，法难缓治。纵有里虚，通后再补。 【忌】升、补敛、闭气、酸。诸药俱见前。 【宜】降下、辛寒、辛温。沉香、白豆蔻、丁香、苏子、龙脑香、苏合香、橘红、生姜、藿香。 次用大黄、黄檗、知母、滑石、木通、车前子、牛膝。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u6ukXHLvgzz', 4, '{"title":"第400104908条・卷之二_续序例下_附录：诸疟主治","description":"<p>8、郁</p>\n<p>【忌】酸敛、滞腻、补气、闭气。诸药俱见前。</p>\n<p>属情抱者宜开发志意，调气散结，和中健脾。远志、贝母、郁金、石菖蒲、香附、苏子、橘红、白豆蔻、木香、苏合香、缩砂蜜、麦门冬。</p>\n<p>属五脏者，木郁达之，宜升、吐。升麻、柴胡、川芎、瓜蒂、人参芦。</p>\n<p>火郁发之，宜散。升麻、葛根、柴胡、防风、羌活。</p>\n<p>土郁夺之，宜下。槟榔、枳实、厚朴、大黄。</p>\n<p>金郁泄之，宜降。橘红、苏子、桑白皮、猪苓、泽泻、茯苓、木通。</p>\n<p>水郁折之，宜利。茯苓、海金沙、猪苓、泽泻、木通、赤小豆、车前子、乌蠡鱼。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104908,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '8、郁 【忌】酸敛、滞腻、补气、闭气。诸药俱见前。 属情抱者宜开发志意，调气散结，和中健脾。远志、贝母、郁金、石菖蒲、香附、苏子、橘红、白豆蔻、木香、苏合香、缩砂蜜、麦门冬。 属五脏者，木郁达之，宜升、吐。升麻、柴胡、川芎、瓜蒂、人参芦。 火郁发之，宜散。升麻、葛根、柴胡、防风、羌活。 土郁夺之，宜下。槟榔、枳实、厚朴、大黄。 金郁泄之，宜降。橘红、苏子、桑白皮、猪苓、泽泻、茯苓、木通。 水郁折之，宜利。茯苓、海金沙、猪苓、泽泻、木通、赤小豆、车前子、乌蠡鱼。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1B9ZJrvHXaV', 4, '{"title":"第400104907条・卷之二_续序例下_附录：诸疟主治","description":"<p>7、诸气</p>\n<p>    气有余即是火。</p>\n<p>【忌】升、闭气、酸敛、滞腻。诸药俱见前。</p>\n<p>虚者宜降、补敛、调、温、酸、辛、甘。苏子、枇杷叶、橘红、麦门冬、芦根汁、甘蔗、番降香、沉水香、白豆蔻、郁金、甘草、童便、白芍药、五味子。</p>\n<p>因虚极而气不得行者，加人参。</p>\n<p>实者宜破散、香燥、辛苦、辛寒。枳壳、青皮、槟榔、厚朴、木香、沉香、香附、乌药、降香、藿香、缩砂蜜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104907,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '7、诸气 气有余即是火。 【忌】升、闭气、酸敛、滞腻。诸药俱见前。 虚者宜降、补敛、调、温、酸、辛、甘。苏子、枇杷叶、橘红、麦门冬、芦根汁、甘蔗、番降香、沉水香、白豆蔻、郁金、甘草、童便、白芍药、五味子。 因虚极而气不得行者，加人参。 实者宜破散、香燥、辛苦、辛寒。枳壳、青皮、槟榔、厚朴、木香、沉香、香附、乌药、降香、藿香、缩砂蜜。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DYEtJ432ByE', 4, '{"title":"第400104906条・卷之二_续序例下_附录：诸疟主治","description":"<p>6、饮</p>\n<p>如涎而薄者，或如涎而稠者，伏于胸中及脾胃间，或吐酸水、苦水、黄水、绿水，或伏而不吐，上支心胸胃脘，作痛不可忍，按之不得下，或发寒热，呕吐不能饮食。</p>\n<p>忌、宜俱同脾虚证内停饮条。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104906,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '6、饮 如涎而薄者，或如涎而稠者，伏于胸中及脾胃间，或吐酸水、苦水、黄水、绿水，或伏而不吐，上支心胸胃脘，作痛不可忍，按之不得下，或发寒热，呕吐不能饮食。 忌、宜俱同脾虚证内停饮条。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r3UsO0IXm0y', 4, '{"title":"第400104905条・卷之二_续序例下_附录：诸疟主治","description":"<p>5、痰</p>\n<p>由于热：忌燥、温热、补敛，升。诸药俱见前。</p>\n<p>【宜】降、润、清热、苦寒、辛寒、佐以咸寒。苏子、橘红、天门冬、枇杷叶、麦门冬、黄芩、桑白皮、薄荷、百部、栝楼根、栝楼仁、桔梗、贝母、蛤粉、竹沥、童便。</p>\n<p>胶固者加霞天膏，并用猫儿刺。</p>\n<p>由于风寒：忌补敛，湿润、酸、咸。诸药俱见前。</p>\n<p>【宜】降气、辛散。橘红、苏子、杏仁、天麻、前胡、半夏、南星、葛根、桑白皮、薄荷、白前、生姜汁。</p>\n<p>由于湿：忌润、咸、酸、滞腻、发湿。诸药俱见前。</p>\n<p>【宜】健脾、燥湿、辛散、佐以淡渗。人参、二术、橘红、半夏、桑白皮、白茯苓、泽泻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104905,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '5、痰 由于热：忌燥、温热、补敛，升。诸药俱见前。 【宜】降、润、清热、苦寒、辛寒、佐以咸寒。苏子、橘红、天门冬、枇杷叶、麦门冬、黄芩、桑白皮、薄荷、百部、栝楼根、栝楼仁、桔梗、贝母、蛤粉、竹沥、童便。 胶固者加霞天膏，并用猫儿刺。 由于风寒：忌补敛，湿润、酸、咸。诸药俱见前。 【宜】降气、辛散。橘红、苏子、杏仁、天麻、前胡、半夏、南星、葛根、桑白皮、薄荷、白前、生姜汁。 由于湿：忌润、咸、酸、滞腻、发湿。诸药俱见前。 【宜】健脾、燥湿、辛散、佐以淡渗。人参、二术、橘红、半夏、桑白皮、白茯苓、泽泻。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ubXYrIwrIvD', 4, '{"title":"第400104904条・卷之二_续序例下_附录：诸疟主治","description":"<p>4、五疸</p>\n<p>方书所载五疸，酒、食、大饥后、过饱、女劳失治而成。然其证必由湿热伤脾及饮食停滞。又有瘀血发黄一证，方所不载。分别一误，则药不对证，多致不救。慎之！慎之！</p>\n<p>【忌】破气、闭气、下、咸、滑利、滞腻、润、燥热，有瘀血者兼忌酸寒。诸药俱见前。</p>\n<p>【宜】清热、利水、除湿、养胃气，有停滞者宜消积滞，有瘀血者宜行血。茵陈蒿、黄连、苜蓿（酒疸非此不愈）、栀子、紫草、栝楼根、秦艽、黄芩、滑石、车前子、白鲜皮、仙人对坐草、白茯苓、连钱草（一名蟹靥草，一名九里香，取汁，入姜汁少许，饮之良。）</p>\n<p>虚者，加人参。</p>\n<p>停滞者，加红曲、橘红、谷麦糵、山查。</p>\n<p>瘀血，加琥珀、牡丹皮、红曲、红花、桃仁、延胡索、蒲黄、五灵脂、韭。</p>\n<p>元气壮实者，服前药瘀血不行，可加熟大黄。虚者勿用。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104904,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '4、五疸 方书所载五疸，酒、食、大饥后、过饱、女劳失治而成。然其证必由湿热伤脾及饮食停滞。又有瘀血发黄一证，方所不载。分别一误，则药不对证，多致不救。慎之！慎之！ 【忌】破气、闭气、下、咸、滑利、滞腻、润、燥热，有瘀血者兼忌酸寒。诸药俱见前。 【宜】清热、利水、除湿、养胃气，有停滞者宜消积滞，有瘀血者宜行血。茵陈蒿、黄连、苜蓿（酒疸非此不愈）、栀子、紫草、栝楼根、秦艽、黄芩、滑石、车前子、白鲜皮、仙人对坐草、白茯苓、连钱草（一名蟹靥草，一名九里香，取汁，入姜汁少许，饮之良。） 虚者，加人参。 停滞者，加红曲、橘红、谷麦糵、山查。 瘀血，加琥珀、牡丹皮、红曲、红花、桃仁、延胡索、蒲黄、五灵脂、韭。 元气壮实者，服前药瘀血不行，可加熟大黄。虚者勿用。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sNCnpN6BC5K', 4, '{"title":"第400104903条・卷之二_续序例下_附录：诸疟主治","description":"<p>3、泻利</p>\n<p>俗称泄泻，因于湿。</p>\n<p>【忌】湿润、破气、下、苦寒、滑利。诸药俱见前。</p>\n<p>【宜】安胃补脾、升、利小便。人参、白茯苓、莲肉、白扁豆、白术、车前子、升麻、橘红、藿香、木瓜、干葛、炙甘草、白莱菔。</p>\n<p>虚寒者，加肉豆蔻、补骨脂、吴茱萸。</p>\n<p>虚热者，去白术，加川黄连，倍芍药、莲肉。</p>\n<p>暑湿为病则小水短赤，或口渴。倍用姜炒黄连为君，佐以干葛、升麻。</p>\n<p>由于感风寒者，二术、吴茱萸、砂仁、陈皮、干姜、紫苏主之。</p>\n<p>若由饮食停滞者，兼消导，山查、麦芽、神曲、陈皮、肉豆蔻。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104903,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '3、泻利 俗称泄泻，因于湿。 【忌】湿润、破气、下、苦寒、滑利。诸药俱见前。 【宜】安胃补脾、升、利小便。人参、白茯苓、莲肉、白扁豆、白术、车前子、升麻、橘红、藿香、木瓜、干葛、炙甘草、白莱菔。 虚寒者，加肉豆蔻、补骨脂、吴茱萸。 虚热者，去白术，加川黄连，倍芍药、莲肉。 暑湿为病则小水短赤，或口渴。倍用姜炒黄连为君，佐以干葛、升麻。 由于感风寒者，二术、吴茱萸、砂仁、陈皮、干姜、紫苏主之。 若由饮食停滞者，兼消导，山查、麦芽、神曲、陈皮、肉豆蔻。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O63GoxmG4eI', 4, '{"title":"第400104902条・卷之二_续序例下_附录：诸疟主治","description":"<p>2、滞下</p>\n<p>俗呼痢疾。其证腹痛便脓血，或赤或白，或赤白相杂，或下纯血，或下紫黑血块，或如豆汁，或如鱼冻，或如屋漏水，或下纯黄积粪。多里急后重，数登圊而不得便，小便短赤不利，或发热，或口渴，甚则呕恶不思食。此皆暑湿之邪与饮食积滞胶固肠胃而作，必先祛暑渗湿安胃为主。伤气分则调气益气，伤血分则和血补血，挟瘀血则行血。药虽因证而设，要皆以补养胃气为急。故其证以噤口痢为最重，胃气一绝则不可治矣。故曰：安谷则昌，绝谷则亡。俗治多藉口 “迎而夺之” 之说，轻用大黄、朴硝，及误用巴豆、牵牛，以致洞泄肠开而毙。又有妄投诃子、粟壳、亚芙蓉、肉豆蔻收涩之剂，以致便闭腹胀，或湿热上攻，肢节肿胀拘挛，痛不可忍，难以救疗。慎之！慎之！</p>\n<p>【忌】破气、闭气、收涩、燥、温热、咸寒、滑腻。诸药俱见前。</p>\n<p>【宜】清热消积、开胃气、升、利小便。黄连、黄芩、白芍药、红曲、山查、广橘红、升麻、葛根、甘草、滑石、莲肉、白扁豆、乌梅。</p>\n<p>如胃弱，加人参（三四钱），莲子（四十粒），橘红（二钱），升麻（七分）。</p>\n<p>如腹痛，以黄连（四钱），白芍药（三钱），炙甘草（一钱五分），黄檗（一钱），升麻（七分）煎服。</p>\n<p>如里急，同上药加当归（二钱）。</p>\n<p>如后重甚，加槟榔（一钱五分），枳壳（一钱五分），木香汁（七匙）。</p>\n<p>如口渴，去木香，倍滑石。</p>\n<p>如小便赤涩短少，或不利，亦倍之。</p>\n<p>赤多，倍乌梅、山查、红曲。白多，加吴茱萸（七分）。</p>\n<p>恶心欲呕，即噤口痢，多用人参、莲肉、扁豆、白芍药，以绿色升麻（七分）佐之。</p>\n<p>久痢不止，加肉豆蔻（一钱），人参（三钱），砂仁（一钱五分），白茯苓（二钱）。</p>\n<p>凡滞下，非元气壮实、多啖能食之人，慎勿轻用大黄、巴豆、牵牛等下药。</p>\n<p>复有毒痢一证，或痧毒内陷下脓血，各药不效者，加忍冬藤为君，地榆、丹砂、犀角汁饮之。</p>\n<p>凡产后滞下，积滞虽多，腹痛虽极，不可用大黄等药行之，致伤胃气，遂不可救。但用人参、白芍、当归、红曲、升麻、益母草、炙甘草、滑石末足矣。若恶露未净，兼用乳香、没药（各七分五厘），炒砂仁（一钱），久之自愈。血虚可加阿胶（三钱）。</p>\n<p>凡胎前滞下，宜用黄芩、黄连、白芍、炙甘草、橘红、赤曲、枳壳、莲肉，略用升麻。未满七月，勿用滑石。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104902,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2、滞下 俗呼痢疾。其证腹痛便脓血，或赤或白，或赤白相杂，或下纯血，或下紫黑血块，或如豆汁，或如鱼冻，或如屋漏水，或下纯黄积粪。多里急后重，数登圊而不得便，小便短赤不利，或发热，或口渴，甚则呕恶不思食。此皆暑湿之邪与饮食积滞胶固肠胃而作，必先祛暑渗湿安胃为主。伤气分则调气益气，伤血分则和血补血，挟瘀血则行血。药虽因证而设，要皆以补养胃气为急。故其证以噤口痢为最重，胃气一绝则不可治矣。故曰：安谷则昌，绝谷则亡。俗治多藉口 “迎而夺之” 之说，轻用大黄、朴硝，及误用巴豆、牵牛，以致洞泄肠开而毙。又有妄投诃子、粟壳、亚芙蓉、肉豆蔻收涩之剂，以致便闭腹胀，或湿热上攻，肢节肿胀拘挛，痛不可忍，难以救疗。慎之！慎之！ 【忌】破气、闭气、收涩、燥、温热、咸寒、滑腻。诸药俱见前。 【宜】清热消积、开胃气、升、利小便。黄连、黄芩、白芍药、红曲、山查、广橘红、升麻、葛根、甘草、滑石、莲肉、白扁豆、乌梅。 如胃弱，加人参（三四钱），莲子（四十粒），橘红（二钱），升麻（七分）。 如腹痛，以黄连（四钱），白芍药（三钱），炙甘草（一钱五分），黄檗（一钱），升麻（七分）煎服。 如里急，同上药加当归（二钱）。 如后重甚，加槟榔（一钱五分），枳壳（一钱五分），木香汁（七匙）。 如口渴，去木香，倍滑石。 如小便赤涩短少，或不利，亦倍之。 赤多，倍乌梅、山查、红曲。白多，加吴茱萸（七分）。 恶心欲呕，即噤口痢，多用人参、莲肉、扁豆、白芍药，以绿色升麻（七分）佐之。 久痢不止，加肉豆蔻（一钱），人参（三钱），砂仁（一钱五分），白茯苓（二钱）。 凡滞下，非元气壮实、多啖能食之人，慎勿轻用大黄、巴豆、牵牛等下药。 复有毒痢一证，或痧毒内陷下脓血，各药不效者，加忍冬藤为君，地榆、丹砂、犀角汁饮之。 凡产后滞下，积滞虽多，腹痛虽极，不可用大黄等药行之，致伤胃气，遂不可救。但用人参、白芍、当归、红曲、升麻、益母草、炙甘草、滑石末足矣。若恶露未净，兼用乳香、没药（各七分五厘），炒砂仁（一钱），久之自愈。血虚可加阿胶（三钱）。 凡胎前滞下，宜用黄芩、黄连、白芍、炙甘草、橘红、赤曲、枳壳、莲肉，略用升麻。未满七月，勿用滑石。', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Iw4MBXglq4N', 4, '{"title":"第400104901条・卷之二_续序例下_附录：诸疟主治","description":"<p>1、附录：诸疟主治</p>\n<p>热多宜贝母、石膏、麦门冬、橘红、干葛、滑石、竹叶、牛膝、知母、黄芩、柴胡、白茯苓、乌梅、何首乌、牡蛎、鳖甲。</p>\n<p>寒多宜桂枝、姜皮、人参、二术、黄耆、当归、橘红、半夏、草豆蔻、白豆蔻、炙甘草。</p>\n<p>汗多宜人参、白术、黄耆，秋冬加桂枝。</p>\n<p>无汗宜干葛、柴胡、石膏、羌活、姜皮、人参、苍术。</p>\n<p>疟母宜鳖甲、射干、牡蛎、三棱、缩砂蜜、桂、橘皮、青皮、人参。</p>\n<p>凡疟疾多热，久不解者，其人必本阴虚，法当益阴除热，非鳖甲、牛膝不能除也。多寒而久不解者，其人必本阳虚，非人参、白术、黄耆不能除也。</p>\n<p>按：疟有山岚瘴气、停痰留饮而发者，古方类用常山、砒霜等吐之。今人误执其方，见疟辄用，不知二药有大毒，损人真气，犯之多致危殆。慎之！慎之！</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104901,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '2024-12-23T07:21:47.000Z', '1、附录：诸疟主治 热多宜贝母、石膏、麦门冬、橘红、干葛、滑石、竹叶、牛膝、知母、黄芩、柴胡、白茯苓、乌梅、何首乌、牡蛎、鳖甲。 寒多宜桂枝、姜皮、人参、二术、黄耆、当归、橘红、半夏、草豆蔻、白豆蔻、炙甘草。 汗多宜人参、白术、黄耆，秋冬加桂枝。 无汗宜干葛、柴胡、石膏、羌活、姜皮、人参、苍术。 疟母宜鳖甲、射干、牡蛎、三棱、缩砂蜜、桂、橘皮、青皮、人参。 凡疟疾多热，久不解者，其人必本阴虚，法当益阴除热，非鳖甲、牛膝不能除也。多寒而久不解者，其人必本阳虚，非人参、白术、黄耆不能除也。 按：疟有山岚瘴气、停痰留饮而发者，古方类用常山、砒霜等吐之。今人误执其方，见疟辄用，不知二药有大毒，损人真气，犯之多致危殆。慎之！慎之！', '2024-12-23T07:21:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lBf57Zc79wv', 4, '{"title":"第400104916条・卷之二_续序例下_附录：诸疟主治","description":"<p>16、胃脘痛</p>\n<p>因火者，忌补敛、燥热。诸药俱见前。</p>\n<p>【宜】降、苦寒、甘寒、咸寒、辛寒。苏子、橘红、黄连、山栀、麦门冬、炙甘草、石膏、知母、玄参、童便。</p>\n<p></p>\n<p>因寒者：忌破气、滞腻、苦寒。诸药俱见前。</p>\n<p>【宜】辛温发散。橘皮、草豆蔻、益智子、丁香、桂、白术、藿香、白豆蔻、缩砂蜜、吴茱萸、厚朴、香附、干姜。</p>\n<p></p>\n<p>因宿食者：忌升、补敛、苦寒。诸药俱见前。</p>\n<p>【宜】消导，兼降气。山查、橘皮、草果、红曲、枳实、术、槟榔、草豆蔻、青皮、厚朴、谷麦糵、缩砂蜜。</p>\n<p></p>\n<p>因脾胃虚弱以致食停者：消导药中加入人参。</p>\n<p>因瘀血者：忌补气、酸敛。诸药俱见前。</p>\n<p>【宜】辛温、苦温以行血。桃仁、延胡索、红曲、红花、山查肉、牡丹皮、韭菜、通草、番降香、郁金、肉桂、三棱、童溺、琥珀、菴闾子、牛膝、赤芍药。</p>\n<p></p>\n<p>因血虚者，按之则痈止：忌破气，复忌补气、燥热、辛温。诸药俱见前。</p>\n<p>【宜】润、补敛、甘寒、甘温。麦门冬、炙甘草、酸枣仁、石斛、白芍药、生地黄、当归。</p>\n<p></p>\n<p>因虫者：忌补、升、发散、甘。诸药俱见前。</p>\n<p>【宜】杀虫、苦、酸。锡灰、苦楝根、槟榔、鹤虱、雷丸、使君子、芜荑、薏苡仁根、大黄、乌梅。</p>\n<p></p>\n<p>因恼怒者：虚弱人忌破气，壮实人忌补气，总忌酸敛、升。诸药俱见前。</p>\n<p>【宜】降气、辛温。苏子、枇杷叶、白豆蔻、番降香、缩砂蜜、木香、橘红、延胡索、五灵脂。</p>\n<p>因痰饮者：忌、宜俱见痰饮证下。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104916,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:35:40.000Z', '2024-12-23T07:35:40.000Z', '2024-12-23T07:35:40.000Z', '16、胃脘痛 因火者，忌补敛、燥热。诸药俱见前。 【宜】降、苦寒、甘寒、咸寒、辛寒。苏子、橘红、黄连、山栀、麦门冬、炙甘草、石膏、知母、玄参、童便。 因寒者：忌破气、滞腻、苦寒。诸药俱见前。 【宜】辛温发散。橘皮、草豆蔻、益智子、丁香、桂、白术、藿香、白豆蔻、缩砂蜜、吴茱萸、厚朴、香附、干姜。 因宿食者：忌升、补敛、苦寒。诸药俱见前。 【宜】消导，兼降气。山查、橘皮、草果、红曲、枳实、术、槟榔、草豆蔻、青皮、厚朴、谷麦糵、缩砂蜜。 因脾胃虚弱以致食停者：消导药中加入人参。 因瘀血者：忌补气、酸敛。诸药俱见前。 【宜】辛温、苦温以行血。桃仁、延胡索、红曲、红花、山查肉、牡丹皮、韭菜、通草、番降香、郁金、肉桂、三棱、童溺、琥珀、菴闾子、牛膝、赤芍药。 因血虚者，按之则痈止：忌破气，复忌补气、燥热、辛温。诸药俱见前。 【宜】润、补敛、甘寒、甘温。麦门冬、炙甘草、酸枣仁、石斛、白芍药、生地黄、当归。 因虫者：忌补、升、发散、甘。诸药俱见前。 【宜】杀虫、苦、酸。锡灰、苦楝根、槟榔、鹤虱、雷丸、使君子、芜荑、薏苡仁根、大黄、乌梅。 因恼怒者：虚弱人忌破气，壮实人忌补气，总忌酸敛、升。诸药俱见前。 【宜】降气、辛温。苏子、枇杷叶、白豆蔻、番降香、缩砂蜜、木香、橘红、延胡索、五灵脂。 因痰饮者：忌、宜俱见痰饮证下。', '2024-12-23T07:35:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cfSQ6SQ3ojz', 4, '{"title":"第400104921条・卷之二_续序例下_附录：诸疟主治","description":"<p>21、鬼疰、尸疰、飞尸、客忤</p>\n<p>此系天地阴邪杀厉之气乘虚中人，或遍身青暗，或忽消瘦声哑，面色青黄不定，或忽惊厥，目直视，手握拳，或遍身骨节疼痛非常。</p>\n<p>【忌】破气，复忌补气、升、澡热、酸敛。诸药俱见前。</p>\n<p>【宜】辟恶气、安神镇心、辛香发散、金石镇坠。牛黄、丹砂、苏合香、天竺黄、琥珀、沉水香、龙脑香、乳香、安息香、檀香、木香、麝香、真珠、雄黄、鬼臼、龙齿、犀角、金银箔、虎骨、代赭石、天灵盖、獭肝、生地黄、菖蒲、远志。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104921,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '21、鬼疰、尸疰、飞尸、客忤 此系天地阴邪杀厉之气乘虚中人，或遍身青暗，或忽消瘦声哑，面色青黄不定，或忽惊厥，目直视，手握拳，或遍身骨节疼痛非常。 【忌】破气，复忌补气、升、澡热、酸敛。诸药俱见前。 【宜】辟恶气、安神镇心、辛香发散、金石镇坠。牛黄、丹砂、苏合香、天竺黄、琥珀、沉水香、龙脑香、乳香、安息香、檀香、木香、麝香、真珠、雄黄、鬼臼、龙齿、犀角、金银箔、虎骨、代赭石、天灵盖、獭肝、生地黄、菖蒲、远志。', '2024-12-23T07:37:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v363FFUISwL', 4, '{"title":"第400104920条・卷之二_续序例下_附录：诸疟主治","description":"<p>20、交肠</p>\n<p>其病大小便易位而出。或因大怒，或因醉饱，遂至脏气乖乱，不循常道。法当宣吐以开提其气，使阑门清利，得司泌别之职，则愈矣。</p>\n<p>【忌】破气、燥、热。诸药俱见前。</p>\n<p>【宜】升清降浊，兼补气、淡渗。升麻、柴胡、苏子、降香、橘红、人参、术、茯苓、泽泻、猪苓、木通、滑石、车前子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104920,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '20、交肠 其病大小便易位而出。或因大怒，或因醉饱，遂至脏气乖乱，不循常道。法当宣吐以开提其气，使阑门清利，得司泌别之职，则愈矣。 【忌】破气、燥、热。诸药俱见前。 【宜】升清降浊，兼补气、淡渗。升麻、柴胡、苏子、降香、橘红、人参、术、茯苓、泽泻、猪苓、木通、滑石、车前子。', '2024-12-23T07:37:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L15FZUJ1U9c', 4, '{"title":"第400104919条・卷之二_续序例下_附录：诸疟主治","description":"<p>19、痿</p>\n<p>属湿热。《经》曰：治痿独取阳明。</p>\n<p>【忌】破气、升、辛热发散。诸药俱见前。</p>\n<p>【宜】大补气血、清热除湿、甘寒、甘温、苦寒、酸寒。人参、黄耆、二术、炙甘草、生地黄、麦门冬、白芍药、木瓜、石斛、薏苡仁、黄檗、茯苓、泽泻、车前子、木通、黄连、黄芩。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104919,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '19、痿 属湿热。《经》曰：治痿独取阳明。 【忌】破气、升、辛热发散。诸药俱见前。 【宜】大补气血、清热除湿、甘寒、甘温、苦寒、酸寒。人参、黄耆、二术、炙甘草、生地黄、麦门冬、白芍药、木瓜、石斛、薏苡仁、黄檗、茯苓、泽泻、车前子、木通、黄连、黄芩。', '2024-12-23T07:37:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UH6oAVkLtCp', 4, '{"title":"第400104918条・卷之二_续序例下_附录：诸疟主治","description":"<p>18、痹</p>\n<p>拘挛而痛也。因风寒湿三者合而成。风气胜者为行痹，寒气胜者为痛痹，湿气胜者为着痹。</p>\n<p>【忌】下、收敛、酸寒、苦寒、咸寒。诸药俱见前。</p>\n<p>【宜】辛散、行气、燥湿、甘温、淡渗。漆叶、续断、黄耆、甘草、甘菊花、萆薢、防己、白术、防风、羌活、独活、秦艽、牛膝、木瓜、天麻、茯苓、泽泻、菖蒲、车前子、桑寄生、狗脊、蔓荆实、杜仲、白藓皮、石斛、细辛、松节、松叶、葈耳、原蚕沙、威灵仙、海风藤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104918,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '18、痹 拘挛而痛也。因风寒湿三者合而成。风气胜者为行痹，寒气胜者为痛痹，湿气胜者为着痹。 【忌】下、收敛、酸寒、苦寒、咸寒。诸药俱见前。 【宜】辛散、行气、燥湿、甘温、淡渗。漆叶、续断、黄耆、甘草、甘菊花、萆薢、防己、白术、防风、羌活、独活、秦艽、牛膝、木瓜、天麻、茯苓、泽泻、菖蒲、车前子、桑寄生、狗脊、蔓荆实、杜仲、白藓皮、石斛、细辛、松节、松叶、葈耳、原蚕沙、威灵仙、海风藤。', '2024-12-23T07:37:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ATKBZ4VmcSP', 4, '{"title":"第400104917条・卷之二_续序例下_附录：诸疟主治","description":"<p>17、腹痛</p>\n<p>因于寒：忌苦寒、下利。诸药俱见前。</p>\n<p>【宜】温中、辛散。白术、厚朴、干姜、吴茱萸、桂、炙甘草、木香、缩砂蜜、橘皮。</p>\n<p></p>\n<p>因于热，火在少腹则绞痛：忌辛热、香燥、补敛。诸药俱见前。</p>\n<p>【宜】甘、苦寒。山栀仁、麦门冬、石斛、白芍药、甘草、桔梗、黄芩、黄连、滑石、木通、戎盐。</p>\n<p></p>\n<p>诸痛不可按，属实：忌补气、大热。诸药俱见前。</p>\n<p>【宜】破散、疏利、苦寒。枳实、青皮、槟榔、三棱、滑石、蓬莪术、木通、大黄（有积滞宜用，无者勿用）。</p>\n<p></p>\n<p>诸痛可按，属虚：忌破气、破血、下利、发散。诸药俱见前。</p>\n<p>【宜】补气血、甘温、酸敛。人参、黄耆、二术、生地黄、当归、炙甘草、白芍药、薯蓣、酸枣仁、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400104917,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '2024-12-23T07:37:02.000Z', '17、腹痛 因于寒：忌苦寒、下利。诸药俱见前。 【宜】温中、辛散。白术、厚朴、干姜、吴茱萸、桂、炙甘草、木香、缩砂蜜、橘皮。 因于热，火在少腹则绞痛：忌辛热、香燥、补敛。诸药俱见前。 【宜】甘、苦寒。山栀仁、麦门冬、石斛、白芍药、甘草、桔梗、黄芩、黄连、滑石、木通、戎盐。 诸痛不可按，属实：忌补气、大热。诸药俱见前。 【宜】破散、疏利、苦寒。枳实、青皮、槟榔、三棱、滑石、蓬莪术、木通、大黄（有积滞宜用，无者勿用）。 诸痛可按，属虚：忌破气、破血、下利、发散。诸药俱见前。 【宜】补气血、甘温、酸敛。人参、黄耆、二术、生地黄、当归、炙甘草、白芍药、薯蓣、酸枣仁、五味子。', '2024-12-23T07:37:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ke9RDwkwBhU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q0VYFMKzk2M', 4, '{"title":"第400105033条・卷之二_续序例下_妇人门","description":"<p>33、下乳汁。</p>\n<p>漏芦、狗四足、猪四足、麦门冬、人参、栝楼仁、土瓜根、葵子、猪胰、木通。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '33、下乳汁。 漏芦、狗四足、猪四足、麦门冬、人参、栝楼仁、土瓜根、葵子、猪胰、木通。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v7p4gFny3Zi', 4, '{"title":"第400105032条・卷之二_续序例下_妇人门","description":"<p>32、产后恶心欲呕或吐 由于胃虚。</p>\n<p>【忌】升提发散、湿润、滞腻、苦寒、生冷、燥热。诸药俱见前。</p>\n<p>【宜】降气、补气、安胃、酸寒，佐以辛温。苏子、枇杷叶、竹茹、人参、橘红、麦门冬、白芍药、藿香、石斛、木瓜、白豆蔻、生姜。</p>\n<p>由于寒，倍生姜、白豆蔻、藿香。由于热，倍竹茹，去生姜、白豆蔻、藿香。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105032,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '32、产后恶心欲呕或吐 由于胃虚。 【忌】升提发散、湿润、滞腻、苦寒、生冷、燥热。诸药俱见前。 【宜】降气、补气、安胃、酸寒，佐以辛温。苏子、枇杷叶、竹茹、人参、橘红、麦门冬、白芍药、藿香、石斛、木瓜、白豆蔻、生姜。 由于寒，倍生姜、白豆蔻、藿香。由于热，倍竹茹，去生姜、白豆蔻、藿香。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2xRgZg0RHwB', 4, '{"title":"第400105031条・卷之二_续序例下_妇人门","description":"<p>31、产后腹胀 由于阴血虚、脾阴虚。</p>\n<p>【忌】破气宽中、升提发散、消导、吐、下、甘、苦寒、咸寒、大热、温燥、滞腻。诸药俱见前。</p>\n<p>【宜】益脾阴、补脾、和肝、酸寒、收敛、甘温。白芍药、酸枣仁、人参、茯苓、石斛、橘皮、薯蓣、五味子、木瓜、莲实、车前子、芡实。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '31、产后腹胀 由于阴血虚、脾阴虚。 【忌】破气宽中、升提发散、消导、吐、下、甘、苦寒、咸寒、大热、温燥、滞腻。诸药俱见前。 【宜】益脾阴、补脾、和肝、酸寒、收敛、甘温。白芍药、酸枣仁、人参、茯苓、石斛、橘皮、薯蓣、五味子、木瓜、莲实、车前子、芡实。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TvoA2o6Fpw7', 4, '{"title":"第400105030条・卷之二_续序例下_妇人门","description":"<p>30、产后不得眠。</p>\n<p>【忌】同产后大便闭结。</p>\n<p>【宜】补心、降心火、补肝、补脾阴，兼清内热。生地黄、麦门冬、茯神、丹参、沙参、酸枣仁、白芍药、竹叶、远志、莲肉、龙眼肉。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '30、产后不得眠。 【忌】同产后大便闭结。 【宜】补心、降心火、补肝、补脾阴，兼清内热。生地黄、麦门冬、茯神、丹参、沙参、酸枣仁、白芍药、竹叶、远志、莲肉、龙眼肉。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('30PAKcpsN1j', 4, '{"title":"第400105029条・卷之二_续序例下_妇人门","description":"<p>29、产后大便闭结 由于血枯内热。</p>\n<p>【忌】补气、行血、辛热、燥、下、升、苦寒。诸药俱见前。</p>\n<p>【宜】益血、凉血、润燥、滋肝肾、生津液。生地黄、熟地黄、天门冬、麦门冬、五味子、蔗浆、牡丹皮、肉苁蓉、当归、麻仁、人乳、蜜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '29、产后大便闭结 由于血枯内热。 【忌】补气、行血、辛热、燥、下、升、苦寒。诸药俱见前。 【宜】益血、凉血、润燥、滋肝肾、生津液。生地黄、熟地黄、天门冬、麦门冬、五味子、蔗浆、牡丹皮、肉苁蓉、当归、麻仁、人乳、蜜。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w1WCN705BpV', 4, '{"title":"第400105028条・卷之二_续序例下_妇人门","description":"<p>28、产后小便不利或短赤 由于肾水真阴不足。</p>\n<p>【忌】利小便，馀忌同产后发热。诸药俱见前。</p>\n<p>【宜】生津液、益阴、补血、凉血、清热、甘温、甘寒、酸寒。天门冬、麦门冬、生地黄、枸杞子、山茱萸、白芍药、车前子、牛膝、五味子、青蒿子、鳖甲、竹叶。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '28、产后小便不利或短赤 由于肾水真阴不足。 【忌】利小便，馀忌同产后发热。诸药俱见前。 【宜】生津液、益阴、补血、凉血、清热、甘温、甘寒、酸寒。天门冬、麦门冬、生地黄、枸杞子、山茱萸、白芍药、车前子、牛膝、五味子、青蒿子、鳖甲、竹叶。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ne57gzxpr1l', 4, '{"title":"第400105027条・卷之二_续序例下_妇人门","description":"<p>27、产后恶寒 由于气血两虚。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】补气血、温中、甘温，佐以辛温。人参、黄耆、炙甘草、干地黄、龙眼肉、当归、炮干姜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '27、产后恶寒 由于气血两虚。 【忌】同产后发热。 【宜】补气血、温中、甘温，佐以辛温。人参、黄耆、炙甘草、干地黄、龙眼肉、当归、炮干姜。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('By0wjbK7ZjY', 4, '{"title":"第400105026条・卷之二_续序例下_妇人门","description":"<p>26、产后气喘 由于气血两虚。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】补气血、润肺、下降。人参、橘红、生地黄、天门冬、麦门冬、苏子、枇杷叶、栝楼仁、栝楼根、童便、五味子、竹茹。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '26、产后气喘 由于气血两虚。 【忌】同产后发热。 【宜】补气血、润肺、下降。人参、橘红、生地黄、天门冬、麦门冬、苏子、枇杷叶、栝楼仁、栝楼根、童便、五味子、竹茹。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xtWEVeKhit5', 4, '{"title":"第400105025条・卷之二_续序例下_妇人门","description":"<p>25、产后发渴 由于血虚有热。</p>\n<p>【忌】同产后发热。</p>\n<p>【宜】同产后发热，加蔗浆，倍麦门冬、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '25、产后发渴 由于血虚有热。 【忌】同产后发热。 【宜】同产后发热，加蔗浆，倍麦门冬、五味子。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tmex9ItzN47', 4, '{"title":"第400105024条・卷之二_续序例下_妇人门","description":"<p>24、产后头痛 由于血虚。</p>\n<p>【忌】发散、破血、升提、辛燥、大热。诸药俱见前。</p>\n<p>【宜】益血、凉血、降、甘温、甘寒，佐以酸寒。生地黄、甘菊花、乌梅、麦门冬、苏子、童便、甘草、当归、白芍药、黑豆、五味子、鳖甲。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '24、产后头痛 由于血虚。 【忌】发散、破血、升提、辛燥、大热。诸药俱见前。 【宜】益血、凉血、降、甘温、甘寒，佐以酸寒。生地黄、甘菊花、乌梅、麦门冬、苏子、童便、甘草、当归、白芍药、黑豆、五味子、鳖甲。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JO3pgnbuuwG', 4, '{"title":"第400105023条・卷之二_续序例下_妇人门","description":"<p>23、产后发热或自汗盗汗。</p>\n<p>【忌】苦寒、发散、升提、破气、破血、下、辛燥、大热、寒滑伤脾。诸药俱见前。</p>\n<p>【宜】补血、凉血、补肝、补心、生津液、兼敛摄实表。干地黄、炙甘草、白芍药、五味子、麦门冬、酸枣仁、牡丹皮、童便、青蒿、鳖甲、泽兰、黑豆、黄耆、人参（肺热者禁用）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '23、产后发热或自汗盗汗。 【忌】苦寒、发散、升提、破气、破血、下、辛燥、大热、寒滑伤脾。诸药俱见前。 【宜】补血、凉血、补肝、补心、生津液、兼敛摄实表。干地黄、炙甘草、白芍药、五味子、麦门冬、酸枣仁、牡丹皮、童便、青蒿、鳖甲、泽兰、黑豆、黄耆、人参（肺热者禁用）。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2iBPQXT6wqB', 4, '{"title":"第400105022条・卷之二_续序例下_妇人门","description":"<p>22、产后泄泻。</p>\n<p>【忌】消导、滑肠、腻膈、发散、生冷、破气、苦寒。诸药俱见前。</p>\n<p>【宜】温中补气、健脾开胃。人参、甘草、薯蓣、莲肉、扁豆、茯苓、白芍药、橘皮、车前子、肉豆蔻（内热津液不足者少用）、藿香、五味子、补骨脂（内热火炽者勿用）、缩砂蜜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105022,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '22、产后泄泻。 【忌】消导、滑肠、腻膈、发散、生冷、破气、苦寒。诸药俱见前。 【宜】温中补气、健脾开胃。人参、甘草、薯蓣、莲肉、扁豆、茯苓、白芍药、橘皮、车前子、肉豆蔻（内热津液不足者少用）、藿香、五味子、补骨脂（内热火炽者勿用）、缩砂蜜。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vgG2ZpNhdXa', 4, '{"title":"第400105021条・卷之二_续序例下_妇人门","description":"<p>21、产后少腹痛按之即止者，属血虚。</p>\n<p>【忌】行血、破气、汗、吐、下、燥、苦寒、大热。诸药俱见前。</p>\n<p>【宜】补血、补脾、和肝。干地黄、白芍药、当归、续断、白胶、阿胶、牛膝、人参、酸枣仁、麦门冬、炙甘草、大枣、薯蓣、橘皮。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105021,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '21、产后少腹痛按之即止者，属血虚。 【忌】行血、破气、汗、吐、下、燥、苦寒、大热。诸药俱见前。 【宜】补血、补脾、和肝。干地黄、白芍药、当归、续断、白胶、阿胶、牛膝、人参、酸枣仁、麦门冬、炙甘草、大枣、薯蓣、橘皮。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8qhMHZY92yV', 4, '{"title":"第400105020条・卷之二_续序例下_妇人门","description":"<p>20、产后少腹痛 按之痛甚有结块，名儿枕痛。</p>\n<p>【忌】酸敛、补气、破气、升、下、汗、燥。诸药俱见前。</p>\n<p>【宜】行血活血散结，兼健脾。延胡索、红蓝花、牡丹皮、苏方木、山查肉、益母草、蓬莪术、蒲黄、白胶、当归、黑豆、生地黄、泽兰、牛膝、五灵脂、缩砂蜜、橘红、童便、桃仁、干姜。</p>\n<p>痛极加乳香、没药（各六七分）。天寒加桂，暑月勿用，肺热有火勿用。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '20、产后少腹痛 按之痛甚有结块，名儿枕痛。 【忌】酸敛、补气、破气、升、下、汗、燥。诸药俱见前。 【宜】行血活血散结，兼健脾。延胡索、红蓝花、牡丹皮、苏方木、山查肉、益母草、蓬莪术、蒲黄、白胶、当归、黑豆、生地黄、泽兰、牛膝、五灵脂、缩砂蜜、橘红、童便、桃仁、干姜。 痛极加乳香、没药（各六七分）。天寒加桂，暑月勿用，肺热有火勿用。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VBnN52xggFV', 4, '{"title":"第400105019条・卷之二_续序例下_妇人门","description":"<p>19、产后诸病（十四证）</p>\n<p>【忌】破气、升、汗、吐、下、燥、苦寒、大热。诸药俱见前。</p>\n<p>【宜】行血，次宜补血清热，总宜补养肝脾肾、辛温、甘寒、酸寒。苏木、黑豆、鹿角末、红花、乳香、没药、牛膝、炮姜、当归（脾胃弱者勿用）、桃仁（胃弱者禁用，亦不可过用）、桂（天寒无火之人可用）、益母草、泽兰、干地黄、续断、白胶、杜仲、山茱萸、人参、青蒿、麦门冬、白芍药、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '19、产后诸病（十四证） 【忌】破气、升、汗、吐、下、燥、苦寒、大热。诸药俱见前。 【宜】行血，次宜补血清热，总宜补养肝脾肾、辛温、甘寒、酸寒。苏木、黑豆、鹿角末、红花、乳香、没药、牛膝、炮姜、当归（脾胃弱者勿用）、桃仁（胃弱者禁用，亦不可过用）、桂（天寒无火之人可用）、益母草、泽兰、干地黄、续断、白胶、杜仲、山茱萸、人参、青蒿、麦门冬、白芍药、五味子。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DGNl72FdQuJ', 4, '{"title":"第400105018条・卷之二_续序例下_妇人门","description":"<p>18、预防血晕</p>\n<p>腹痛坐草时，即用苏木菊花心者一两，生地黄一两，降香末二钱，水三碗，煎一碗，加童便半碗，儿堕地即饮之，永无恶血冲心之患。房中常打醋、炭，万一血晕亦须此药。更以家宝丹一丸，灌下神效。</p>\n<p></p>\n<p>凡妇人气弱者，无气力送子出产门，须服人参。此药能兼治横生、倒产，世医不知也。</p>\n<p></p>\n<p>凡临产交骨不开，惟浓煮柞木枝汤，饮之则自开。柞木俗名一叶一刺，其木枝干直上，每一叶必发一刺。</p>\n<p></p>\n<p>胞衣不下，用乳香、没药末各七分五厘，麝香一分，芒硝一钱五分，研细。以酒调服，立下。饮热童便以滋药力，更妙。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '18、预防血晕 腹痛坐草时，即用苏木菊花心者一两，生地黄一两，降香末二钱，水三碗，煎一碗，加童便半碗，儿堕地即饮之，永无恶血冲心之患。房中常打醋、炭，万一血晕亦须此药。更以家宝丹一丸，灌下神效。 凡妇人气弱者，无气力送子出产门，须服人参。此药能兼治横生、倒产，世医不知也。 凡临产交骨不开，惟浓煮柞木枝汤，饮之则自开。柞木俗名一叶一刺，其木枝干直上，每一叶必发一刺。 胞衣不下，用乳香、没药末各七分五厘，麝香一分，芒硝一钱五分，研细。以酒调服，立下。饮热童便以滋药力，更妙。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pkiSTWUEyX3', 4, '{"title":"第400105017条・卷之二_续序例下_妇人门","description":"<p>17、难产</p>\n<p>【忌】破气、破血、收敛。诸药俱见前。</p>\n<p>【宜】补气血、滑利、润。人参、柞树枝、鱼胶、冬葵子、千里马、白芷梢、牛膝、桂心、当归、芎、益母草、百草霜、石燕、弓弩、麻油、猪脂、酒、生鸡子、兔头、滑石、麝香。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '17、难产 【忌】破气、破血、收敛。诸药俱见前。 【宜】补气血、滑利、润。人参、柞树枝、鱼胶、冬葵子、千里马、白芷梢、牛膝、桂心、当归、芎、益母草、百草霜、石燕、弓弩、麻油、猪脂、酒、生鸡子、兔头、滑石、麝香。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4NFlBNJjfYp', 4, '{"title":"第400105016条・卷之二_续序例下_妇人门","description":"<p>16、胎漏</p>\n<p>属气血虚有热。</p>\n<p>忌、宜俱同安胎条。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '16、胎漏 属气血虚有热。 忌、宜俱同安胎条。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jg9Q8kVgRRR', 4, '{"title":"第400105015条・卷之二_续序例下_妇人门","description":"<p>15、安胎</p>\n<p>【忌】破气、破血、升散、辛热、辛燥。诸药俱见前。</p>\n<p>八月以后及胎前滞下者，方可用枳壳，气虚者不用。</p>\n<p>三月以前宜养脾胃，四月以后宜壮腰肾，补血益阴，顺气，总宜清热。茯苓、麦门冬、薯蓣、人参、芍药、白术、橘红、炙甘草、缩砂蜜、艾叶、杜仲、生地黄、益母草、白胶、阿胶、续断、黄芩、枸杞子、青蒿子、桑寄生、鲤鱼、乌雌鸡、葱白。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '15、安胎 【忌】破气、破血、升散、辛热、辛燥。诸药俱见前。 八月以后及胎前滞下者，方可用枳壳，气虚者不用。 三月以前宜养脾胃，四月以后宜壮腰肾，补血益阴，顺气，总宜清热。茯苓、麦门冬、薯蓣、人参、芍药、白术、橘红、炙甘草、缩砂蜜、艾叶、杜仲、生地黄、益母草、白胶、阿胶、续断、黄芩、枸杞子、青蒿子、桑寄生、鲤鱼、乌雌鸡、葱白。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oS7SU1klJjo', 4, '{"title":"第400105014条・卷之二_续序例下_妇人门","description":"<p>14、妊娠恶阻</p>\n<p>【忌】破气、升散、燥热、苦寒、滑肠、腻膈。诸药俱见前。</p>\n<p>【宜】顺气、甘寒、酸寒。苏子、橘红、枇杷叶、白茯苓、麦门冬、芦根、竹茹、木瓜、白芍药、竹叶、人参、缩砂蜜、白梅、乌梅。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '14、妊娠恶阻 【忌】破气、升散、燥热、苦寒、滑肠、腻膈。诸药俱见前。 【宜】顺气、甘寒、酸寒。苏子、橘红、枇杷叶、白茯苓、麦门冬、芦根、竹茹、木瓜、白芍药、竹叶、人参、缩砂蜜、白梅、乌梅。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8dluLH9VqXi', 4, '{"title":"第400105013条・卷之二_续序例下_妇人门","description":"<p>13、种子</p>\n<p>内分男、女，气虚、血虚、精寒、血热、火炽、精滑，因证选用。</p>\n<p>【忌】破气、破血、燥、过用辛热。诸药俱见前。</p>\n<p>【宜】调气补血，男子宜固精。桑螵蛸（温，平，治男子精滑）、柏实（甘，温，治男子精滑精寒）、海狗肾（咸，热，治男子精寒）、鱼胶（平，治男子精滑）、阳起石（热，治男子精寒）、覆盆子（甘，温，治男子精滑）、车前子（咸，寒，治男女火炽）、鹿茸（温，咸，治男子精寒）、莲须（甘，温，治男子精滑）、巴戟天（温，治男子精寒）、何首乌（苦，温，益男子气血）、牛膝（苦，平，治男子血虚阴痿）、补骨脂（辛，温，治男子精寒阴弱）、沙苑蒺藜（甘，平，男子固精益血）、白胶（温，平，治男女气血两虚精寒）、肉苁蓉（温，酸，咸，治男女血虚精寒）、黄檗（苦，寒，治男女火炽）、人参（微温，治男女气虚、脾胃薄弱）、麦门冬（甘，寒，男女血热）、五味子（酸，温，治男女精滑精寒）、山茱萸（酸，温，治男女精滑精寒）、天门冬（苦，寒，治男女火炽）、莲肉（甘，平，治男女胃弱精滑）、熟地黄（甘，寒，男女益血生精）、白薇（温平，女）、当归（辛温，女）、白芍药（酸寒，女）、紫石英（温，女）、艾叶（辛温，女）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '13、种子 内分男、女，气虚、血虚、精寒、血热、火炽、精滑，因证选用。 【忌】破气、破血、燥、过用辛热。诸药俱见前。 【宜】调气补血，男子宜固精。桑螵蛸（温，平，治男子精滑）、柏实（甘，温，治男子精滑精寒）、海狗肾（咸，热，治男子精寒）、鱼胶（平，治男子精滑）、阳起石（热，治男子精寒）、覆盆子（甘，温，治男子精滑）、车前子（咸，寒，治男女火炽）、鹿茸（温，咸，治男子精寒）、莲须（甘，温，治男子精滑）、巴戟天（温，治男子精寒）、何首乌（苦，温，益男子气血）、牛膝（苦，平，治男子血虚阴痿）、补骨脂（辛，温，治男子精寒阴弱）、沙苑蒺藜（甘，平，男子固精益血）、白胶（温，平，治男女气血两虚精寒）、肉苁蓉（温，酸，咸，治男女血虚精寒）、黄檗（苦，寒，治男女火炽）、人参（微温，治男女气虚、脾胃薄弱）、麦门冬（甘，寒，男女血热）、五味子（酸，温，治男女精滑精寒）、山茱萸（酸，温，治男女精滑精寒）、天门冬（苦，寒，治男女火炽）、莲肉（甘，平，治男女胃弱精滑）、熟地黄（甘，寒，男女益血生精）、白薇（温平，女）、当归（辛温，女）、白芍药（酸寒，女）、紫石英（温，女）、艾叶（辛温，女）。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gsc5iLU96Bu', 4, '{"title":"第400105012条・卷之二_续序例下_妇人门","description":"<p>12、热血入室</p>\n<p>类伤寒，或经事适来忽住，或届期不行，忽发大热、口渴，或厥，但不头疼为异于伤寒耳。</p>\n<p>【忌】补气、温燥、辛燥、收敛、下泄、大热、升发。诸药俱见前。</p>\n<p>【宜】行血清热、甘寒、咸寒、苦寒。生地黄、牡丹皮、蒲黄、苏木、牛膝、延胡索、麦门冬、犀角、白芍药、黄芩、童溺、荆芥穗。如便闭，加大黄。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '12、热血入室 类伤寒，或经事适来忽住，或届期不行，忽发大热、口渴，或厥，但不头疼为异于伤寒耳。 【忌】补气、温燥、辛燥、收敛、下泄、大热、升发。诸药俱见前。 【宜】行血清热、甘寒、咸寒、苦寒。生地黄、牡丹皮、蒲黄、苏木、牛膝、延胡索、麦门冬、犀角、白芍药、黄芩、童溺、荆芥穗。如便闭，加大黄。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XcAXzWtMdco', 4, '{"title":"第400105011条・卷之二_续序例下_妇人门","description":"<p>11、崩中</p>\n<p>属气血两虚有热。</p>\n<p>【忌】破气、行血、降、温热、辛燥、苦寒。诸药俱见前。</p>\n<p>【宜】补气血，兼清热、甘温、甘寒、酸敛。人参、黄耆、生地黄、熟地黄、地榆、芍药、白胶、阿胶、香附、续断、甘草、麦门冬、山茱萸、杜仲、五味子、白茅根、蒲黄（炒）、桑耳灰、侧柏叶、艾叶、木耳灰。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '11、崩中 属气血两虚有热。 【忌】破气、行血、降、温热、辛燥、苦寒。诸药俱见前。 【宜】补气血，兼清热、甘温、甘寒、酸敛。人参、黄耆、生地黄、熟地黄、地榆、芍药、白胶、阿胶、香附、续断、甘草、麦门冬、山茱萸、杜仲、五味子、白茅根、蒲黄（炒）、桑耳灰、侧柏叶、艾叶、木耳灰。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u8PpyAUFmp7', 4, '{"title":"第400105010条・卷之二_续序例下_妇人门","description":"<p>10、月事过多</p>\n<p>属心火盛，脾气弱。</p>\n<p>【忌】破气、降、辛温、苦寒。诸药俱见前。</p>\n<p>【宜】凉血、敛摄、酸平、甘寒。麦冬、生地（泻泄禁用）、青蒿、生甘草、牡丹皮、白芍药、酸枣仁、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '10、月事过多 属心火盛，脾气弱。 【忌】破气、降、辛温、苦寒。诸药俱见前。 【宜】凉血、敛摄、酸平、甘寒。麦冬、生地（泻泄禁用）、青蒿、生甘草、牡丹皮、白芍药、酸枣仁、五味子。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('61GIhENpDEA', 4, '{"title":"第400105009条・卷之二_续序例下_妇人门","description":"<p>9、经行后期</p>\n<p>为血虚。</p>\n<p>【忌】行血、破气、燥热、苦寒。诸药俱见前。</p>\n<p>【宜】补肝肾、甘温、酸温。熟地黄、薯蓣、人参、菟丝子、山茱萸、杜仲、续断、阿胶、艾、五味子、当归、枸杞子、白胶、牛膝。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '9、经行后期 为血虚。 【忌】行血、破气、燥热、苦寒。诸药俱见前。 【宜】补肝肾、甘温、酸温。熟地黄、薯蓣、人参、菟丝子、山茱萸、杜仲、续断、阿胶、艾、五味子、当归、枸杞子、白胶、牛膝。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6K1NTP42aOx', 4, '{"title":"第400105008条・卷之二_续序例下_妇人门","description":"<p>8、经行先期</p>\n<p>为血热。</p>\n<p>【忌】升、补气、辛温、燥热。香附、当归、乌药、艾（已上辛温）。余忌药俱见前。</p>\n<p>【宜】凉血清热、补肝肾，兼降气、甘寒、酸寒、苦寒。生地黄、牡丹皮、白芍药、天门冬、麦门冬、枸杞子、杜仲、青蒿、枇杷叶、苏子、鳖甲、阿胶、黄檗、黄芩、知母。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '8、经行先期 为血热。 【忌】升、补气、辛温、燥热。香附、当归、乌药、艾（已上辛温）。余忌药俱见前。 【宜】凉血清热、补肝肾，兼降气、甘寒、酸寒、苦寒。生地黄、牡丹皮、白芍药、天门冬、麦门冬、枸杞子、杜仲、青蒿、枇杷叶、苏子、鳖甲、阿胶、黄檗、黄芩、知母。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eQw66X17c0H', 4, '{"title":"第400105007条・卷之二_续序例下_妇人门","description":"<p>7、血枯经闭</p>\n<p>由于脾胃薄弱，气血不生。</p>\n<p>【忌】破气、破血、燥热、腻膈滑肠、升发、苦寒。诸药俱见前。</p>\n<p>【宜】补脾胃、甘温、甘平。人参、莲肉、酸枣仁、白扁豆、甘草、茯苓、薯蓣、橘红、白芍药、缩砂蜜、菟丝子、牛膝、牡丹皮、白胶、阿胶、芡实、麦门冬。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '7、血枯经闭 由于脾胃薄弱，气血不生。 【忌】破气、破血、燥热、腻膈滑肠、升发、苦寒。诸药俱见前。 【宜】补脾胃、甘温、甘平。人参、莲肉、酸枣仁、白扁豆、甘草、茯苓、薯蓣、橘红、白芍药、缩砂蜜、菟丝子、牛膝、牡丹皮、白胶、阿胶、芡实、麦门冬。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UGPlcWeRHUK', 4, '{"title":"第400105006条・卷之二_续序例下_妇人门","description":"<p>6、标急而元气不甚惫者，先救其标；标急而元气衰剧者，则当本而标之可也。</p>\n<p>【忌】破气、降、温热。诸药俱见前。</p>\n<p>【宜】补敛、清热、辛甘、苦寒，佐以淡渗。生地黄、人参、白芍药、阿胶、山茱萸、黄檗、五味子、麦门冬、白胶、枸杞子、续断、杜仲、牛膝、白茯苓、车前子、泽泻、蛇床子、香附、补骨脂、牡蛎、艾、二术。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '6、标急而元气不甚惫者，先救其标；标急而元气衰剧者，则当本而标之可也。 【忌】破气、降、温热。诸药俱见前。 【宜】补敛、清热、辛甘、苦寒，佐以淡渗。生地黄、人参、白芍药、阿胶、山茱萸、黄檗、五味子、麦门冬、白胶、枸杞子、续断、杜仲、牛膝、白茯苓、车前子、泽泻、蛇床子、香附、补骨脂、牡蛎、艾、二术。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QvxVO1vKJi0', 4, '{"title":"第400105005条・卷之二_续序例下_妇人门","description":"<p>5、赤带久不止则血虚，宜胶艾四物汤加便煅牡蛎粉、酸枣仁、麦门冬。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '5、赤带久不止则血虚，宜胶艾四物汤加便煅牡蛎粉、酸枣仁、麦门冬。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tfWUdaKfyx7', 4, '{"title":"第400105004条・卷之二_续序例下_妇人门","description":"<p>4、赤淋多因于心火、肝火时炽不已，久而阴血渐虚，中气渐损，遂下赤矣。治宜养心为主，兼以和肝缓中，凉血清气。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '4、赤淋多因于心火、肝火时炽不已，久而阴血渐虚，中气渐损，遂下赤矣。治宜养心为主，兼以和肝缓中，凉血清气。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6e0OX8L4Vz6', 4, '{"title":"第400105003条・卷之二_续序例下_妇人门","description":"<p>3、带下如鸡子清者，脾肾极虚也。面色必不华，足胫必浮，腰腿必酸，宜五味子、八味丸。间用开脾养心之剂，如归脾汤之类。阴虚有火，宜八味丸中加五味子、菟丝子、车前子、黄檗。叔和云：崩中日久为白带，漏下多时肾水枯。盖言崩久气血虚脱，而白滑之物下不止耳。此证虽有气血寒热之分，要归总属于虚。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '3、带下如鸡子清者，脾肾极虚也。面色必不华，足胫必浮，腰腿必酸，宜五味子、八味丸。间用开脾养心之剂，如归脾汤之类。阴虚有火，宜八味丸中加五味子、菟丝子、车前子、黄檗。叔和云：崩中日久为白带，漏下多时肾水枯。盖言崩久气血虚脱，而白滑之物下不止耳。此证虽有气血寒热之分，要归总属于虚。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2326R4JS56T', 4, '{"title":"第400105002条・卷之二_续序例下_妇人门","description":"<p>2、带下如浓泔而臭秽特甚者，湿热甚也，且多有湿痰下坠者，宜苍术、白术、黄檗、黄芩、车前子为主，佐以升提。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2、带下如浓泔而臭秽特甚者，湿热甚也，且多有湿痰下坠者，宜苍术、白术、黄檗、黄芩、车前子为主，佐以升提。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4LdV7aiwt4x', 4, '{"title":"第400105001条・卷之二_续序例下_妇人门","description":"<p>1、赤白带下</p>\n<p>妇人多忧思郁怒，损伤心脾，肝火时发，血走不归经，所以多患赤白带也。白带多是脾虚。盖肝气郁则脾受伤，脾伤则湿土之气下陷，是脾精不守，不能输为荣血，而下白滑之物矣。皆由风木郁于地中使然耳。法当开提肝气，补助脾元。宜以补中益气汤，加酸枣仁、茯苓、山药、黄檗、苍术、麦门冬之类，浓煎，不时饮之。再用六味地黄丸中加牡蛎粉、海螵蛸、杜仲、牛膝，蜜丸，光大如豆。空心饥时吞下五六钱。阳虚火炽加枸杞子、五味子、黄檗。白带多属气虚，补气健脾，治法之要领也。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '2024-12-23T08:05:23.000Z', '1、赤白带下 妇人多忧思郁怒，损伤心脾，肝火时发，血走不归经，所以多患赤白带也。白带多是脾虚。盖肝气郁则脾受伤，脾伤则湿土之气下陷，是脾精不守，不能输为荣血，而下白滑之物矣。皆由风木郁于地中使然耳。法当开提肝气，补助脾元。宜以补中益气汤，加酸枣仁、茯苓、山药、黄檗、苍术、麦门冬之类，浓煎，不时饮之。再用六味地黄丸中加牡蛎粉、海螵蛸、杜仲、牛膝，蜜丸，光大如豆。空心饥时吞下五六钱。阳虚火炽加枸杞子、五味子、黄檗。白带多属气虚，补气健脾，治法之要领也。', '2024-12-23T08:05:23.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'OkfAFj3JDi1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X4t13BcP1iF', 4, '{"title":"第400105116条・卷之二_续序例下_小儿门","description":"<p>16、胎毒</p>\n<p>【忌】补敛、燥热、辛温。诸药俱见前。</p>\n<p>【宜】凉血清热、解毒，兼发散于外。勿从外治，以致热毒内攻。生地黄、玄参、牡丹皮、黄檗、黄连、忍冬藤、甘草、连翘、麦门冬、贝母、犀角、荆芥、鼠粘子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105116,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '16、胎毒 【忌】补敛、燥热、辛温。诸药俱见前。 【宜】凉血清热、解毒，兼发散于外。勿从外治，以致热毒内攻。生地黄、玄参、牡丹皮、黄檗、黄连、忍冬藤、甘草、连翘、麦门冬、贝母、犀角、荆芥、鼠粘子。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QuDLmBKo59I', 4, '{"title":"第400105115条・卷之二_续序例下_小儿门","description":"<p>15、诸虫</p>\n<p>【忌】升，甘。诸药俱见前。</p>\n<p>【宜】杀虫、酸寒、苦寒，佐以辛寒。槟榔、雷丸、使君子、苦楝根、锡灰、鹤虱、芦荟、芍药、乌梅、黄连、黄芩、牵牛。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105115,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '15、诸虫 【忌】升，甘。诸药俱见前。 【宜】杀虫、酸寒、苦寒，佐以辛寒。槟榔、雷丸、使君子、苦楝根、锡灰、鹤虱、芦荟、芍药、乌梅、黄连、黄芩、牵牛。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bDUY03J8IOx', 4, '{"title":"第400105114条・卷之二_续序例下_小儿门","description":"<p>14、疳积</p>\n<p>【忌】破气、酸敛、燥热。诸药俱见前。</p>\n<p>【宜】除疳热，兼消导、苦寒、甘寒，佐以辛寒、辛温。胡黄连、川黄连、肉豆蔻、谷麦糵、神曲、山查、木香、橘皮、白芜荑、使君子、芦会、白术、白芙蓉花、五谷虫、雷丸、青黛、厚朴。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105114,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '14、疳积 【忌】破气、酸敛、燥热。诸药俱见前。 【宜】除疳热，兼消导、苦寒、甘寒，佐以辛寒、辛温。胡黄连、川黄连、肉豆蔻、谷麦糵、神曲、山查、木香、橘皮、白芜荑、使君子、芦会、白术、白芙蓉花、五谷虫、雷丸、青黛、厚朴。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d0PwLzfrs2q', 4, '{"title":"第400105113条・卷之二_续序例下_小儿门","description":"<p>13、慢惊</p>\n<p>多因久吐泻、大病后阴阳两虚而成。</p>\n<p>【忌】破气、下、升、苦寒，及治急惊药。诸药俱见前。</p>\n<p>【宜】补脾健胃、和肝益气、甘温、酸平、佐以辛热。人参、黄耆、茯苓、白芍药、甘草、龙眼肉、酸枣仁、石菖蒲、远志、麦门冬、茯神、冬瓜仁、橘红。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105113,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '13、慢惊 多因久吐泻、大病后阴阳两虚而成。 【忌】破气、下、升、苦寒，及治急惊药。诸药俱见前。 【宜】补脾健胃、和肝益气、甘温、酸平、佐以辛热。人参、黄耆、茯苓、白芍药、甘草、龙眼肉、酸枣仁、石菖蒲、远志、麦门冬、茯神、冬瓜仁、橘红。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SRLBooVDm9J', 4, '{"title":"第400105112条・卷之二_续序例下_小儿门","description":"<p>12、急惊</p>\n<p>【忌】补敛、升、燥热。诸药俱见前。</p>\n<p>【宜】降、清热、镇坠、豁痰、和肝。丹砂、琥珀、牛黄、天竺黄、贝母、竹沥、钓藤钩、僵蚕、茯神、犀角、金箔、胆星、真珠、全蝎、龙脑、麝香、白檀香。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105112,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '12、急惊 【忌】补敛、升、燥热。诸药俱见前。 【宜】降、清热、镇坠、豁痰、和肝。丹砂、琥珀、牛黄、天竺黄、贝母、竹沥、钓藤钩、僵蚕、茯神、犀角、金箔、胆星、真珠、全蝎、龙脑、麝香、白檀香。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6g1YuI5v9eg', 4, '{"title":"第400105111条・卷之二_续序例下_小儿门","description":"<p>11、泄泻</p>\n<p>总忌破气、下、滑利、滞腻。诸药俱见前。</p>\n<p>因食者：宜和胃消食。橘皮、草果、红曲、谷麦糵、白豆蔻、白术、山查、白茯苓、肉豆蔻、缩砂蜜。</p>\n<p></p>\n<p>因湿者：宜燥脾、利水。二术、橘皮、木瓜、茯苓、泽泻、车前子、石斛、黄连、薯蓣、猪苓、升麻、葛根。</p>\n<p></p>\n<p>因暑者：宜前药中加人参、莲肉、白扁豆。</p>\n<p>总之当补脾胃，兼升，兼利小便。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105111,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '11、泄泻 总忌破气、下、滑利、滞腻。诸药俱见前。 因食者：宜和胃消食。橘皮、草果、红曲、谷麦糵、白豆蔻、白术、山查、白茯苓、肉豆蔻、缩砂蜜。 因湿者：宜燥脾、利水。二术、橘皮、木瓜、茯苓、泽泻、车前子、石斛、黄连、薯蓣、猪苓、升麻、葛根。 因暑者：宜前药中加人参、莲肉、白扁豆。 总之当补脾胃，兼升，兼利小便。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rG42dwDM1HQ', 4, '{"title":"第400105110条・卷之二_续序例下_小儿门","description":"<p>10、呕吐</p>\n<p>因伤乳食者。</p>\n<p>【忌】升、苦寒。诸药俱见前。</p>\n<p>【宜】温中、消导。橘皮、缩砂蜜、枳实、厚朴、谷麦糵、草果、山查、红曲、半夏、人参。</p>\n<p></p>\n<p>因寒者：忌破气、升、苦寒。诸药俱见前者。</p>\n<p>【宜】辛热、温中。藿香、橘皮、丁香、人参、白术、生姜、半夏、白豆蔻。</p>\n<p></p>\n<p>因暑者：忌升、破气、温热。诸药俱见前。</p>\n<p>【宜】清暑、补气、安胃，兼利小便。黄连、香薷、人参、木瓜、茯苓、竹茹、石斛、橘皮、甘草、白扁豆、麦门冬、白梅、滑石、木通、泽泻。</p>\n<p></p>\n<p>有虫者：忌升、甘。诸药俱见前。</p>\n<p>【宜】酸敛，佐以苦寒。白芍药、五味子、木瓜、黄连、楝根、乌梅、槟榔、榧子肉、木香、使君子。</p>\n<p>总之，数呕吐宜安胃，久则宜补气。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105110,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '10、呕吐 因伤乳食者。 【忌】升、苦寒。诸药俱见前。 【宜】温中、消导。橘皮、缩砂蜜、枳实、厚朴、谷麦糵、草果、山查、红曲、半夏、人参。 因寒者：忌破气、升、苦寒。诸药俱见前者。 【宜】辛热、温中。藿香、橘皮、丁香、人参、白术、生姜、半夏、白豆蔻。 因暑者：忌升、破气、温热。诸药俱见前。 【宜】清暑、补气、安胃，兼利小便。黄连、香薷、人参、木瓜、茯苓、竹茹、石斛、橘皮、甘草、白扁豆、麦门冬、白梅、滑石、木通、泽泻。 有虫者：忌升、甘。诸药俱见前。 【宜】酸敛，佐以苦寒。白芍药、五味子、木瓜、黄连、楝根、乌梅、槟榔、榧子肉、木香、使君子。 总之，数呕吐宜安胃，久则宜补气。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GhngX3U5UL4', 4, '{"title":"第400105109条・卷之二_续序例下_小儿门","description":"<p>9、痧疹不宜依证施治，惟当治本。本者，手太阴、足阳明二经之邪热也。解其邪热，则诸证自退矣。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105109,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '9、痧疹不宜依证施治，惟当治本。本者，手太阴、足阳明二经之邪热也。解其邪热，则诸证自退矣。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DUV8ZRWXOYX', 4, '{"title":"第400105108条・卷之二_续序例下_小儿门","description":"<p>8、痧后生疮不已，余热未尽故也。宜用金银花、荆芥穗、连翘、玄参、甘草、怀生地、鳖虱胡麻、黄连、木通，浓煎饮之良。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105108,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '8、痧后生疮不已，余热未尽故也。宜用金银花、荆芥穗、连翘、玄参、甘草、怀生地、鳖虱胡麻、黄连、木通，浓煎饮之良。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PgzuLOiOPGT', 4, '{"title":"第400105107条・卷之二_续序例下_小儿门","description":"<p>7、痧后元气不复，脾胃薄弱者，宜用白芍药、炙甘草为君，莲肉、山药、白扁豆、麦门冬、青黛、龙眼肉为臣。多服必渐强，慎勿轻用参、术。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '7、痧后元气不复，脾胃薄弱者，宜用白芍药、炙甘草为君，莲肉、山药、白扁豆、麦门冬、青黛、龙眼肉为臣。多服必渐强，慎勿轻用参、术。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bp2TGlq7TPU', 4, '{"title":"第400105106条・卷之二_续序例下_小儿门","description":"<p>6、疹后牙疳最危，外用牡黄牛粪尖，煅存性，研极细，加真片脑一分，研匀吹之；内用连翘、干葛、荆芥穗、升麻、玄参、黄连、甘草、生地黄，水煎，加生犀角汁二三十匙调服。缓则不可救药。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '6、疹后牙疳最危，外用牡黄牛粪尖，煅存性，研极细，加真片脑一分，研匀吹之；内用连翘、干葛、荆芥穗、升麻、玄参、黄连、甘草、生地黄，水煎，加生犀角汁二三十匙调服。缓则不可救药。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XZV5PwF0tLB', 4, '{"title":"第400105105条・卷之二_续序例下_小儿门","description":"<p>5、痧疹乃肺胃邪热所致，初发时必咳嗽，宜清热透毒，不得止嗽。疹后咳嗽，但用贝母、苦梗、甘草、薄荷、栝楼根、玄参、麦门冬，以清余热、消痰壅，则自愈，慎勿用五味子等收敛之剂。多喘，喘者邪热壅于肺故也，慎勿用定喘药，惟应大剂竹叶石膏汤加西河柳两许，玄参、薄荷各二钱。如冬天寒甚，痧毒郁于内，不得透出者，加蜜酒炒麻黄一剂，立止。凡热势甚者，即用白虎汤加西河柳，忌用升麻，服之必喘。多泄泻，慎勿止泻，惟用黄连、干葛、升麻、甘草、则泻自止。疹家不忌泻，泻则阳明之邪热得解，是亦表里分消之义也。疹后泄泻及便脓血，皆由邪热内陷故也，大忌止涩，惟宜升散，仍用升麻、甘草、干葛、黄连、白芍药、白扁豆。便脓血则加滑石末，必自愈。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '5、痧疹乃肺胃邪热所致，初发时必咳嗽，宜清热透毒，不得止嗽。疹后咳嗽，但用贝母、苦梗、甘草、薄荷、栝楼根、玄参、麦门冬，以清余热、消痰壅，则自愈，慎勿用五味子等收敛之剂。多喘，喘者邪热壅于肺故也，慎勿用定喘药，惟应大剂竹叶石膏汤加西河柳两许，玄参、薄荷各二钱。如冬天寒甚，痧毒郁于内，不得透出者，加蜜酒炒麻黄一剂，立止。凡热势甚者，即用白虎汤加西河柳，忌用升麻，服之必喘。多泄泻，慎勿止泻，惟用黄连、干葛、升麻、甘草、则泻自止。疹家不忌泻，泻则阳明之邪热得解，是亦表里分消之义也。疹后泄泻及便脓血，皆由邪热内陷故也，大忌止涩，惟宜升散，仍用升麻、甘草、干葛、黄连、白芍药、白扁豆。便脓血则加滑石末，必自愈。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7TKvJIfT5Pt', 4, '{"title":"第400105104条・卷之二_续序例下_小儿门","description":"<p>4、痧疹者，手太阴肺、足阳明胃二经之火热发而为病者也。小儿居多，大人亦时有之。殆时气瘟疫之类欤？其证类多咳嗽，多嚏，眼中如泪，多泄泻，多痰，多热，多渴，多烦闷，甚则躁乱，咽痛，唇焦神昏，是其候也。治法当以清凉发散为主。药用辛寒、甘寒、苦寒以升发之。惟忌酸敛，最宜辛散。误施温补，祸不旋踵。辛散如荆芥、西河柳、干葛、石膏、鼠粘子、麻黄；清凉如玄参、竹叶、栝楼根、青黛、薄荷；甘寒如麦门冬、生甘草、蔗浆；苦寒如黄芩、黄连、黄檗、贝母、连翘。随证轻重，制剂大小，中病则已，毋太过焉。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105104,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '4、痧疹者，手太阴肺、足阳明胃二经之火热发而为病者也。小儿居多，大人亦时有之。殆时气瘟疫之类欤？其证类多咳嗽，多嚏，眼中如泪，多泄泻，多痰，多热，多渴，多烦闷，甚则躁乱，咽痛，唇焦神昏，是其候也。治法当以清凉发散为主。药用辛寒、甘寒、苦寒以升发之。惟忌酸敛，最宜辛散。误施温补，祸不旋踵。辛散如荆芥、西河柳、干葛、石膏、鼠粘子、麻黄；清凉如玄参、竹叶、栝楼根、青黛、薄荷；甘寒如麦门冬、生甘草、蔗浆；苦寒如黄芩、黄连、黄檗、贝母、连翘。随证轻重，制剂大小，中病则已，毋太过焉。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HUViI5jn2NU', 4, '{"title":"第400105103条・卷之二_续序例下_小儿门","description":"<p>3、如冬月，佐之以辛散，荆芥、麻黄（去节沫，蜜酒炒，只可用一剂）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105103,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '3、如冬月，佐之以辛散，荆芥、麻黄（去节沫，蜜酒炒，只可用一剂）。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6NDWsXMTAWr', 4, '{"title":"第400105102条・卷之二_续序例下_小儿门","description":"<p>2、痧疹</p>\n<p>此证多有呕吐者，勿治呕吐，但治痧毒，则呕自止，况呕中便有发散之义。</p>\n<p>【忌】破气、温补、酸敛、燥热、辛温、滞腻。诸药俱见前。</p>\n<p>【宜】清热透肌、辛寒、甘寒、苦寒。石膏、鼠粘子、赤柽木（即西河柳）、知母、甘草、玄参、麦门冬、连翘、薄荷、竹叶、黄连、黄芩、葛根、黄檗、蝉蜕、栝楼根、青黛、蔗浆、贝母。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2、痧疹 此证多有呕吐者，勿治呕吐，但治痧毒，则呕自止，况呕中便有发散之义。 【忌】破气、温补、酸敛、燥热、辛温、滞腻。诸药俱见前。 【宜】清热透肌、辛寒、甘寒、苦寒。石膏、鼠粘子、赤柽木（即西河柳）、知母、甘草、玄参、麦门冬、连翘、薄荷、竹叶、黄连、黄芩、葛根、黄檗、蝉蜕、栝楼根、青黛、蔗浆、贝母。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('StFpyKRhcsT', 4, '{"title":"第400105101条・卷之二_续序例下_小儿门","description":"<p>1、痘疮</p>\n<p>血热证：忌温补、燥热。天灵盖、鸡冠血、桑蠹、鲮鲤甲、人齿、官桂、附子、丁香、木香、冰片（已上燥热）、馀忌药俱见前。</p>\n<p>【宜】凉血、活血、解毒、甘寒、苦寒。犀角、生地黄、人中黄、紫草、黄连、麦门冬、牡丹皮、白芍药、童溺、连翘、金银花、玄参、贝母、蝉蜕、鼠粘子。</p>\n<p></p>\n<p>虚寒证：忌汗、吐、下、苦寒、酸寒。诸药俱见前。</p>\n<p>【宜】辛甘发散、补气、温，疮密者佐以解毒。人参、红铅、黄耆、甘草、桂枝、丁香、当归（胃弱大便不闭者禁用）、莲肉、糯米、大枣、龙眼肉、干葛、木香、忍冬藤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '2024-12-23T08:24:26.000Z', '1、痘疮 血热证：忌温补、燥热。天灵盖、鸡冠血、桑蠹、鲮鲤甲、人齿、官桂、附子、丁香、木香、冰片（已上燥热）、馀忌药俱见前。 【宜】凉血、活血、解毒、甘寒、苦寒。犀角、生地黄、人中黄、紫草、黄连、麦门冬、牡丹皮、白芍药、童溺、连翘、金银花、玄参、贝母、蝉蜕、鼠粘子。 虚寒证：忌汗、吐、下、苦寒、酸寒。诸药俱见前。 【宜】辛甘发散、补气、温，疮密者佐以解毒。人参、红铅、黄耆、甘草、桂枝、丁香、当归（胃弱大便不闭者禁用）、莲肉、糯米、大枣、龙眼肉、干葛、木香、忍冬藤。', '2024-12-23T08:24:26.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eUMDgHf5J7z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jQMvVgeaoig', 4, '{"title":"第400105218条・卷之二_续序例下_外科","description":"<p>18、漆疮</p>\n<p>【宜】蟹、茱萸皮、鸡子白、杉材、石蟹、漆姑草、韭莱（炒热罨上）、井中苔萍。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105218,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '18、漆疮 【宜】蟹、茱萸皮、鸡子白、杉材、石蟹、漆姑草、韭莱（炒热罨上）、井中苔萍。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xzllqeEHD4l', 4, '{"title":"第400105217条・卷之二_续序例下_外科","description":"<p>17、火灼</p>\n<p>【忌】燥热及寒物涂罨。井泥、冰、凉水、芭蕉根、醋（已上寒物涂罨）、馀忌药俱见前。</p>\n<p>【宜】拔散火毒、辛散、润、甘寒、辛寒、苦寒。柴胡、葛根、甘草、升麻、黄连、麦门冬、连翘、栝楼根、石膏、黄檗、鸡子油、柏白皮、生胡麻、食盐、豆酱、黄芩、地榆、山栀。</p>\n<p>外用好酒满浸伤处，温即易之。如遍体被伤，用酒满浸，时时易之即不死。一方用蜜水润之。一方石灰水和生芝麻油敷，治已烂臭甚者，神验。一方用粘米炒黑，为末，将菜汁调敷，神效。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105217,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '17、火灼 【忌】燥热及寒物涂罨。井泥、冰、凉水、芭蕉根、醋（已上寒物涂罨）、馀忌药俱见前。 【宜】拔散火毒、辛散、润、甘寒、辛寒、苦寒。柴胡、葛根、甘草、升麻、黄连、麦门冬、连翘、栝楼根、石膏、黄檗、鸡子油、柏白皮、生胡麻、食盐、豆酱、黄芩、地榆、山栀。 外用好酒满浸伤处，温即易之。如遍体被伤，用酒满浸，时时易之即不死。一方用蜜水润之。一方石灰水和生芝麻油敷，治已烂臭甚者，神验。一方用粘米炒黑，为末，将菜汁调敷，神效。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8rfRbVME0QR', 4, '{"title":"第400105216条・卷之二_续序例下_外科","description":"<p>16、踒折挫闪</p>\n<p>忌、宜俱同金疮、跌扑。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105216,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '16、踒折挫闪 忌、宜俱同金疮、跌扑。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aEfETMtA2OD', 4, '{"title":"第400105215条・卷之二_续序例下_外科","description":"<p>15、跌扑损伤</p>\n<p>【忌】同金疮。</p>\n<p>【宜】同金疮。有瘀血停滞者，宜加行血药，如桃仁、红花、苏木、自然铜、䗪虫、千年灰、古文钱之属。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105215,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '15、跌扑损伤 【忌】同金疮。 【宜】同金疮。有瘀血停滞者，宜加行血药，如桃仁、红花、苏木、自然铜、䗪虫、千年灰、古文钱之属。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c9eiL6smlCZ', 4, '{"title":"第400105214条・卷之二_续序例下_外科","description":"<p>14、破伤风</p>\n<p>【忌】同金疮。</p>\n<p>【宜】同金疮，佐以祛风药，如白芷、荆芥、防风、柴胡之属。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105214,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '14、破伤风 【忌】同金疮。 【宜】同金疮，佐以祛风药，如白芷、荆芥、防风、柴胡之属。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eZIC9huKc8f', 4, '{"title":"第400105213条・卷之二_续序例下_外科","description":"<p>13、金疮</p>\n<p>【忌】破气、闭气、升散、酸敛、苦寒、冷利、燥、酸寒。诸药俱见前。</p>\n<p>【【宜】止血、和血、凉血、甘温、甘寒，佐以辛温。地黄、䗪虫、当归、续断、牛膝、甘草、麦门冬、地榆、半夏、茜草、白胶、杜仲、芎、乳香、没药、艾叶、水杨花、钓樟根、黄荆子（炒黑）、王不留行、古钱、自然铜、狗头骨、黄麻皮灰、芦竹箨、韭、大小蓟（内外）、刘寄奴（内外）、花蕊石（内外）、麒麟竭（内外）、古石灰（外）、白蜡（外）、降香（外）、海螵蛸（外）、桑柴灰（外）、人骨灰（外）、紫檀末（外）、三七（外）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105213,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '13、金疮 【忌】破气、闭气、升散、酸敛、苦寒、冷利、燥、酸寒。诸药俱见前。 【【宜】止血、和血、凉血、甘温、甘寒，佐以辛温。地黄、䗪虫、当归、续断、牛膝、甘草、麦门冬、地榆、半夏、茜草、白胶、杜仲、芎、乳香、没药、艾叶、水杨花、钓樟根、黄荆子（炒黑）、王不留行、古钱、自然铜、狗头骨、黄麻皮灰、芦竹箨、韭、大小蓟（内外）、刘寄奴（内外）、花蕊石（内外）、麒麟竭（内外）、古石灰（外）、白蜡（外）、降香（外）、海螵蛸（外）、桑柴灰（外）、人骨灰（外）、紫檀末（外）、三七（外）。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HkU0AM0Q7eU', 4, '{"title":"第400105212条・卷之二_续序例下_外科","description":"<p>12、阴蚀（即下部疮）</p>\n<p>【忌】同乳岩。</p>\n<p>【宜】凉血活血、除热散毒、苦寒、辛寒。青黛、茜草、苦参、鲜地骨皮、黄檗、小蓟、艾叶、马鞭草、木瓜、牛膝、木通、全蝎（外）、蛇床子（外）、橄榄核（外）、蛀竹屑（外）、猪脊髓（外）、青葙子（外）、腻粉（外）、官粉（外）、杏仁（外）、珠末（外）、皂角末（外）、铅丹（外）、象牙末（外）、龙脑香（外）、白僵蚕（外）、粉霜（外）、烟膏（外）、天灵盖（外）、滴乳石（外）、白蜡（外）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105212,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '12、阴蚀（即下部疮） 【忌】同乳岩。 【宜】凉血活血、除热散毒、苦寒、辛寒。青黛、茜草、苦参、鲜地骨皮、黄檗、小蓟、艾叶、马鞭草、木瓜、牛膝、木通、全蝎（外）、蛇床子（外）、橄榄核（外）、蛀竹屑（外）、猪脊髓（外）、青葙子（外）、腻粉（外）、官粉（外）、杏仁（外）、珠末（外）、皂角末（外）、铅丹（外）、象牙末（外）、龙脑香（外）、白僵蚕（外）、粉霜（外）、烟膏（外）、天灵盖（外）、滴乳石（外）、白蜡（外）。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MfU0eFQGbGB', 4, '{"title":"第400105211条・卷之二_续序例下_外科","description":"<p>11、乳岩、乳痈、内外吹</p>\n<p>【忌】补气、升、温补、辛热、燥、酸敛。</p>\n<p>【宜】散结气、和肝、凉血活血，清热解毒。贝母、橘叶、连翘、栝楼根、山慈菇、山豆根、蒲公英、紫花地丁、黄连、甘草、柴胡、白芷、青皮、橘皮、牡鼠粪、王不留行、乳香、没药、漏芦、夏枯草、忍冬藤、栝楼仁、头垢、人爪、鲮鲤甲、半枝莲、茜根。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105211,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '11、乳岩、乳痈、内外吹 【忌】补气、升、温补、辛热、燥、酸敛。 【宜】散结气、和肝、凉血活血，清热解毒。贝母、橘叶、连翘、栝楼根、山慈菇、山豆根、蒲公英、紫花地丁、黄连、甘草、柴胡、白芷、青皮、橘皮、牡鼠粪、王不留行、乳香、没药、漏芦、夏枯草、忍冬藤、栝楼仁、头垢、人爪、鲮鲤甲、半枝莲、茜根。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YsifpZ125eX', 4, '{"title":"第400105210条・卷之二_续序例下_外科","description":"<p>10、通肠漏</p>\n<p>【忌】破气、下、发散、温燥、辛热。诸药俱见前。</p>\n<p>【宜】凉血、清利湿热、解毒、消漏管、补气血、长肉。槐实、黄连、黄芩、青黛、地榆、白及、忍冬藤、半枝莲、生地黄（已上凉血解毒）、猪悬蹄、黄牛角䚡、刺猬皮、蛀竹屑、明矾、金头蜈蚣（已上消漏管）、黄耆、熟地黄、当归、人参、白芍药、五味子、牛膝、山药、枯矾、黄蜡、白蜡、麻皮灰、铅华、月经布、没食子（已上补气血长肉）、天明精、地骨皮（俱要鲜者）、皮硝、文蛤（已上煎浓汤熏洗）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105210,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '10、通肠漏 【忌】破气、下、发散、温燥、辛热。诸药俱见前。 【宜】凉血、清利湿热、解毒、消漏管、补气血、长肉。槐实、黄连、黄芩、青黛、地榆、白及、忍冬藤、半枝莲、生地黄（已上凉血解毒）、猪悬蹄、黄牛角䚡、刺猬皮、蛀竹屑、明矾、金头蜈蚣（已上消漏管）、黄耆、熟地黄、当归、人参、白芍药、五味子、牛膝、山药、枯矾、黄蜡、白蜡、麻皮灰、铅华、月经布、没食子（已上补气血长肉）、天明精、地骨皮（俱要鲜者）、皮硝、文蛤（已上煎浓汤熏洗）。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nqM8tTs0MZ3', 4, '{"title":"第400105209条・卷之二_续序例下_外科","description":"<p>9、痔（有内外二证）</p>\n<p>【忌】破气、降、燥热、辛温。诸药俱见前。</p>\n<p>【宜】凉血、活血、除大肠热，兼升。去血过多者宜补血、甘寒、苦寒、酸寒，佐以辛寒。生地黄、五倍子、黄连、黄芩、白芍药、地榆、猬皮、大小蓟、黄檗、侧柏叶、槐实、皂荚灰、熊胆、升麻、鳖甲、红蓝花、龙脑香、茜草、黄耆、赤石脂、猪悬蹄、蛇蜕、榧实、白矾、金银花、青黛、象牙末、蛀竹屑、牛角䚡、白蜡。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105209,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '9、痔（有内外二证） 【忌】破气、降、燥热、辛温。诸药俱见前。 【宜】凉血、活血、除大肠热，兼升。去血过多者宜补血、甘寒、苦寒、酸寒，佐以辛寒。生地黄、五倍子、黄连、黄芩、白芍药、地榆、猬皮、大小蓟、黄檗、侧柏叶、槐实、皂荚灰、熊胆、升麻、鳖甲、红蓝花、龙脑香、茜草、黄耆、赤石脂、猪悬蹄、蛇蜕、榧实、白矾、金银花、青黛、象牙末、蛀竹屑、牛角䚡、白蜡。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CyjL0wICjGN', 4, '{"title":"第400105208条・卷之二_续序例下_外科","description":"<p>8、瘿瘤</p>\n<p>忌、宜俱同瘰疬，兼宜薜荔、半夏、文蛤、南星、通草、生姜。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105208,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '8、瘿瘤 忌、宜俱同瘰疬，兼宜薜荔、半夏、文蛤、南星、通草、生姜。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k2tjK1kcMJI', 4, '{"title":"第400105207条・卷之二_续序例下_外科","description":"<p>7、瘰疬（马刀疮附）</p>\n<p>同属少阳胆经，治法亦同。</p>\n<p>【忌】补气、辛热、酸敛。诸药俱见前。</p>\n<p>【宜】清热散结、和肝凉胆、苦寒、甘寒、咸寒，佐以辛寒。连翘、玄参、忍冬藤、紫背天葵、乳香、麝香、夏枯草、鼠粘子、贝母、天明精、没药、薄荷、肥皂荚、皂角子、何首乌、柴胡、黄芩、甘草、昆布、牡蛎、鳖甲、栝楼根、恶实、漏芦、守宫（煅）、猫头、天荷叶、映山红、海藻、海蛤、苏合油、雄黄、矾石、斑猫、蟾酥、鳖虱胡麻、回燕窝泥。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105207,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '7、瘰疬（马刀疮附） 同属少阳胆经，治法亦同。 【忌】补气、辛热、酸敛。诸药俱见前。 【宜】清热散结、和肝凉胆、苦寒、甘寒、咸寒，佐以辛寒。连翘、玄参、忍冬藤、紫背天葵、乳香、麝香、夏枯草、鼠粘子、贝母、天明精、没药、薄荷、肥皂荚、皂角子、何首乌、柴胡、黄芩、甘草、昆布、牡蛎、鳖甲、栝楼根、恶实、漏芦、守宫（煅）、猫头、天荷叶、映山红、海藻、海蛤、苏合油、雄黄、矾石、斑猫、蟾酥、鳖虱胡麻、回燕窝泥。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0bPUh3cI532', 4, '{"title":"第400105206条・卷之二_续序例下_外科","description":"<p>6、疔疮</p>\n<p>【忌】补敛、温热。诸药俱见前。</p>\n<p>【宜】凉血活血、解毒、祛风、汗、下。生甘草、辟虺雷、茜草、生地草、贝母、紫花地丁、白药子、大黄、金银花、苍耳草、连翘、夏枯草、鼠粘子、矾石（已上内）、半枝莲、牛黄、蟾酥、红药子、白及、白敛（已上内外）、龙脑、铁锈、桑硇、铜青、雄黄（已上外）。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '6、疔疮 【忌】补敛、温热。诸药俱见前。 【宜】凉血活血、解毒、祛风、汗、下。生甘草、辟虺雷、茜草、生地草、贝母、紫花地丁、白药子、大黄、金银花、苍耳草、连翘、夏枯草、鼠粘子、矾石（已上内）、半枝莲、牛黄、蟾酥、红药子、白及、白敛（已上内外）、龙脑、铁锈、桑硇、铜青、雄黄（已上外）。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9hF5ETOysnr', 4, '{"title":"第400105205条・卷之二_续序例下_外科","description":"<p>5、溃疡</p>\n<p>【忌】闭气、苦寒、破气，又忌躁。诸药俱见前。</p>\n<p>【宜】补气血、甘、酸温，佐以解毒。人参、红铅、胎骨、黄耆、当归、地黄、芍药、甘草、白及、白敛、忍冬藤、甘菊花、贝母、薯蓣、大枣、五味子、麦门冬。</p>\n<p>散毒（外傅）。雄黄、雌黄、粉锡、矾石、龙脑香、松脂、地榆、水银粉、铁锈、白及、白敛、漏芦、檗木、青葙子、楝实、䕡茹、石灰、铁浆、苦参、菖蒲、槲皮、葵根、柳华、五加皮、梓叶、苎根、紫草、马鞭草、艾（灸）。</p>\n<p></p>\n<p>止痛排脓（外傅）。白及、白敛、大黄、乳香、没药、丹砂、红药子、龙脑、金华、白药子、麦饭石、米醋、蜜。</p>\n<p></p>\n<p>去瘀肉（外傅）。巴豆膏、轻粉、粉霜、乌梅肉灰。</p>\n<p></p>\n<p>蚀脓（外傅）。蛀竹屑、䕡茹、雄黄、白芷、大黄、巴豆、地榆、枯矾。</p>\n<p></p>\n<p>长肉收口（外傅）。仙人杖（烧油）、人参、金华、白蜡、黄蜡、血竭、蛀竹屑、枯矾末、黄芩末、珠末、象牙末、铅丹、红粉霜、胡粉、芝麻油、猪蹄汤。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105205,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '5、溃疡 【忌】闭气、苦寒、破气，又忌躁。诸药俱见前。 【宜】补气血、甘、酸温，佐以解毒。人参、红铅、胎骨、黄耆、当归、地黄、芍药、甘草、白及、白敛、忍冬藤、甘菊花、贝母、薯蓣、大枣、五味子、麦门冬。 散毒（外傅）。雄黄、雌黄、粉锡、矾石、龙脑香、松脂、地榆、水银粉、铁锈、白及、白敛、漏芦、檗木、青葙子、楝实、䕡茹、石灰、铁浆、苦参、菖蒲、槲皮、葵根、柳华、五加皮、梓叶、苎根、紫草、马鞭草、艾（灸）。 止痛排脓（外傅）。白及、白敛、大黄、乳香、没药、丹砂、红药子、龙脑、金华、白药子、麦饭石、米醋、蜜。 去瘀肉（外傅）。巴豆膏、轻粉、粉霜、乌梅肉灰。 蚀脓（外傅）。蛀竹屑、䕡茹、雄黄、白芷、大黄、巴豆、地榆、枯矾。 长肉收口（外傅）。仙人杖（烧油）、人参、金华、白蜡、黄蜡、血竭、蛀竹屑、枯矾末、黄芩末、珠末、象牙末、铅丹、红粉霜、胡粉、芝麻油、猪蹄汤。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UZBazOn2WvW', 4, '{"title":"第400105204条・卷之二_续序例下_外科","description":"<p>4、痈疽毒气攻心，发谵语</p>\n<p>【宜】以生绿豆粉、丹砂、乳香，为丸服之。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105204,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '4、痈疽毒气攻心，发谵语 【宜】以生绿豆粉、丹砂、乳香，为丸服之。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RvwlOSFeoNm', 4, '{"title":"第400105203条・卷之二_续序例下_外科","description":"<p>3、肿疡</p>\n<p>忌、宜俱同痈疽。先后发渴，更忌当归。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105203,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '3、肿疡 忌、宜俱同痈疽。先后发渴，更忌当归。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MvdsXAIun1y', 4, '{"title":"第400105202条・卷之二_续序例下_外科","description":"<p>2、痈疽先后发渴</p>\n<p>【忌】升、破气、辛温、燥热、吐、下。诸药俱见前。</p>\n<p>【宜】活血、凉血、解毒散结。生地黄、连翘、忍冬藤、白芷、白及、白敛、茜草、紫花地丁、夏枯草、甘菊花、地榆、贝母、鼠粘子、黄檗、栝楼根、乳香、没药、芍药、生绿豆、半枝莲、白药子、红药子、黄蜡、明矾。</p>\n<p>已溃者加人参、黄耆、麦门冬、五味子。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2、痈疽先后发渴 【忌】升、破气、辛温、燥热、吐、下。诸药俱见前。 【宜】活血、凉血、解毒散结。生地黄、连翘、忍冬藤、白芷、白及、白敛、茜草、紫花地丁、夏枯草、甘菊花、地榆、贝母、鼠粘子、黄檗、栝楼根、乳香、没药、芍药、生绿豆、半枝莲、白药子、红药子、黄蜡、明矾。 已溃者加人参、黄耆、麦门冬、五味子。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JLvj5kQAeGl', 4, '{"title":"第400105201条・卷之二_续序例下_外科","description":"<p>1、疬风</p>\n<p>【忌】破气、酸敛、燥热、下。诸药俱见前。</p>\n<p>【宜】凉血、杀虫、祛风、苦寒，佐以辛寒辛平。豨莶、天门冬、甘菊花、生地黄、青黛、漆叶、苦参、何首乌、鳖虱胡麻仁、白芷、荆芥、天麻、续断、羌、独活、半枝莲、白花蛇、乌梢蛇、皂角刺。</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '2024-12-23T08:37:04.000Z', '1、疬风 【忌】破气、酸敛、燥热、下。诸药俱见前。 【宜】凉血、杀虫、祛风、苦寒，佐以辛寒辛平。豨莶、天门冬、甘菊花、生地黄、青黛、漆叶、苦参、何首乌、鳖虱胡麻仁、白芷、荆芥、天麻、续断、羌、独活、半枝莲、白花蛇、乌梢蛇、皂角刺。', '2024-12-23T08:37:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'MFU1LNRaXHa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('20aPxkfQTjK', 4, '{"title":"第400105301条・卷之三_玉石部上品","description":"<p>1、丹砂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105301,"note":"       味甘，微寒，无毒。主身体五藏百病，养精神，安魂魄，益气明目，通血脉，止烦满消渴，益精神，悦泽人面。杀精魅邪恶鬼，除中恶腹痛，毒气，疥瘘诸疮。久服通神明不老，轻身神仙。能化为汞。作末名真朱。光色如云母，可析者良。（恶磁石，畏碱水。）\n\n       疏：丹砂本禀地二之火气以生，而兼得乎天七之气以成。色赤法火，中含水液。为龙为汞，亦曰阴精。七为阳火之少，故味甘微寒而无毒，盖指生砂而言也。《药性论》云：丹砂为清镇少阴君火之上药，辟除鬼魅百邪之神物。安定神明则精气自固，火不妄炎则金木得平，而魂魄自定，气力自倍。五脏皆安则精华上发，故明目。心主血脉，心火宁谧，则阴分无热而血脉自通，烦满自止，消渴自除矣。杀精魅邪恶鬼，除中恶腹痛者，阳明神物，故能辟除不祥，消散阴恶杀厉之气也。久服通神明不老者，古之真人，飞丹炼石，引纳清和，配以金铅，按之法象，自能合丹道而成变化也。青霞子及太清服炼灵砂法云：能重能轻，能暗能明，能黑能白，能神能灵。一斛人擎，力难举升：万斤遇火，轻速上腾。鬼神寻求，莫知所在。先禀气于甲，受气于丙，出胎见壬，结魄成庚，增光归戊，阴阳升降，各本其原。非虚语矣！\n\n【主治参与】\n        丹砂研飞极细，令状如飞尘，以甘草、生地黄浓煎，调分许，与儿初生时服之，能止胎惊，解胎毒。\n同真珠、琥珀、金箔、牛黄、生犀角、天竺黄、滑石末，治小儿急惊，有神。\n入六一散，治暑气伏于心经，神昏口渴，及泄泻如火热。\n入补心丹，镇心神，定魂魄。\n入乳香托里散，散痈疽热毒，发热疼痛，及毒气攻心发谵语。\n\n【简误】\n       丹砂为八石之主，故列石部之首。体中含汞，汞味本辛，故能杀虫、杀精魅。宜乎《药性论》谓其有大毒。若经伏火，及一切烹炼，则毒等砒、硇，服之必毙。自唐以来，上而人主，下而缙绅，曾饵斯药，鲜克免者。戒之！戒之！","videoMemo":"","fangList":[],"bieMing":"丹砂"}}', '2024-12-23T08:51:43.000Z', '2024-12-23T08:51:43.000Z', '2024-12-23T08:51:43.000Z', '1、丹砂', '2024-12-23T08:51:43.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o8LvaqzCdtk', 4, '{"title":"第400105304条・卷之三_玉石部上品","description":"<p>4、矾石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105304,"note":"       味酸，寒，无毒。主寒热，泄痢，白沃，阴蚀恶疮，目痛，坚骨齿，除固热在骨髓，去鼻中息肉。炼饵服之，轻身不老增年。岐伯云：久服伤人骨，能使铁为铜。生河西山谷，及陇西武都石门。（甘草为之使。恶牡蛎，畏麻黄）\n\n疏：矾石味酸，气寒而无毒。其性燥急，收涩解毒，除热坠浊。盖寒热泄痢，皆湿热所为；妇人白沃，多由虚脱，涩以止脱故也。阴蚀恶疮，亦缘湿火。目痛多由风热，除固热在骨髓，坚齿者，髓为热所劫则空，故骨痿而齿浮。矾性入骨除热，故亦主之。去鼻中息肉者，消毒除热燥湿之功也。\n\n【主治参与】\n矾石即白矾，得巴豆同煅令枯。取矾研末，以鹅翎管吹入喉中，流出热涎立解。喉痹其证，俗呼为缠喉风是也。\n皮肤疥癣，脓窠、坐板、肥疳等疮，皆资其用，各合所宜以施之。\n得硫黄、雄黄、白附子、海金沙、蜜陀僧，擦汗斑殊效。一年者去皮一次，十年者去皮十次。擦后坐卧勿当风，勿行房摇扇。\n制半夏，能散湿痰及食积痰，兼除五饮。\n同芒硝可烧水银成粉，治一切疮中有虫。\n得黄蜡和丸，名蜡矾丸，治一切疮毒有神。凡治痈疽，当服之以护膜，膜苟不破，虽剧必瘥。\n\n陈师古方：中风痰厥，四肢不收，气闭膈塞者，白矾一两，牙皂角五钱，为末。每服一钱，温水调下，吐痰为度。\n\n《简要济众方》：牙齿肿痛，白矾一两烧灰，大露蜂房一两微炙，每二钱水煎，含漱去涎。\n《千金方》：鼻中息肉：用明矾一两，蓖麻仁七粒，盐梅肉五个，麝香一字，捣丸，绵裹塞之，化水自下也。\n夏子益《奇疾方》：发斑怪证：有人眼赤鼻张，大喘，浑身出斑，毛发如铜铁，乃热毒气结于下焦也。白矾、滑石各一两为末。水三碗，煎减半，不住，服尽即安。\n《永类钤方》：烂弦风眼，白矾煅一两，铜青三钱，研末，汤泡澄清，点洗。\n《千金方》：脚气冲心：白矾三两，水一斗五升，煎沸浸洗。\n张仲景《金匮》方：女劳黄疸，日晡发热而反恶寒，膀胱急，少腹满，目尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也，自大劳大热交接后入水所致。腹满者难治。用矾石烧，硝石熬黄，等分为散。以大麦粥汁和服方寸匕，日三服。病从大小便去。\n又《金匮》方：妇人白沃，经水不利，子脏坚癖，中有干血，下白物：用矾石三分烧，杏仁一分，研匀，蜜丸枣核大，纳入肠中，日一易之。\n《千金翼》：妇人阴脱作痒，矾石烧研，空心酒服方寸匕，日三。\n\n刘禹锡《传信方》：蛇咬蝎螫：烧刀矛头令赤，置白矾于上，汁出，热滴之，立瘥。此神验之方也。\n\n【简误】\n白矾，《本经》主寒热泄痢，此盖指泄痢久不止，虚脱滑泄，因发寒热。矾性过涩，涩以止脱，故能主之。假令湿热方炽，积滞正多，误用收涩，为害不一。慎之！妇人白沃，多由虚脱。故用收涩以固其标，终非探本之治。目痛不由弩肉及有外障，亦非所宜。除固热在骨髓，仅可资其引导，若谓其独用，反有损也。矾性燥急而能劫水，故不利齿骨。齿者骨之余故也。岐伯云：久服伤人骨。故凡阴虚内热，火炽水涸，发为咽喉痛者，不宜含此。目痛由阴虚血热者，亦不宜用劫水损骨之药，岂可炼服，轻身不老增年？徒虚语耳！\n","videoMemo":"","fangList":[],"bieMing":"矾石"}}', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '4、矾石', '2024-12-23T09:07:42.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XF5ItTLwEbs', 4, '{"title":"第400105303条・卷之三_玉石部上品","description":"<p>3、石钟乳</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105303,"note":"      味甘，温，无毒。主咳逆上气，明目益精，安五藏，通百节，利九窍，下乳汁，益气，补虚损，疗脚弱疼冷，下焦伤竭，强阴。久服延年益寿，好颜色，不老，令人有子。不炼服之，令人淋。（蛇床为之使。恶牡丹、玄参、紫石英。）\n\n疏：石钟乳禀石之气而生。《本经》谓其味甘，气温，无毒。吴普曰：神农辛。斯言近之。甄权以为有大毒，或是经火之故。应云味甘辛，气大温，其性得火则有大毒，乃为得之。其主咳逆上气者，以气虚则不能归元，发为斯证。乳性温而镇坠，使气得归元则病自愈，故能主之也。通百节、利九窍、下乳汁者，辛温之力也。疗脚弱疼冷者，亦是阳气下行之验也。甄权主寒嗽、通声者，辛以散邪结，温以祛寒气故也。其他种种补益之说，当是前人好事者溢美之辞。夷考其性，恐无是理，未足信也。\n\n【主治参与】\n石钟乳得牛黄、白蜡、象牙末、真珠、乳香、没药、桦皮灰、龟板灰，俱存性细研，枯白矾、蛀竹屑、红铅，治广疮结毒，烂环鼻梁，及阴蚀阳物，有神。\n孙真人《千金翼》钟乳煎：治风虚劳损，腰脚无力，补益强壮。用钟乳粉炼成者三两，以夹绢袋盛之，牛乳一大升，煎减三之一，去袋饮乳，分二服，日一作。不吐不利，虚冷人微溏无所苦。一袋可煮三十度，力尽别作袋。每煎迄，须濯净，令通气。其滓和面，煨鸡子食之，此崔尚书方也。\n\n《宣明方》治一切劳嗽，胸膈痞满，焚香透膈散：用鹅管石、雄黄、佛耳草、款冬花，等分为末。每用一钱，安香炉上焚之，以筒吸烟入喉中，日二次。\n《圣济总录》治肺虚喘急，连绵不息。生钟乳粉光明者五钱，蜡三两和化，饭甑内蒸熟，研丸如梧子大。每水下一丸。\n《外台秘要》治乳汁不通，气少血衰，脉涩不行，故少乳。炼成钟乳粉二钱，浓煎漏芦汤调下，或通草等分为末，米饮服方寸匕，日三服。\n\n【简误】\n石钟乳辛温，若加火炼，有毒无疑。纵治虚寒，尚须审察，况病涉温热者耶？世人病阴虚有热者十之九，阳虚内寒者百之一。是以自唐迄今，因服钟乳而发病者不可胜纪，服之而获效得力者不闻一二。其于事理，可以烛照。经曰：石药之性悍。味斯言也，则其大略可概见已。慎毋轻信方士之言，致蹈前人覆辙。尊生之士，宜安常处，顺以道理，自持修短有命，无惑乎长年之说，庶不为其所误矣。","videoMemo":"","fangList":[],"bieMing":"石钟乳"}}', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '3、石钟乳', '2024-12-23T09:07:42.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wFJTWVkgVhH', 4, '{"title":"第400105302条・卷之三_玉石部上品","description":"<p>2、云母</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105302,"note":"        味甘，平，无毒。主身皮死肌，中风寒热，如在车船上。除邪气，安五藏，益子精。明目，下气，坚肌，续绝补中，疗五劳七伤，虚损少气，止痢。久服轻身延年，悦泽不老，耐寒暑，志高神仙。一名云珠，色多赤；一名云华，五色具；一名云英，色多青；一名云液，色多白；一名云砂，色青黄；一名磷石，色正白。（泽泻为之使，忌羊血，用矾石则柔烂。）\n\n        疏：云母《本经》载其味甘，气平，详其主治，亦应有温。韩保升曰：云母色白而主肺，此石药中温良之品也。以其法金，故主身皮死肌，及中风寒热，如在车船上。甘能缓，温能和，故除邪气。石性镇坠，能使火下，火下则水上，是既济之象也，故安五脏，益子精，明目，久服轻身延年。《别录》主下气，坚肌，续绝补中，疗五劳七伤，虚损少气，久服悦泽不老，耐寒暑，志高神仙，皆此意也。其曰止痢者，久痢则肠胃俱虚，甘温足以回其虚，下坠足以去其积，故亦主之也。\n\n【主治参与】\n云母得铅丹熬成膏，可贴一切痈疽疮毒。和以升丹细末，更著奇效。\n\n《经验方》云：青城山丈人观主康道丰治百病云母粉方：用云母一斤，析开，揉入大瓶内，筑实封固，以十斤顶火煅赤取出，却拌香葱、紫连翘草二件，合捣如泥，后以夹绢袋盛，于大水盆内摇取粉，余滓未尽，再添草药重捣取粉。于木盆一面贮灰，于灰上印一潜坑，铺纸倾粉在内，候干焙之，以面糊丸梧子大。遇有疾者，服之无不效。知成都府辛谏议，曾患大风，众医不愈，道丰进此，服之神验。\n\n《千金方》服食云母法：上白云母二十斤，薄劈，以露水八斗作汤，分半淘净二次。又作二斗汤，纳芒硝十斤，木器中浸二十日，取出绢袋盛，悬屋上，勿见风日，令燥。以鹿皮为囊揉之，从旦至午，筛滓复揉，得好粉二十斤，搅糊，入竹筒内，薄削封口漆固，北垣南下，入地六尺，覆土。春夏四十日，秋冬三十日出之，当成水。若洞洞不消，更埋三十日。此水能治万病，及劳气风疼。每以温水一合和服之，日三服。十日小便当变黄，二十日腹中寒澼消，三十日龋齿更生，四十日不畏风寒，五十日诸病皆愈，颜色日少，长生神仙。\n\n《深师方》：治痰饮头痛，往来寒热。云母粉二两，炼过，常山一两，为末。每服方寸匕，汤服取吐，忌生葱、生菜。\n\n仲景《金匮》方：治牝疟多寒。云母烧二日夜，龙骨、蜀漆烧去腥，等分为末。发前浆水服半钱。\n\n《千金方》治赤白久痢，积年不愈。饮调云母粉方寸匕服，神效。\n又方，治妇人带下，水和云母粉方寸匕，神效。\n\n《积德堂方》治妇人难产，经日不生，云母粉半两，温酒调服，入口即产，不顺者即顺，万不失一。陆氏云：此是何德扬方也。已救三五十人。\n《千金方》治风疹遍身，百计不愈。煅云母粉，清水调服二钱良。又方：治一切恶疮，用云母粉傅之。\n《圣惠方》治火疮败坏。云母粉和生羊髓傅之。\n《事林广记》治金疮出血，云母粉傅之。绝妙。\n《千金翼》治风热汗出，水和云母粉，服三钱，不过再服，立愈。\n\n【简误】\n云母性虽甘平，终属石种，与脏腑气血，实非同类，只宜用以治病取效。若夫益精明目，轻身延年，耐寒暑，志高神仙，皆必不然之论也。始俟世人试过，乃敢信耳。","videoMemo":"","fangList":[],"bieMing":"云母"}}', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '2024-12-23T09:07:42.000Z', '2、云母', '2024-12-23T09:07:42.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IuEC36oMiJf', 4, '{"title":"第400105314条・卷之三_玉石部上品","description":"<p>14、铁锈</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105314,"note":"      味甘，微寒，无毒。主身体五藏百病，养精神，安魂魄，益气明目，通血脉，止烦满消渴，益精神，悦泽人面。杀精魅邪恶鬼，除中恶腹痛，毒气，疥瘘诸疮。久服通神明不老，轻身神仙。能化为汞。作末名真朱。光色如云母，可析者良。（恶磁石，畏碱水。）\n\n      疏：丹砂本禀地二之火气以生，而兼得乎天七之气以成。色赤法火，中含水液。为龙为汞，亦曰阴精。七为阳火之少，故味甘微寒而无毒，盖指生砂而言也。《药性论》云：丹砂为清镇少阴君火之上药，辟除鬼魅百邪之神物。安定神明则精气自固，火不妄炎则金木得平，而魂魄自定，气力自倍。五脏皆安则精华上发，故明目。心主血脉，心火宁谧，则阴分无热而血脉自通，烦满自止，消渴自除矣。杀精魅邪恶鬼，除中恶腹痛者，阳明神物，故能辟除不祥，消散阴恶杀厉之气也。久服通神明不老者，古之真人，飞丹炼石，引纳清和，配以金铅，按之法象，自能合丹道而成变化也。青霞子及太清服炼灵砂法云：能重能轻，能暗能明，能黑能白，能神能灵。一斛人擎，力难举升：万斤遇火，轻速上腾。鬼神寻求，莫知所在。先禀气于甲，受气于丙，出胎见壬，结魄成庚，增光归戊，阴阳升降，各本其原。非虚语矣！\n\n【主治参与】\n        丹砂研飞极细，令状如飞尘，以甘草、生地黄浓煎，调分许，与儿初生时服之，能止胎惊，解胎毒。\n\n同真珠、琥珀、金箔、牛黄、生犀角、天竺黄、滑石末，治小儿急惊，有神。\n\n入六一散，治暑气伏于心经，神昏口渴，及泄泻如火热。\n\n入补心丹，镇心神，定魂魄。\n\n入乳香托里散，散痈疽热毒，发热疼痛，及毒气攻心发谵语。\n\n【简误】\n        丹砂为八石之主，故列石部之首。体中含汞，汞味本辛，故能杀虫、杀精魅。宜乎《药性论》谓其有大毒。若经伏火，及一切烹炼，则毒等砒、硇，服之必毙。自唐以来，上而人主，下而缙绅，曾饵斯药，鲜克免者。戒之！戒之！","videoMemo":"","fangList":[],"bieMing":"铁锈"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '14、铁锈', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JvsOYHLUgL4', 4, '{"title":"第400105313条・卷之三_玉石部上品","description":"<p>13、绿矾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105313,"note":"          凉，无毒。治喉痹，蚛牙，口疮，及恶疮疥癣。酿鲫鱼，烧灰和服，疗肠风泻血。（一名皂矾，煅赤醋淬为矾红，又名青矾。）\n\n疏：绿矾气味所禀与白矾同，其酸涌涩收，燥湿解毒，化涎之功，亦与白矾相似而力差缓。本经主喉痹者，酸涌化涎之功也。蚛牙口疮、恶疮疥癣者，燥湿除热解毒之功也。肠风泻血者，消散湿热之后复有收涩之功也。然而诸治之外，又善消积滞，凡腹中坚，肉积，诸药不能化者，以矾红同健脾消食药为丸，投之辄消。\n\n【主治参与】\n          得红曲、山查、肉豆蔻，消肉积。加麦芽、橘皮、草果、槟榔、三棱、蓬荗，消一切肉积，及米面食坚积。脾病黄肿，用绿矾四两，煅成赤珠子，当归四两，酒浸七日焙，百草霜三两，为末，以浸药酒，打糊丸梧子大。每服五丸至七丸，温水下。一月后黄去，立效。\n\n杨真人《济急方》酒黄水肿，黄肿积痛：青矾半斤，醋一大碗，和匀，瓦盆内煅干为度，平胃散、乌药顺气散各半两，为末，醋煮糊丸梧子大，姜汤下二三十丸。\n\n《救急方》食劳黄病，身目俱黄：青矾，锅内安炭煅赤，米醋拌为末，枣肉和丸梧子大。每服二三十丸，食后姜汤下。\n\n《圣惠方》腹中食积：绿矾二两研，米醋一大碗，瓷器煎之，柳条搅成膏，入赤脚乌一两研，丸绿豆大。每空心温酒下五丸。\n\n谈野翁《试验方》走马疳疮：绿矾煅红，以醋拌匀，如此三次，为末，入麝香少许，温浆水漱净，掺之。应加龙脑、雄黄、蓬砂、芒硝。\n\n【简误】\n绿矾、矾红，虽能消肉食坚积，然能令人作泻，胃弱人不能多用，服此者终身忌食荞麦，犯之立毙。","videoMemo":"","fangList":[],"bieMing":"绿矾"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '13、绿矾', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E7yXXFeKDj2', 4, '{"title":"第400105312条・卷之三_玉石部上品","description":"<p>12、无名异</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105312,"note":"       味甘，平，无毒。主金疮折伤内损，止痛，生肌肉。\n\n         疏：无名异禀地中阴水之气以生，本经味甘、气平、无毒，苏颂咸寒。咸能入血，甘能补血，寒能除热，故主金疮折伤内损，及止痛生肌肉也。苏颂：醋摩傅肿毒痈疽者，亦取其活血凉血之功耳。\n\n【主治参与】\n《集验方》打伤肿痛：无名异为末，酒服，赶下四肢，瘀血皆散矣。\n\n《多能鄙事》损伤接骨：无名异、甜瓜子各一两，乳香、没药各一钱，为末。每服五钱，热酒调服，小儿三钱。服毕，以黄米粥涂纸上，掺左顾牡蛎末裹之，竹篦夹住。\n\n谈野翁《试验方》：临杖预服无名异末，临时温酒服三五钱，则杖不甚痛，亦不甚伤。\n\n除折伤肿毒外，无他用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"无名异"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '12、无名异', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qQUp5Eoz86m', 4, '{"title":"第400105311条・卷之三_玉石部上品","description":"<p>11、赤石脂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105311,"note":"           味甘、酸、辛，大温，无毒。主养心气，明目益精，疗腹痛泄澼，下痢赤白，小便利，及痈疽疮痔，女子崩中漏下，产难胞衣不出。久服补髓好颜色，益智不饥，轻身延年。（白石脂功用大略相同。石脂有五色，旧经同一条，今用唯赤、白二者，余皆不用。）\n\n          疏：赤石脂禀土金之气，而色赤则象火，故其味甘酸辛，气大温无毒。气薄味厚，降而能收，阳中阴也。入手阳明大肠，兼入手足少阴经。《经》曰：涩可去脱。大小肠下后虚脱，非涩剂无以固之，故主腹痛肠澼，及小便利，女子崩中漏下也。赤者南方之色，离火之象，而甘温则又有入血益血之功，故主养心气，及益精补髓，好颜色也。血足则目自明，心气收摄则得所养而下交于肾，故有如上功能也。痈疽因荣气不从所生，疮痔因肠胃湿热所致，甘温能通畅血脉，下降能涤除湿热，故主之也。其主难产胞衣不出者，以其体重下降，而酸辛能化恶血，恶血化则胞胎无阻滞之患矣。东垣所谓：胞衣不出，涩剂可以下之。此之谓也。不饥轻身延年，乃方士炼饵之法耳。凡泄利肠澼，久则下焦虚脱，无以闭藏。其他固涩之药，性多轻浮，不能达下，惟石脂体重而涩，直入下焦阴分，故为久利泄澼之要药。\n\n【主治参与】\n       《和剂局方》冷痢腹痛，下白冻如鱼脑者，桃花丸主之：赤石脂煅研，干姜炮，等分为末，蒸饼为丸。量大小服，日三服。\n\n仲景方：伤寒下利，便脓血不止，桃花汤主之。赤石脂一斤，一半全用，一半末用，干姜一两，粳米半斤，水七升，煮米熟，去滓。每服七合。纳末方寸匕，日三服，愈乃止。\n\n《千金翼方》：痰饮吐水无时节者，其原因冷饮过度，遂令脾胃气弱，不能消化饮食，饮食入胃，皆变成冷水，反吐不停，赤石脂散主之。赤石脂一斤，捣筛，服方寸匕，酒食自任，稍加至三匕。服尽一斤，则终身不吐痰水，又不下利，补五脏，令人肥健。有人患痰饮，服诸药不效，用此遂愈。病人虚者宜之。\n\n【简误】\n      火热暴注者，不宜用。滞下全是湿热，于法当忌。自非的受寒邪、下利白积者，不宜用。崩中，法当补阴清热，不可全仗收涩。滞下本属湿热积滞，法当祛暑除积，止涩之药定非所宜。慎之！慎之！","videoMemo":"","fangList":[],"bieMing":"赤石脂"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '11、赤石脂', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y3QrA6l3wcD', 4, '{"title":"第400105310条・卷之三_玉石部上品","description":"<p>10、紫石英</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105310,"note":"      味甘、辛，温，无毒。主心腹咳逆邪气，补不足，女子风寒在子宫，绝孕十年无子，疗上气，心腹痛，寒热邪气结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。久服温中，轻身延年。\n\n      疏：紫石英禀土中之阳气以生，《本经》味甘，气温，无毒。《别录》加辛。雷公言大温。独李当之言大寒者，是昧其性矣。味厚于气，阳中之阴，降也。入手少阴、手厥阴、足厥阴经。少阴主心，属阳而本热，虚则阳气衰而寒邪得以乘之，或为上气咳逆，或为气结寒热心腹痛。此药温能除寒，甘能补中，中气足，心得补，诸证无不瘳矣。惊悸属心虚，魂魄不安亦由心君怯弱，无以镇压诸经。兹得镇坠之力，而心君有以镇摄，即重以去怯之义也。其主女子风寒在子宫，绝孕无子者，盖女子系胎于肾及心包络，皆阴脏也，虚则风寒乘之而不孕，非得温暖之气，则无以祛风寒而资化育之妙。此药填下焦，走肾及心包络，辛温能散风寒邪气，故为女子暖子宫之要药。补中气，益心肝，通血脉，镇坠，虚火使之归元，故又能止消渴，散痈肿，令人悦泽，及久服轻身延年也。凡入丸散，用火煅醋淬七次，研末水飞过，晒干入药。\n\n【主治参与】\n          同白薇、艾叶、白胶、当归、山茱萸、川芎、香附，治女人子宫虚寒，绝孕无子。\n\n张文仲《备急方》虚劳惊悸，补虚止惊，令人能食：紫石英五两，打如豆大，水淘一遍，以水一斗，煮取三升，细细服。\n\n仲景《金匮方》治风热瘈疭及惊痫，风引汤：紫石英、白石英、寒水石、石膏、干姜、大黄、龙齿、牡蛎、甘草、滑石等分，㕮咀，水一升，煎去三分，食后温呷，无不效者。\n\n【简误】\n         紫石英，其性镇而重，其气暖而补，故心神不定，肝血不足，及女子血海虚寒不孕者，诚为要药。然而止可暂用，不宜久服，凡系石类皆然，不独石英一物也。妇人绝孕由于阴虚火旺，不能摄受精气者忌用。","videoMemo":"","fangList":[],"bieMing":"紫石英"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '10、紫石英', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GWF6VeRR17S', 4, '{"title":"第400105309条・卷之三_玉石部上品","description":"<p>9、空青</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105309,"note":"       味甘、酸，寒、大寒，无毒。主青盲耳聋，明目，利九窍，通血脉，养精神，益肝气，疗目赤痛，去肤翳，止泪出，利水道，下乳汁，通关节，破坚积。久服轻身延年不老，令人不忘，志高神仙。能化铜铁铅锡作金。生益州山谷，及越巂山有铜处。铜精熏则生空青，其腹中空。三月中旬采，亦无时。\n\n       疏：空青感铜之精气而结，其味甘酸，其气大寒，无毒可知已。色青法木，故入肝而主目盲。目者肝之窍，瞳子神光属肾，肝肾虚则内热，怒则火起于肝，故生内外障翳，此目病所由成也。甘寒能除积热，兼之以酸，则火自敛而降矣。热退则障自消，目自明。耳者肾之窍，水涸火炎故耳聋，肾家热解则火息水生而听复聪矣。九窍不利，无非火壅。肝家有火则血热气逆，故血脉不通。凉肝除热则精气自益，阴足火清，则窍自利而血脉自通，精神自长矣。目赤痛，肤翳泪出，皆肝气不足之候，益肝气则诸证自除矣。其曰利水道，下乳汁，通关节，破坚积者，皆以热除则气血和平，阴气自复，五脏清宁则诸证自解。圣药神功，于斯显矣。\n\n【主治参与】\n空青得真珠、贝子、珊瑚、石决明，点目中内外障翳有神。\n\n《千金方》：眼目不明，空青少许，渍露一宿，点。\n\n《圣济总录》：肤翳昏暗，空青二钱，蕤仁去皮一两，片脑三钱，细研，日点。明目去翳障。\n\n上珍之药，一时难构。明目外，无别用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"空青"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '9、空青', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SX4VdOMswKV', 4, '{"title":"第400105308条・卷之三_玉石部上品","description":"<p>8、滑石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105308,"note":"         味甘，寒、大寒，无毒。主身热泄澼，妇子乳难，癃闭，利小便，荡胃中积聚寒热，益精气，通九窍，六府津液，去留结，止渴，令人利中。久服轻身耐饥长年。（石韦为之使，恶曾青。）\n\n        疏：滑石，石中之得冲气者也。故味甘淡，气寒而无毒。入足太阳膀胱经，亦兼入足阳明、手少阴、太阳、阳明经。用质之药也。滑以利诸窍，通壅滞，下垢腻；甘以和胃气，寒以散积热。甘寒滑利以合其用，是为祛暑散热，利水除湿，消积滞，利下窍之要药。《本经》用以主身热泄澼，女子乳难，荡胃中积聚寒热者，解足阳明胃家之热也。利小便癃闭者，通膀胱，利阴窍也。其曰益精气、久服轻身、耐饥长年，此则必无是理矣。《别录》：通九窍津液，去留结，止渴，令人利中者，湿热解，则胃气和而津液自生；下窍通，则诸壅自泄也。丹溪用以燥湿，分水道，实大肠，化食毒，行积滞，逐瘀血，解燥渴，神脾胃，降心火，偏主石淋，皆此意耳。\n\n【主治参与】\n          和甘草为益元散，又名天水散、六一散、太白散：解中暑、伤寒、疫疬，并汗后遗热、劳复诸疾，兼解两感伤寒，百药、酒食、邪热毒，烦满短气，腹胀闷痛，淋閟涩痛，疗身热呕吐泄泻，肠澼下痢赤白，除烦热，胸中积聚寒热，止渴消蓄水。妇人催生下乳，治吹乳，乳痈，牙疮，齿疳。此药大养脾胃之气，通九窍六腑，去留结，通经脉，消水谷，安魂定魄，乃神验之仙药也。\n\n刘河间《伤寒直格》本方：白滑石水飞过六两，粉甘草一两，为末。每服三钱，蜜少许，温水调下。实热则用新汲水调下，解利则葱豉汤下，通乳用猪肉面汤调下，催生用香油浆水调下。凡难产或死胎不下，皆由风热燥涩，结滞紧敛，不能舒缓故也。此药力至，则结滞顿开而瘥矣。如用以治痢，照雷公炮制：用牡丹皮同煮过，加丹砂水飞细末，每两一钱，名辰砂六一散。治心经伏暑，下痢纯血，烦躁口渴，神昏不爽。\n\n《圣惠方》治膈上烦热多渴，利九窍，滑石二两，捣水三大盏，煎二盏，去滓，入粳米煮粥食。\n\n《千金方》治女劳黄疸，日晡发热恶寒，少腹急，大便溏黑，额黑。滑石、石膏等分，研末。大麦汁服方寸匕，日三，小便大利，愈。腹满者难治。\n\n《圣惠方》治乳石发动，烦热烦渴：滑石粉半两，水一盏，绞白汁，顿服。\n\n《广利方》：气壅关格不通，小便淋结，脐下妨闷兼痛：滑石粉水调服一两。\n\n杨氏《产乳》：小便不通。滑石末一升，车前汁和涂脐之四畔，方四寸，干即易之。冬月水和。\n\n《圣惠方》治妇人转脬，因过忍小便而致：滑石末，葱汤服二钱。\n\n《普济方》伏暑水泄，白龙丸：滑石火煅过一两，硫黄四钱，为末，面糊丸绿豆大。每用淡姜汤随大小服。又方：治伏暑或吐，或泻，或疟，小便赤，烦渴。玉液散：用桂府滑石烧四两，藿香一钱，丁香一钱，为末，米汤服二钱。亦治霍乱。\n\n王氏《痘疹方》治痘疮狂乱，循衣摸床，大渴引饮，用益元散一两，加朱砂飞过二钱，冰片三分，麝香一分，用灯心汤调二三钱服。\n\n《普济方》治风毒热疮，遍身出黄水。桂府滑石末傅之，次日愈。先以虎杖、豌豆、甘草等分，煎汤洗后乃搽。\n\n《集简方》治脚指缝烂：滑石一两，石膏煅半两，枯矾少许，研掺之。\n\n夏子益《奇疾方》，载白矾石条内。\n\n【简误】\n        滑石本利窍去湿，消暑除热，逐积下水之药。若病人因阴精不足内热，以致小水短少赤涩或不利；烦渴身热，由于阴虚火炽水涸者，皆禁用。脾肾俱虚者，虽作泄，勿服。","videoMemo":"","fangList":[],"bieMing":"滑石"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '8、滑石', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gXz72RFEkKM', 4, '{"title":"第400105307条・卷之三_玉石部上品","description":"<p>7、玄明粉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105307,"note":"        味辛、甘，性冷，无毒。治心热烦躁，并五藏宿滞癥结，明目，退膈上虚热，消肿毒。此即朴硝炼成者。\n\n        疏：玄明粉，即芒硝投滚汤沸化，夜置冰霜之下，结起在水面上者。用白莱菔切片，煮汁投硝，以结起多次者为上。其色莹白，其味辛咸，沉而降，阴也。入手少阴、足厥阴、阳明经。其治邪热在心烦躁者，《经》曰：热淫于内，治以咸寒，佐之以苦。并主五藏宿滞癥结者，即燥粪、结痰、瘀血、宿食之谓。辛能散结，咸能软坚，兼能润下，苦能下泄，故主之也。目为血热所侵，必赤肿作痛异常，硝物峻利，加以苦辛咸寒之极，故能散热结，逐热血。目病既去，必自明矣。退膈上虚热者，当作实热。邪解心凉，故热退也。消肿毒者，即软坚散结之功也。\n\n【主治参与】\n《集简方》热厥气痛：玄明粉三钱，热童便调下。\n\n《伤寒蕴要》伤寒发狂，玄明粉二钱，朱砂一钱，末之，冷水服。\n\n《圣济总录》鼻血不止：玄明粉二钱，冷水服。\n\n【简误】\n硝者，消也。五金八石，其坚莫比，惟硝能销之。苟非大辛、至咸、极苦、最烈之味，其能消化之乎？消石、朴硝，一经澄炼，便名芒硝、马牙硝、风化硝、甜硝。若经煅过，即名玄明粉。究其功用，无坚不磨，无结不散，无热不荡，无积不推，可谓直往无前，物无留碍之性也。《别录》谓炼饵服之，轻身神仙，失其本矣。故仲景于诸承气汤用之，非邪结下焦、坚实不可按者不用。恐其误伐下焦真阴故也。病不由于邪热深固，闭结难通，断不可轻投。至于血涸津枯，以致大肠燥结，阴虚精乏，以致大热骨蒸；火炎于上，以致头痛目昏，口渴耳聋咽痛，吐血衄血，咳嗽痰壅，虚极类实等证，切戒勿施！庶免虚虚之咎，而无悔不可追之大错也。至如唐玄宗所召道士刘玄真，谓服玄明粉，遂无病长生中所载有益精壮气，助阳补阴，不拘丈夫妇人，幼稚襁褓，不问四时冷热俱治之说，乃是荒唐不经之语。不识本章，何缘载人？岂历代董修儒臣，本不知医，但广异闻，未暇核实而误收之耶？正所谓尽信书，则不如无书也。","videoMemo":"","fangList":[],"bieMing":"玄明粉"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '7、玄明粉', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L7wEaE9z7w4', 4, '{"title":"第400105306条・卷之三_玉石部上品","description":"<p>6、朴硝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105306,"note":"        味苦、辛，寒，大寒，无毒。主百病，除寒热邪气，逐六府积聚，结固留癖，胃中食饮热结，破留血闭绝，停痰痞满，推陈致新。能化七十二种石。炼饵服之，轻身神仙。炼之白如银，能寒能热，能滑能涩，能辛能苦，能咸能酸。入地千岁不变。色青白者佳，黄者伤人，赤者杀人。\n\n        疏：朴硝乃初次煎成者，其气味烈于芒硝，主治皆同。总为除邪热，逐六腑积聚，结固留癖，胃中食饮停滞因邪热结，停痰痞满，破留血闭绝之要药。与芒硝功用曾无少别，文具芒硝条下，兹不复疏。\n【主治参与】\n《圣惠方》治时气头痛不止，用朴硝二两，捣罗为散，用生油调涂于顶上。又方：治乳石发动烦闷，及诸风热，用朴硝炼成者半两，细研如粉，每服以蜜水调下一钱匕，日三四服。\n\n《简要济众》治小便不通膀胱热。白花散：朴硝不以多少，研为末，每服二钱匕，温茴香酒调下，无时服。\n\n入紫雪：疗伤寒，温疫，温疟，一切积热烦热，狂呼叫走，瘴疫毒疠，卒死脚气，五尸五注，心腹诸疾，㽲刺切痛，解诸热毒，邪热发黄，蛊毒鬼魅，野道热毒，小儿惊痫百病：黄金一百两，石膏、寒水石、磁石、滑石各三斤，捣碎，水一斛，煮四斗，去滓。入犀角屑、羚羊角屑、青木香、沉香各五两，玄参洗焙、升麻各一斤，炙甘草八两，丁香一两，入前汁中，煮取一斗五升，去滓。入炼朴硝十斤，硝石三十二两，于药汁中微火煎之，用柳木不住搅，至水气欲尽，倾水盆中。待欲凝，入麝香一两二钱半，朱砂末三两，搅匀收之。每服一二钱，凉水服。临时加减，甚者一两。\n\n碧雪：治一切积热，天行时疾，发狂昏愦，或咽喉肿塞，口舌生疮，心中烦躁，或大小便不通，胃火诸病。朴硝、芒硝、马牙硝、石膏水飞、寒水石水飞各一斤，以甘草一斤，煎水五升，入诸药同煎，不住手搅，令消熔得所，入青黛一斤，和匀，倾盆内，经宿结成雪。为末，每含咽，或吹之，或水调服二三钱。欲通利，则热水服一两。\n\n刘禹锡《传信方》治热壅，甘露饮：凉胸膈，驱积滞。芒硝末一大斤，用蜜十二两，和匀，入新竹筒内，半筒已上即止，不得令满。却入炊甑中，令有药处在饭内，其虚处出在上，蒸之。候饭熟，取出，绵滤入磁缽内，竹篦搅匀勿停手，待凝，取入磁盒。每卧时含半匙，渐渐咽之。如要通利，即多服之。\n\n《简便方》治赤眼肿痛：朴硝置豆腐上蒸化，取汁收点。\n\n《外台秘要》治喉痹肿痛：用朴硝一两，细细含咽，立效。或加丹砂一钱。气塞不通，加生甘草二钱半，吹之。\n\n孙真人方：治口舌生疮，用朴硝含之良。\n\n夏之益《奇疾方》：灸疮飞蝶，因艾灸火疮痂退落，疮内鲜肉片子飞如蝶状，腾空飞去，痛不可言，是血肉俱热怪病也。用朴硝、大黄各半两，为末，水调下，微利即愈。\n\n《史记・仓公传》云：菑川王美人，怀子不乳，来召淳于意。意往，饮以莨菪药一撮，以酒饮之，旋乳。意复诊其脉躁，躁者，有余病，即饮以消石一剂，出血豆比五六枚而安。此去蓄血之验也。\n\n《炮炙论》治头痛欲死，用消石末吹鼻中即愈。\n\n《圣惠方》治赤眼肿痛。用消石末，临卧时，以铜箸点黍米大，入目眦，至旦，以盐水洗去之。","videoMemo":"","fangList":[],"bieMing":"朴硝"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '6、朴硝', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M95KWjzOUlV', 4, '{"title":"第400105305条・卷之三_玉石部上品","description":"<p>5、芒硝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105305,"note":"         味辛、苦，大寒。主五藏积聚，久热胃闭，除邪气，破留血，腹中痰实结搏，通经脉，利大小便及月水，破五淋，推陈致新。生于朴硝。\n\n          疏：芒硝禀天地至阴极寒之气所生，故味苦辛，性大寒。乃太阴之精，以消物为性，故能消五金八石，况乎五脏之积聚，其能比之金石之坚哉？久热即是邪热，伤寒热邪结中焦，或停饮食则胃胀闭，少少投之，可立荡除。除邪气者，寒能除热故也。破留血者，咸能软坚，辛能散结也。邪热盛则经脉闭，热淫于内，治以咸寒，结散热除则经脉自通，二便自利，月水复。此五淋中，惟石淋、膏淋为胶结难解。病由于积热，非得辛苦大寒之药，以推荡消散之，不能除也。推陈致新，总述其体用之功耳。由朴硝再煎而成，故曰生于朴硝。\n\n【主治参与】\n入仲景大承气汤，治伤寒七八日后，邪结下焦，少腹按之坚痛，下之愈。\n\n又治伤寒邪热失汗，蓄血少腹，或先因内伤留血下焦，入桃仁承气汤，下之愈。\n\n《千金方》疗漆疮，用汤渍芒硝令浓，涂之。如干即易之。\n\n《子母秘录》治小儿赤游，行于体上下，至心即死：以芒硝纳汤中，取浓汁以拭丹上。\n\n《百一选方》治疗关格，大小便不通，胀满欲死，两三日则杀人：以芒硝三两，纸裹三四重，炭火烧之，令内一升汤中尽服，当先饮汤一升已，吐出乃服之。\n\n《孙真人食忌》：主眼有翳：取芒硝一大两，置铜器中，急火上炼之，放冷后，以生绢细罗，点眼角中。每夜欲卧时一度点，妙。\n\n姚和众方：治小儿重舌：马牙硝涂于舌上下，三日效。《简要济众方》治小儿鹅口。用马牙硝擦舌上，日五度，效。《梅师方》治火焰丹毒，水调芒硝末涂之。\n\n《信效方》治死胎不下。用芒硝末二钱，童便温服。\n\n《三因方》：治风热喉痹及缠喉风。玉钥匙：用焰硝一两半，白僵蚕一钱，白硼砂半两，脑子一字，研匀，取少许，数数吹之。\n\n《普济方》治重舌、鹅口，用竹沥同焰硝点之。","videoMemo":"","fangList":[],"bieMing":"芒硝"}}', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '2024-12-23T09:33:53.000Z', '5、芒硝', '2024-12-23T09:33:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9bBR1z4YSBd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j7E1DLz9HSv', 4, '{"title":"第400105418条・卷之四_玉石部中品","description":"<p>18、胡燕巢内土</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105418,"note":"        无毒。主风瘙瘾疹，及恶刺疮、浸淫疮遍身至心者死，并水和傅之。\n\n          疏：胡燕，即玄鸟，春分后至。窠取四方湿土为之，其气味必甘寒，故藏器以之疗诸疮疡。盖诸痛痒疮疡，皆属心火，而甘寒最能解火毒，土性能化一切毒故也。\n\n【主治参与】\n        入回燕膏，贴瘰疬有效。回燕者，朝北燕窠土也。","videoMemo":"","fangList":[],"bieMing":"胡燕巢内土"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '18、胡燕巢内土', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AJlvZkgCQbn', 4, '{"title":"第400105417条・卷之四_玉石部中品","description":"<p>17、土蜂巢内土</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105417,"note":"          本经无气味，云主肿毒，醋和为泥傅之。亦主蜘蛛咬，必是甘平无毒之物。甘为土化，故能解诸毒也。","videoMemo":"","fangList":[],"bieMing":"土蜂巢内土"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '17、土蜂巢内土', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HVRxr7kVjHI', 4, '{"title":"第400105416条・卷之四_玉石部中品","description":"<p>16、太阴玄精</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105416,"note":"        味咸，温，无毒。主除风冷邪气湿痹，益精气，妇人痼冷漏下，心腹积聚冷气，止头疼，解肌。其色青白，龟背者良。\n\n       疏：太阴玄精出于盐卤之地，及至阴之精凝结而成。故其形皆六出，象老阴之数也。本经味咸气温无毒，然详其所主，味应带辛，气应作寒。非辛寒则不能除风冷邪气湿痹，及止头疼、解肌等证。咸能软坚，故主心腹积聚。咸能润下，入肾滋水，故主益精气。本经误认为温，故有妇人痼冷漏下冷气之治，皆非所宜也。\n\n【主治参与】\n《图经本草》正阳丹：治伤寒三日，头疼壮热，四肢不利。太阴玄精石、硝石、硫黄各二两，蓬砂一两，细研，入瓶固济，以火半斤，于瓶子周一寸（火办）之，约近半日，候药青紫色，住火，待冷取出，用腊月雪水拌匀，入罐子中，屋后北阴下阴干。又入地埋二七日，取出研细，面糊丸鸡头实大。先用热水浴后，以艾汤研下一丸。以衣盖，汗出为瘥。\n入来复丹，治缓急诸病，但有胃气，无不获安。\n【简误】\n伤寒阴证不宜服。咸能走血，用以引经入肾则可，多则反泻肾伤血矣。血病无多食咸，戒之。","videoMemo":"","fangList":[],"bieMing":"太阴玄精"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '16、太阴玄精', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E3oI267VNXl', 4, '{"title":"第400105415条・卷之四_玉石部中品","description":"<p>15、玛瑙</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105415,"note":"    味辛，寒，无毒。主辟恶，熨目赤烂。\n\n   疏：玛瑙，玉之属也。观陈藏器云 “砑木不热”，其性寒可知矣。寒而带辛，故能辟恶，及熨目赤烂也。同珊瑚辈为末点目，去障翳尤妙。","videoMemo":"","fangList":[],"bieMing":"玛瑙"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '15、玛瑙', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DRux1Se2rHz', 4, '{"title":"第400105414条・卷之四_玉石部中品","description":"<p>14、珊瑚</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105414,"note":"       味甘，平，无毒。主宿血，去目中翳。鼻衄，末吹鼻中。\n\n        疏：珊瑚得水中阴气以生，味甘气平，性主消散，故能去目中翳，及消宿血、止鼻衄也。\n\n【主治参与】\n      同贝子、真珠、玛瑙、琥珀、石蟹，为极细末，点入目中，去浮翳。","videoMemo":"","fangList":[],"bieMing":"珊瑚"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '14、珊瑚', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GVYsiD9NnMQ', 4, '{"title":"第400105413条・卷之四_玉石部中品","description":"<p>13、铁落</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105413,"note":"       味辛、甘，平，无毒。主风热恶疮，疡疽疮痂疥，气在皮肤中，除胸膈中热气，食不下，止烦，去黑子。可以染皂。\n\n        疏：铁落是煅家烧铁赤沸，砧上煅之，如皮甲落下者。本出于铁，不离金象，体重而降。故《素问》有生铁落饮，以疗病狂怒者，云生铁落，下气疾也。又狂怒属肝气暴升，故取金气以制之也。其主气在皮肤中，及除胸膈中热气，食不下，止烦者，皆制木散热之功也。《本经》又主风热恶疮，疡疽疮痂疥者，皆肝心火热所致，辛平能除二经之火热，故主之也。苏恭以之炒热投酒中饮，疗贼风痉。大明治惊邪癫痫，小儿客忤，并煎服之，悉此意耳。\n\n【主治参与】\n         铁秤锤烧红，淬入米泔中百次，乘热熏洗阴癣顽疮，皆有效。别敷杀虫凉血药弥佳。","videoMemo":"","fangList":[],"bieMing":"铁落"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '13、铁落', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yOTjj7KSFPs', 4, '{"title":"第400105412条・卷之四_玉石部中品","description":"<p>12、蜜陀僧</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105412,"note":"       味咸、辛，平，有小毒。主久痢，五痔，金疮。面上瘢䵟，面膏药用之。（旧出南闽中银铜冶处，今甚难得，但取煎销银铺炉底用之。）\n\n         疏：蜜陀僧感银铜之气而结，故其味咸辛，气平有小毒。久痢，五痔，大肠湿热积滞也。辛主散结滞，咸主润下除热。大肠清宁，则久痢、五痔自瘳矣。体重，能消磨坚积；味咸，能入血凉血，故又主金疮，及灭面上瘢䵟也。\n\n【主治参与】\n        《圣惠方》鼻皶赤皰：蜜陀僧二两，细研，人乳调，夜涂旦洗。\n\n《活人心鉴》夏月汗癍如疹：用蜜陀僧八钱，雄黄四钱，先以姜片擦热，仍以姜片蘸末擦之，次日即焦。\n\n《寿域方》：骨疽出骨，一名多骨疮，不时出细骨。乃母受胎未及一月，与六亲骨肉交合，感其精气，故有多骨之名。以蜜陀僧末，桐油调匀，摊贴之，即愈。\n\n【简误】\n        蜜陀僧惟治䵟，傅面外，今人无复用以服食者。大都可外傅，不可内服。此药难得真者，销银炉底，乃销铜之气所结，能烂一切物，故益不宜轻用。","videoMemo":"","fangList":[],"bieMing":"蜜陀僧"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '12、蜜陀僧', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c9YVcHJwGcm', 4, '{"title":"第400105411条・卷之四_玉石部中品","description":"<p>11、阳起石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105411,"note":"           味咸，微温，无毒。主崩中漏下，破子藏中血，癥瘕结气，寒热腹痛，无子，阴痿不起，补不足，疗男子茎头寒，阴下湿痒，去臭汗，消水肿。久服不饥，令人有子。（白色莹明若狼牙者为上，凡用，火煅酒淬七次，研细水飞，日干。）\n\n        疏：阳起石禀纯阳之气以生。《本经》味咸，气微温，无毒。观《图经》所载：齐州阳起山，其山常有暖气，虽盛冬大雪遍境，独此山无少积，盖石气熏蒸也。其为气之温暖，当不甚微矣。味咸而气温，入右肾命门，补助阳气，并除积寒宿血留滞下焦之圣药，故能主崩中漏下，及破子脏中血，癥瘕结气，寒热腹痛，及男子茎头寒，阴痿不起，阴下湿痒，令人有子也。真阳足则五脏之气充溢，邪湿之气外散，故久服不饥，并去臭汗也。《别录》又主消水肿者，盖指真火归元，则能暖下焦，熏蒸糟粕，化精微，助脾土以制水也。\n\n【主治参与】\n          同破故纸、鹿茸、腽肭脐、菟丝子、狗阴茎、肉苁蓉、巴戟天，治命门虚寒，阴痿不起，精寒无嗣。服之能令阳道丰隆，使人有子。总治男子九丑之疾。\n\n【简误】\n       阴虚火旺者，忌之。阳痿属于失志，以致火气闭密，不能发越而然，及崩中漏下由于火盛，而非虚寒者，并不得服。","videoMemo":"","fangList":[],"bieMing":"阳起石"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '11、阳起石', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vXEl03MK3w4', 4, '{"title":"第400105410条・卷之四_玉石部中品","description":"<p>10、凝水石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105410,"note":"        味辛、甘，寒、大寒，无毒。主身热，腹中积聚邪气，皮中如火烧，烦满，水饮之。除时气热盛，五脏伏热，胃中热，烦满，止渴，水肿，小腹痹。久服不饥。一名寒水石，一名白水石。色如云母，可析者良。盐之精也。（石膏亦名寒水石，与此不同。）\n\n       疏：凝水石生于卤地，禀积阴之气而成。《本经》味辛气寒。\n\n      《别录》加甘、大寒无毒。《经》曰：小热之气，凉以和之；大热之气，寒以取之。又曰：热淫于内，治以咸寒。大寒微咸之性，故主身热邪气，皮中如火烧，烦满，及时气热盛，五脏伏热，胃中热也。易饥作渴，亦胃中伏火也。甘寒除阳明之邪热，故能止渴不饥。水肿者，湿热也。小便多不利，以致水气上溢于腹，而成腹痹。辛咸走散之性，故能除热利窍消肿也。疗腹中积聚者，亦取其辛散咸软之功耳。\n\n【主治参与】\n《永类方》男女转脬，不得小便：寒水石二两，滑石一两，葵子一合，为末，水一斗，煮五升，时服一升，即利。\n\n《经验方》：小儿丹毒，皮肤热赤：寒水石半两，白土一分，为末，米醋调涂之。\n\n【简误】\n       凝水石，按本文云 “盐之精”，则与石膏、方解石大相悬绝矣。因石膏有寒水石之名，而王隐君复云寒水石又名方解石，以致混淆难辨。其功能各不相同，用者自宜分别。生卤地，味辛咸，碎之如朴硝者，是凝水石。其气大寒，能除有余邪热。凡阴虚火旺，咳嗽吐血多痰，潮热骨蒸，并脾胃作泄者，不宜服。《经》曰 “诸腹胀大，皆属于热” 者，宜之；“诸湿肿满，属脾土” 者，忌之。大宜详审，慎勿有误。","videoMemo":"","fangList":[],"bieMing":"凝水石"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '10、凝水石', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fm8vggUXv7D', 4, '{"title":"第400105409条・卷之四_玉石部中品","description":"<p>9、磁石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105409,"note":"        味辛、咸，寒，无毒。主周痹，风湿肢节中痛，不可持物，洗洗酸痟。除大热烦满，及耳聋。养肾脏，坚骨气，益精除烦，通关节，消痈肿鼠瘘，颈核喉痛，小儿惊痫。炼水饮之，亦令人有子。一名玄石。（即吸铁石。入药须火烧醋淬，研末水飞，或醋煮三日夜。）\n\n         疏：磁石生于有铁处，得金水之气以生。《本经》：味辛，气寒，无毒。\n\n     《别录》、甄权：咸，有小毒。大明：甘、涩，平。藏器：咸，温。今详其用，应是辛咸微温之药，而甘寒非也。气味俱厚，沉而降，阳中阴也。入足少阴，兼入足厥阴经。其主周痹风湿，肢节中痛，不可持物，洗洗酸者，皆风寒湿三气所致，而风气尤胜也。风淫末疾，发于四肢，故肢节痛不能持物。风湿相搏，久则从火化，而骨节皮肤中洗洗酸也。辛能散风寒，温能通关节，故主之也。咸为水化，能润下软坚。辛能散毒，微温能通行除热，故主大热烦满，及消痈肿鼠瘘。颈核喉痛者，足少阳、少阴虚火上攻所致，咸以入肾，其性镇坠而下吸，则火归元而痛自止也。夫肾为水脏，磁石色黑而法水，故能入肾养肾脏。肾主骨，故能强骨。肾藏精，故能益精。肾开窍于耳，故能疗耳聋。肾主施泄，久秘固而精气盈溢，故能令人有子。小儿惊痫，心气怯，痰热盛也，咸能润下，重可去怯，是以主之。甄权云：补男子肾虚，风虚身强，腰中不利，加而用之。宗奭云：养肾气，填精髓，肾虚耳聋目昏者，皆用之。\n\n【主治参与】\n《直指方》耳卒聋闭：吸铁石半钱，入病耳内，铁砂末入不病耳内，自然通透。\n\n《千金方》阳事不起：磁石五斤，研，清酒渍二七日。每服三合，日三夜一。\n\n倪维德《原机启微集》：眼昏内障，神光宽大渐散，昏如雾露中行，渐睹空花，物成二体，久则光不收及内障。磁朱丸：真磁石火煅醋淬七次二两，朱砂一两，神曲生用三两，为末。更以神曲末一两煮糊，加蜜丸梧子大。每服二十丸，空心饭汤下。\n\n《千金方》金疮血出：磁石末傅之，止痛断血。\n\n诸药石皆有毒，且不宜久服，独磁石性禀冲和，无猛悍之气，更有补肾益精之功，故不著 “简误”。大都渍酒优于丸散，石性体重故尔。","videoMemo":"","fangList":[],"bieMing":"磁石"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '9、磁石', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bqqfwE40JGX', 4, '{"title":"第400105408条・卷之四_玉石部中品","description":"<p>8、水银粉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105408,"note":"       味辛，冷，无毒。主通大肠，傅小儿疳并瘰疬，杀疮疥癣虫，及鼻上酒皶，风疮瘙痒。又名汞粉，轻粉，腻粉。（畏磁石、石黄，忌一切血。本出与丹砂故也。土茯苓、黑铅、铁浆，可制其毒。）\n\n      疏：水银粉，升炼水银而成。其味本辛，气冷，无毒。疗体与水银相似，第其性稍轻浮尔。大肠热燥则不通。小儿疳痹因多食甘肥，肠胃结滞所致，辛凉总除肠胃积滞热结，故主之也。其主瘰疬疮疥癣虫，及鼻上酒皶，风疮瘙痒者，皆从外治，无非取其除热杀虫之功耳。\n\n升炼轻粉法：用水银一两，白矾二两，食盐一两，同研不见星，铺于铁器内，以小乌盆覆之，盐泥封固盆口，以炭火打三炷香，取开，则粉升于盆上矣。\n\n【主治参与】\n《活幼口议》：小儿哯乳不止，服此立效。腻粉一钱，盐豉七粒去皮，研匀，丸麻子大。每服三丸，藿香汤下。\n\n《经验方》小儿吃泥，䑋肚：用腻粉一分，砂糖和丸，麻子大。空心米饮下一丸，良久，泄出泥土瘥。\n\n《圣惠方》大小便闭，胀闷欲死，二三日则杀人：腻粉一钱，生麻油一合，相和空心服。\n\n万表《积善堂方》下疳阴蚀疮：轻粉末干掺之，即结靥而愈。\n\n《永类钤方》臁疮不合：葱汁调轻粉傅之。\n\n又秘法升丹灵药方：治痈疽恶疮，杨梅诸疮，拔毒长肉，神验。水银一两，黑铅七钱，朱砂、雄黄各三钱，白矾、火硝各二两半，其法先用铅化开，投水银，凝成饼，入朱砂、雄黄研匀，然后将硝、矾熔化，投前四味末入内，离火急搅令匀，用阳城罐盛之，铁盏盖口上，架铁梁，铁线扎紧，盐泥固济，神仙炉内文武火升炼，盏中时时以水擦之，火渐加，以三分为率。每焚官香一炷，则加一分。如是炼三炷官香为度，候冷，取开，于盏底刮取，研如飞面，甘草汤飞过三次，入龙脑香少许，点广疮上。数数以指蘸药按之。三日自脱，神方也。\n\n【简误】\n         水银粉下膈涎，消积滞，并小儿涎潮瘈疭药多用。然而其性有毒，走而不守，若服之过剂，或不得当，则毒气熏蒸，窜入经络筋骨，莫之能出。痰涎既去，血液随亡，筋失所养，营卫不从，变为筋挛骨痛，或结肿块漏疮，或手足皲裂顽痹等证，遂成痼疾，贻害无穷。盖此物本成于汞，则汞之毒尚存。又得火煅，则火之毒气未出。《本经》言其无毒，误也。凡闭结由于虚，血不能润泽；小儿疳病，脾胃两虚；小儿慢惊，痰涎壅上；杨梅结毒，发于气虚；久病之人，咸不宜服。宗奭有云：病属于惊，尤须审谨。盖惊为心气不足，不可下，下之里虚。惊气入心不可治，其人本虚，便须禁此。慎之至也。","videoMemo":"","fangList":[],"bieMing":"水银粉"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '8、水银粉', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NA99Irlu4O6', 4, '{"title":"第400105407条・卷之四_玉石部中品","description":"<p>7、灵砂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400105407,"note":"        味甘，温，无毒。主五藏百病，养神，安魂魄，益气明目，通血脉，止烦满，益精神，杀精魅恶鬼气。久服通神明，不老轻身神仙，令人心灵。一名二气砂。\n\n        疏：灵砂，硫、汞制而成。及水火既济，二气交合，夺造化之功，窃阴阳之妙，可以变化五行，升降气血，为除邪养正，扶危救急之灵丹也。故能主五脏百病，益精神，安魂魄，及益气养神也。其主明目，通血脉，止烦满，杀精魅恶鬼气者，特其余事耳。得阴阳之妙，故能令人心灵。心灵则神明自通，不老轻身神仙所自来矣。又能主上盛下虚，痰涎壅盛，头旋吐逆，霍乱反胃，心腹冷痛诸证，更为镇坠之神丹也。\n\n修治：用水银一两，硫黄六铢，细研，炒作青砂头，后入水火既济炉，抽之如束针纹者，成就也。又按，胡演《丹药秘诀》云：升灵砂法：用新锅安逍遥炉上，蜜揩锅底，文火下烧，入硫黄二两熔化，投水银半斤，以铁匙急搅作青砂头。如有焰起，喷醋解之。待汞不见星，取出细研，盛入水火鼎内，盐泥固济，下以自然火升之。干水十二盏为度。取出束针纹者，成矣。\n\n【主治参与】\n钱氏《小儿方》：霍乱吐逆，不问虚实冷热。二气散，一名青金丹：用水银、硫黄等分，研不见星。每服一字，生姜汤调下。\n\n《直指方》冷气心痛。灵砂三分，五灵脂一分，为末，稀糊丸麻子大。每服二十丸，食前石菖蒲、生姜汤下。\n\n又方，九窍出血，因暴惊而得，其脉虚者，灵砂丹三十粒，人参汤下，三服愈。此证不可认作血得热则妄行而用凉药，误矣！何者？惊则气浮，神魂发越，阳气暴壅故也。得镇坠则神魂复安，而血自循经矣。\n\n《和剂局方》有养正丹，又名交泰丹，用黑铅、朱砂、水银、硫黄炒成，即灵砂意也。其用亦与灵砂略同。\n\n【简误】\n        灵砂虽称水火既济，阴阳配合，然而硫、汞有毒，性亦下坠，止可藉其坠阳交阴，却病于一时，安能资其养神益气，通灵于平日哉？凡胃虚呕吐，伤暑霍乱，肺热生痰，病属于虚，非关骤发者，咸在所忌。","videoMemo":"","fangList":[],"bieMing":"灵砂"}}', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '2024-12-24T02:27:51.000Z', '7、灵砂', '2024-12-24T02:27:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'uVOozA4CX5e');
